type TestHmacSha256 = Hmac<Sha256>;

enum ScriptedStep {
    Immediate(Result<Vec<ModelStreamEvent>, ProviderError>),
    AssertChannelLeaseBeforeRelease {
        state_root: PathBuf,
        channel_id: String,
        active_run_id: String,
        turn_id: String,
        superseded_run_id: Option<String>,
        superseded_turn_id: Option<String>,
        gate: Arc<Notify>,
        response: Result<Vec<ModelStreamEvent>, ProviderError>,
    },
    ReleaseAfter {
        gate: Arc<Notify>,
        response: Result<Vec<ModelStreamEvent>, ProviderError>,
    },
    ReleaseAfterPermit {
        gate: Arc<Semaphore>,
        response: Result<Vec<ModelStreamEvent>, ProviderError>,
    },
}

impl From<Result<Vec<ModelStreamEvent>, ProviderError>> for ScriptedStep {
    fn from(value: Result<Vec<ModelStreamEvent>, ProviderError>) -> Self {
        Self::Immediate(value)
    }
}

fn assert_channel_lease_persisted(
    state_root: &Path,
    channel_id: &str,
    active_run_id: &str,
    turn_id: &str,
    superseded_run_id: Option<&str>,
    superseded_turn_id: Option<&str>,
) -> Result<()> {
    let store = crate::channels::FileChannelStore::new(state_root);
    let leases = store.load_leases()?;
    let channel_leases = leases
        .get(channel_id)
        .ok_or_else(|| anyhow!("missing persisted channel leases for {channel_id}"))?;
    let lease = channel_leases
        .iter()
        .find(|lease| {
            lease.active_run_id.as_deref() == Some(active_run_id) && lease.turn_id == turn_id
        })
        .ok_or_else(|| {
            anyhow!(
                "missing persisted lease for run {active_run_id} turn {turn_id}: {channel_leases:#?}"
            )
        })?;
    anyhow::ensure!(
        lease.superseded_run_id.as_deref() == superseded_run_id,
        "unexpected superseded_run_id for recovered lease: {lease:#?}"
    );
    anyhow::ensure!(
        lease.superseded_turn_id.as_deref() == superseded_turn_id,
        "unexpected superseded_turn_id for recovered lease: {lease:#?}"
    );
    Ok(())
}

