struct ScriptedImageBackend;

#[async_trait]
impl crate::image_generation::ImageGenerationBackend for ScriptedImageBackend {
    fn provider(&self) -> &str {
        "openai"
    }

    async fn generate(
        &self,
        request: &crate::control_tools::GenerateImageToolRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        let media_type = match request.size.as_deref() {
            Some("jpeg") => "image/jpeg",
            _ => "image/png",
        };
        Ok(crate::image_generation::GeneratedImageBatch {
            provider: "openai".to_string(),
            model: "test-image-model".to_string(),
            images: vec![crate::image_generation::GeneratedImagePayload {
                media_type: media_type.to_string(),
                bytes: match media_type {
                    "image/jpeg" => sample_jpeg_bytes()?,
                    _ => sample_png_bytes()?,
                },
            }],
            revised_prompt: Some(request.prompt.clone()),
        })
    }

    fn supports_edit(&self) -> bool {
        true
    }

    async fn edit(
        &self,
        request: &crate::image_generation::ImageEditBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        let media_type = request
            .images
            .first()
            .map(|image| image.media_type.as_str())
            .unwrap_or("image/png");
        Ok(crate::image_generation::GeneratedImageBatch {
            provider: "openai".to_string(),
            model: "test-image-model".to_string(),
            images: vec![crate::image_generation::GeneratedImagePayload {
                media_type: media_type.to_string(),
                bytes: match media_type {
                    "image/jpeg" => sample_jpeg_bytes()?,
                    _ => sample_png_bytes()?,
                },
            }],
            revised_prompt: Some(format!("{}:{}", request.prompt, request.images.len())),
        })
    }
}

