#[async_trait]
impl crate::image_generation::ImageGenerationBackend for RecordingImageBackend {
    fn provider(&self) -> &str {
        "openai"
    }

    async fn generate(
        &self,
        _request: &crate::control_tools::GenerateImageToolRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        bail!("recording backend only supports edit requests")
    }

    fn supports_edit(&self) -> bool {
        true
    }

    async fn edit(
        &self,
        request: &crate::image_generation::ImageEditBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        self.recorded_file_names.lock().push(
            request
                .images
                .iter()
                .map(|image| image.file_name.clone())
                .collect(),
        );
        self.recorded_media_types.lock().push(
            request
                .images
                .iter()
                .map(|image| image.media_type.clone())
                .collect(),
        );
        Ok(crate::image_generation::GeneratedImageBatch {
            provider: "openai".to_string(),
            model: "recording-image-model".to_string(),
            images: vec![crate::image_generation::GeneratedImagePayload {
                media_type: request
                    .images
                    .first()
                    .map(|image| image.media_type.clone())
                    .unwrap_or_else(|| "image/png".to_string()),
                bytes: request
                    .images
                    .first()
                    .map(|image| image.bytes.clone())
                    .unwrap_or_default(),
            }],
            revised_prompt: Some(request.prompt.clone()),
        })
    }
}

#[async_trait]
impl crate::transcription::AudioTranscriptionBackend for ScriptedTranscriptionBackend {
    fn identity(
        &self,
        model_override: Option<&str>,
    ) -> crate::transcription::AudioTranscriptionBackendIdentity {
        crate::transcription::AudioTranscriptionBackendIdentity {
            provider: self.provider.clone(),
            model: model_override.unwrap_or(&self.model).to_string(),
        }
    }

    async fn transcribe(
        &self,
        request: &crate::transcription::AudioTranscriptionBackendRequest,
        model_override: Option<&str>,
    ) -> Result<kheish_runtime::AudioTranscriptionResponse> {
        self.recorded_media_types
            .lock()
            .push(request.media_type.clone());
        self.recorded_file_names
            .lock()
            .push(request.file_name.clone());
        self.recorded_prompts.lock().push(request.prompt.clone());
        self.recorded_languages
            .lock()
            .push(request.language.clone());
        let timestamps = (!request.timestamp_granularities.is_empty()).then(|| {
            kheish_runtime::AudioTranscriptionTimestamps {
                language: request.language.clone(),
                duration_ms: Some(1_200),
                words: request
                    .timestamp_granularities
                    .contains(&"word".to_string())
                    .then(|| {
                        vec![kheish_runtime::AudioTranscriptionWordTimestamp {
                            word: "hello".to_string(),
                            start_ms: 0,
                            end_ms: 600,
                        }]
                    })
                    .unwrap_or_default(),
                segments: request
                    .timestamp_granularities
                    .contains(&"segment".to_string())
                    .then(|| {
                        vec![kheish_runtime::AudioTranscriptionSegmentTimestamp {
                            id: Some(0),
                            text: self.transcript.clone(),
                            start_ms: 0,
                            end_ms: 1_200,
                            speaker: None,
                        }]
                    })
                    .unwrap_or_default(),
            }
        });
        Ok(kheish_runtime::AudioTranscriptionResponse {
            provider: self.provider.clone(),
            model: model_override.unwrap_or(&self.model).to_string(),
            text: self.transcript.clone(),
            timestamps,
        })
    }
}

#[async_trait]
impl crate::transcription::AudioTranscriptionBackend for FailingTranscriptionBackend {
    fn identity(
        &self,
        _model_override: Option<&str>,
    ) -> crate::transcription::AudioTranscriptionBackendIdentity {
        crate::transcription::AudioTranscriptionBackendIdentity {
            provider: "openai".to_string(),
            model: "gpt-4o-transcribe".to_string(),
        }
    }

    async fn transcribe(
        &self,
        _request: &crate::transcription::AudioTranscriptionBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<kheish_runtime::AudioTranscriptionResponse> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        bail!("{}", self.message)
    }
}

struct FlakyTranscriptionBackend {
    first_error: String,
    success_text: String,
    calls: Arc<AtomicUsize>,
}

#[async_trait]
impl crate::transcription::AudioTranscriptionBackend for FlakyTranscriptionBackend {
    fn identity(
        &self,
        _model_override: Option<&str>,
    ) -> crate::transcription::AudioTranscriptionBackendIdentity {
        crate::transcription::AudioTranscriptionBackendIdentity {
            provider: "openai".to_string(),
            model: "gpt-4o-transcribe".to_string(),
        }
    }

    async fn transcribe(
        &self,
        _request: &crate::transcription::AudioTranscriptionBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<kheish_runtime::AudioTranscriptionResponse> {
        let call_index = self.calls.fetch_add(1, Ordering::SeqCst);
        if call_index == 0 {
            bail!("{}", self.first_error);
        }
        Ok(kheish_runtime::AudioTranscriptionResponse {
            provider: "openai".to_string(),
            model: "gpt-4o-transcribe".to_string(),
            text: self.success_text.clone(),
            timestamps: None,
        })
    }
}

#[async_trait]
impl crate::transcription::AudioTranscriptionBackend for BlockingTranscriptionBackend {
    fn identity(
        &self,
        _model_override: Option<&str>,
    ) -> crate::transcription::AudioTranscriptionBackendIdentity {
        crate::transcription::AudioTranscriptionBackendIdentity {
            provider: "openai".to_string(),
            model: "gpt-4o-transcribe".to_string(),
        }
    }

    async fn transcribe(
        &self,
        request: &crate::transcription::AudioTranscriptionBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<kheish_runtime::AudioTranscriptionResponse> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        let in_flight = self.in_flight.fetch_add(1, Ordering::SeqCst) + 1;
        self.max_in_flight.fetch_max(in_flight, Ordering::SeqCst);
        self.entered.notify_waiters();
        let permit = self
            .release
            .acquire()
            .await
            .context("blocking transcription release semaphore closed")?;
        drop(permit);
        self.in_flight.fetch_sub(1, Ordering::SeqCst);

        Ok(kheish_runtime::AudioTranscriptionResponse {
            provider: "openai".to_string(),
            model: "gpt-4o-transcribe".to_string(),
            text: format!("DERIVATION_PARALLEL_OK {}", request.file_name),
            timestamps: None,
        })
    }
}

fn scripted_transcription_service(
    transcript: &str,
    recorded_media_types: Arc<Mutex<Vec<String>>>,
    recorded_file_names: Arc<Mutex<Vec<String>>>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    scripted_transcription_service_with_hints(
        transcript,
        recorded_media_types,
        recorded_file_names,
        Arc::new(Mutex::new(Vec::new())),
        Arc::new(Mutex::new(Vec::new())),
    )
}

fn scripted_transcription_service_with_hints(
    transcript: &str,
    recorded_media_types: Arc<Mutex<Vec<String>>>,
    recorded_file_names: Arc<Mutex<Vec<String>>>,
    recorded_prompts: Arc<Mutex<Vec<Option<String>>>>,
    recorded_languages: Arc<Mutex<Vec<Option<String>>>>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    scripted_transcription_service_with_identity(
        "scripted-transcription",
        transcript,
        "openai",
        "gpt-4o-transcribe",
        recorded_media_types,
        recorded_file_names,
        recorded_prompts,
        recorded_languages,
    )
}

fn scripted_transcription_service_with_identity(
    route_id: &str,
    transcript: &str,
    provider: &str,
    model: &str,
    recorded_media_types: Arc<Mutex<Vec<String>>>,
    recorded_file_names: Arc<Mutex<Vec<String>>>,
    recorded_prompts: Arc<Mutex<Vec<Option<String>>>>,
    recorded_languages: Arc<Mutex<Vec<Option<String>>>>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    let mut backends = BTreeMap::new();
    backends.insert(
        route_id.to_string(),
        Arc::new(ScriptedTranscriptionBackend {
            transcript: transcript.to_string(),
            provider: provider.to_string(),
            model: model.to_string(),
            recorded_media_types,
            recorded_file_names,
            recorded_prompts,
            recorded_languages,
        }) as Arc<dyn crate::transcription::AudioTranscriptionBackend>,
    );
    Ok(Arc::new(crate::transcription::TranscriptionService::new(
        backends,
        route_id.to_string(),
    )?))
}

fn failing_transcription_service(
    message: &str,
    calls: Arc<AtomicUsize>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    let mut backends = BTreeMap::new();
    backends.insert(
        "failing-transcription".to_string(),
        Arc::new(FailingTranscriptionBackend {
            message: message.to_string(),
            calls,
        }) as Arc<dyn crate::transcription::AudioTranscriptionBackend>,
    );
    Ok(Arc::new(crate::transcription::TranscriptionService::new(
        backends,
        "failing-transcription".to_string(),
    )?))
}

fn flaky_transcription_service(
    first_error: &str,
    success_text: &str,
    calls: Arc<AtomicUsize>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    let mut backends = BTreeMap::new();
    backends.insert(
        "flaky-transcription".to_string(),
        Arc::new(FlakyTranscriptionBackend {
            first_error: first_error.to_string(),
            success_text: success_text.to_string(),
            calls,
        }) as Arc<dyn crate::transcription::AudioTranscriptionBackend>,
    );
    Ok(Arc::new(crate::transcription::TranscriptionService::new(
        backends,
        "flaky-transcription".to_string(),
    )?))
}

fn blocking_transcription_service(
    calls: Arc<AtomicUsize>,
    in_flight: Arc<AtomicUsize>,
    max_in_flight: Arc<AtomicUsize>,
    entered: Arc<Notify>,
    release: Arc<Semaphore>,
) -> Result<Arc<crate::transcription::TranscriptionService>> {
    let mut backends = BTreeMap::new();
    backends.insert(
        "blocking-transcription".to_string(),
        Arc::new(BlockingTranscriptionBackend {
            calls,
            in_flight,
            max_in_flight,
            entered,
            release,
        }) as Arc<dyn crate::transcription::AudioTranscriptionBackend>,
    );
    Ok(Arc::new(crate::transcription::TranscriptionService::new(
        backends,
        "blocking-transcription".to_string(),
    )?))
}

struct StaticRouteImageBackend {
    provider: &'static str,
    model: &'static str,
    supports_edit: bool,
}

#[async_trait]
impl crate::image_generation::ImageGenerationBackend for StaticRouteImageBackend {
    fn provider(&self) -> &str {
        self.provider
    }

    async fn generate(
        &self,
        _request: &crate::control_tools::GenerateImageToolRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        Ok(crate::image_generation::GeneratedImageBatch {
            provider: self.provider.to_string(),
            model: self.model.to_string(),
            images: vec![crate::image_generation::GeneratedImagePayload {
                media_type: "image/png".to_string(),
                bytes: sample_png_bytes()?,
            }],
            revised_prompt: None,
        })
    }

    fn supports_edit(&self) -> bool {
        self.supports_edit
    }

    async fn edit(
        &self,
        request: &crate::image_generation::ImageEditBackendRequest,
        _model_override: Option<&str>,
    ) -> Result<crate::image_generation::GeneratedImageBatch> {
        Ok(crate::image_generation::GeneratedImageBatch {
            provider: self.provider.to_string(),
            model: self.model.to_string(),
            images: vec![crate::image_generation::GeneratedImagePayload {
                media_type: request
                    .images
                    .first()
                    .map(|image| image.media_type.clone())
                    .unwrap_or_else(|| "image/png".to_string()),
                bytes: match request.images.first() {
                    Some(image) => image.bytes.clone(),
                    None => sample_png_bytes()?,
                },
            }],
            revised_prompt: Some(request.prompt.clone()),
        })
    }
}

