#[test]
fn routed_model_control_rejects_provider_model_mismatch() -> Result<()> {
    let observer = Arc::new(NoopObserver);
    let debug = DebugControl::new(DebugCaptureLevel::Off);
    let (_driver, control) = RoutedModelControl::new(
        vec![
            ModelRouteConfig::Anthropic(AnthropicProviderConfig::new(
                "claude-opus-4-6",
                "test-anthropic-key",
            )),
            ModelRouteConfig::OpenAi(OpenAiProviderConfig::new("gpt-5.4", "test-openai-key")),
        ],
        daemon_model_retry_policy(),
        daemon_model_budget(),
        observer,
        debug,
    )?;

    let error = control
        .resolve_route(Some("anthropic"), Some("gpt-5.4"))
        .expect_err("mismatched provider/model should fail");
    assert!(
        error
            .to_string()
            .contains("not compatible with route `anthropic`")
    );
    let missing = control
        .resolve_route(Some("missing-route"), Some("gpt-5.4"))
        .expect_err("missing provider/model should fail as missing route");
    assert!(
        missing
            .to_string()
            .contains("daemon has no route configured for `missing-route`")
    );
    Ok(())
}

