#[test]
fn merge_generation_override_preserves_non_default_session_generation_fields() {
    let merged = merge_generation_override(
        Some(ModelGenerationConfig {
            model: Some("gpt-5.4".to_string()),
            reasoning: Some(kheish_types::ReasoningConfig {
                effort: Some(kheish_types::ReasoningEffort::High),
                summary: Some(kheish_types::ReasoningSummary::Concise),
                budget_tokens: None,
                interleaved: false,
            }),
            tool_choice: kheish_types::ToolChoice::Required,
            allow_parallel_tool_calls: false,
            response_format: kheish_types::ResponseFormat::StructuredJson {
                schema: kheish_types::StructuredFieldSchema::new(
                    kheish_types::StructuredValueKind::Object,
                ),
            },
            ..ModelGenerationConfig::default()
        }),
        Some(ModelGenerationConfig::default()),
    )
    .expect("merged generation should be present");

    assert_eq!(merged.model.as_deref(), Some("gpt-5.4"));
    assert_eq!(
        merged.reasoning.and_then(|reasoning| reasoning.effort),
        Some(kheish_types::ReasoningEffort::High)
    );
    assert_eq!(merged.tool_choice, kheish_types::ToolChoice::Required);
    assert!(!merged.allow_parallel_tool_calls);
    assert!(matches!(
        merged.response_format,
        kheish_types::ResponseFormat::StructuredJson { .. }
    ));
}

