#[async_trait]
impl ModelProvider for ScriptedProvider {
    async fn stream(
        &self,
        _request: ModelRuntimeRequest,
        sink: ModelEventSink,
    ) -> std::result::Result<(), ProviderError> {
        let step = {
            let mut queue = self.0.lock();
            queue.pop_front().expect("scripted response")
        };
        match step {
            ScriptedStep::Immediate(Ok(events)) => {
                for event in events {
                    sink.emit(event).expect("sink open");
                }
                Ok(())
            }
            ScriptedStep::ReleaseAfter { gate, response } => {
                gate.notified().await;
                match response {
                    Ok(events) => {
                        for event in events {
                            sink.emit(event).expect("sink open");
                        }
                        Ok(())
                    }
                    Err(error) => Err(error),
                }
            }
            ScriptedStep::AssertChannelLeaseBeforeRelease {
                state_root,
                channel_id,
                active_run_id,
                turn_id,
                superseded_run_id,
                superseded_turn_id,
                gate,
                response,
            } => {
                assert_channel_lease_persisted(
                    &state_root,
                    &channel_id,
                    &active_run_id,
                    &turn_id,
                    superseded_run_id.as_deref(),
                    superseded_turn_id.as_deref(),
                )
                .map_err(|error| ProviderError {
                    message: error.to_string(),
                    retryable: false,
                    retry_after_ms: None,
                })?;
                gate.notified().await;
                match response {
                    Ok(events) => {
                        for event in events {
                            sink.emit(event).expect("sink open");
                        }
                        Ok(())
                    }
                    Err(error) => Err(error),
                }
            }
            ScriptedStep::ReleaseAfterPermit { gate, response } => {
                let _permit = gate.acquire().await.map_err(|_| ProviderError {
                    message: "scripted release gate closed".to_string(),
                    retryable: false,
                    retry_after_ms: None,
                })?;
                match response {
                    Ok(events) => {
                        for event in events {
                            sink.emit(event).expect("sink open");
                        }
                        Ok(())
                    }
                    Err(error) => Err(error),
                }
            }
            ScriptedStep::Immediate(Err(error)) => Err(error),
        }
    }
}

impl LoopbackWebFetchProvider {
    fn new(address: Arc<Mutex<Option<SocketAddr>>>) -> Self {
        Self {
            address,
            calls: AtomicUsize::new(0),
        }
    }
}

#[async_trait]
impl ModelProvider for LoopbackWebFetchProvider {
    async fn stream(
        &self,
        _request: ModelRuntimeRequest,
        sink: ModelEventSink,
    ) -> std::result::Result<(), ProviderError> {
        let call_index = self.calls.fetch_add(1, Ordering::SeqCst);
        if call_index == 0 {
            let address = *self
                .address
                .lock()
                .as_ref()
                .expect("daemon address should be set before model call");
            sink.emit(ModelStreamEvent::MessageId {
                value: "assistant-loopback-fetch-1".to_string(),
            })
            .expect("sink open");
            sink.emit(ModelStreamEvent::ToolCall {
                call: kheish_types::ToolCallRecord {
                    id: "call-loopback-fetch-1".to_string(),
                    name: "web_fetch".to_string(),
                    input: json!({"url": format!("http://{address}/v1/status")}),
                    assistant_message_id: None,
                    assistant_provider_response_id: None,
                },
            })
            .expect("sink open");
            sink.emit(ModelStreamEvent::Stop {
                reason: kheish_types::ModelFinishReason::ToolCalls,
            })
            .expect("sink open");
        } else {
            for event in scripted_events(
                "assistant-loopback-fetch-2",
                "WEB_FETCH_LOOPBACK_BLOCKED",
                kheish_types::ModelFinishReason::Completed,
            ) {
                sink.emit(event).expect("sink open");
            }
        }
        Ok(())
    }
}

fn immediate_script_queue(
    script: Vec<Result<Vec<ModelStreamEvent>, ProviderError>>,
) -> VecDeque<ScriptedStep> {
    script.into_iter().map(Into::into).collect()
}

async fn scripted_daemon_steps(
    state_root: &Path,
    script: Vec<ScriptedStep>,
) -> Result<(SocketAddr, oneshot::Sender<()>)> {
    let events = DaemonEventBus::new(256);
    let debug = DebugControl::new(DebugCaptureLevel::Off);
    let observer: Arc<dyn RuntimeObserver> = DaemonObserver::shared(
        events.clone(),
        debug.clone(),
        FileDebugStore::new(state_root),
    );
    let model = Arc::new(ModelRuntime::new(
        ScriptedProvider(Mutex::new(script.into_iter().collect())),
        ModelRetryPolicy::default(),
        ModelBudget::default(),
        observer.clone(),
    ));
    let permissions = Arc::new(PermissionEngine::new(
        vec![],
        vec![],
        vec![PermissionRule {
            scope: PermissionScope::Session,
            tool_name_pattern: "echo".to_string(),
            behavior: PermissionBehavior::Ask,
            reason: Some("approval required".to_string()),
        }],
        observer.clone(),
    ));
    let model_control =
        Some(Arc::new(ScriptedModelControl::new("scripted-model")) as Arc<dyn DaemonModelControl>);
    start_test_daemon(
        state_root,
        model,
        permissions,
        model_control,
        events,
        debug,
        observer,
        |tools| tools.register(EchoTool),
    )
    .await
}

#[async_trait]
impl ModelProvider for SlowProvider {
    async fn stream(
        &self,
        _request: ModelRuntimeRequest,
        sink: ModelEventSink,
    ) -> std::result::Result<(), ProviderError> {
        sink.emit(ModelStreamEvent::MessageId {
            value: "slow-assistant".to_string(),
        })
        .expect("sink open");
        sink.emit(ModelStreamEvent::TextDelta {
            text: "Still working".to_string(),
        })
        .expect("sink open");
        tokio::time::sleep(self.delay).await;
        sink.emit(ModelStreamEvent::Stop {
            reason: kheish_types::ModelFinishReason::Completed,
        })
        .expect("sink open");
        Ok(())
    }
}

#[async_trait]
impl ModelProvider for EchoingDelayProvider {
    async fn stream(
        &self,
        request: ModelRuntimeRequest,
        sink: ModelEventSink,
    ) -> std::result::Result<(), ProviderError> {
        let content = request
            .prompt
            .items
            .iter()
            .rev()
            .find_map(|item| match item {
                kheish_types::ProviderInputItem::Message { role, content, .. }
                    if *role == Role::User =>
                {
                    Some(content.clone())
                }
                _ => None,
            })
            .unwrap_or_else(|| "EMPTY".to_string());
        sink.emit(ModelStreamEvent::MessageId {
            value: format!("echo-{}-{}", request.session_id, request.turn),
        })
        .expect("sink open");
        tokio::time::sleep(self.delay).await;
        sink.emit(ModelStreamEvent::TextDelta {
            text: format!("ECHO:{}", content.trim()),
        })
        .expect("sink open");
        sink.emit(ModelStreamEvent::Stop {
            reason: kheish_types::ModelFinishReason::Completed,
        })
        .expect("sink open");
        Ok(())
    }
}

