#[test]
fn restore_supervisor_rejects_corrupt_persisted_topology() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let observer: Arc<dyn RuntimeObserver> = Arc::new(NoopObserver);
    let supervisor = AgentSupervisor::new(observer.clone());
    let parent = supervisor.spawn(
        None,
        ConversationKey {
            session_id: "parent".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;
    let _child = supervisor.spawn(
        Some(parent.id.clone()),
        ConversationKey {
            session_id: "child".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;

    let mut snapshot = supervisor.snapshot();
    snapshot.agents.remove(&parent.id);
    let store = FileDaemonStore::new(&state_root);
    store.save_supervisor(&snapshot)?;

    let error = match restore_supervisor(&store, observer) {
        Ok(_) => bail!("corrupt topology should fail boot"),
        Err(error) => error,
    };
    assert!(
        error.to_string().contains("missing parent"),
        "unexpected error: {error}"
    );
    Ok(())
}

#[test]
fn restore_supervisor_rejects_duplicate_agent_sessions() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let observer: Arc<dyn RuntimeObserver> = Arc::new(NoopObserver);
    let supervisor = AgentSupervisor::new(observer.clone());
    let parent = supervisor.spawn(
        None,
        ConversationKey {
            session_id: "shared-session".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;
    let child = supervisor.spawn(
        Some(parent.id.clone()),
        ConversationKey {
            session_id: "child-session".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;

    let mut snapshot = supervisor.snapshot();
    snapshot
        .agents
        .get_mut(&child.id)
        .expect("child exists")
        .conversation
        .session_id = "shared-session".to_string();
    let store = FileDaemonStore::new(&state_root);
    store.save_supervisor(&snapshot)?;

    let error = match restore_supervisor(&store, observer) {
        Ok(_) => bail!("duplicate agent sessions should fail boot"),
        Err(error) => error,
    };
    assert!(
        error.to_string().contains("shares session"),
        "unexpected error: {error}"
    );
    Ok(())
}

#[test]
fn restore_supervisor_recovers_append_only_audit_entries() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let observer: Arc<dyn RuntimeObserver> = Arc::new(NoopObserver);
    let supervisor = AgentSupervisor::new(observer.clone());
    let parent = supervisor.spawn(
        None,
        ConversationKey {
            session_id: "audit-parent".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;
    let mut snapshot = supervisor.snapshot();
    snapshot.audit_log.clear();
    snapshot.next_audit_id = 0;
    let store = FileDaemonStore::new(&state_root);
    store.save_supervisor(&snapshot)?;
    store.append_supervisor_audit(&kheish_agent::AgentSupervisorAuditEntry {
        audit_id: 7,
        timestamp_ms: now_ms(),
        event: "ledger_only".to_string(),
        agent_id: parent.id.clone(),
        parent_agent_id: None,
        session_id: Some(parent.conversation.session_id.clone()),
        previous_status: None,
        status: Some(parent.status.clone()),
        reason: Some("simulated crash before snapshot save".to_string()),
    })?;
    let audit_path = state_root.join("daemon-supervisor-audit.jsonl");
    let mut corrupt_tail = fs::OpenOptions::new().append(true).open(&audit_path)?;
    corrupt_tail.write_all(b"{\"audit_id\":")?;
    corrupt_tail.write_all(&[0xc3])?;

    let second_store = FileDaemonStore::new(&state_root);
    second_store.append_supervisor_audit(&kheish_agent::AgentSupervisorAuditEntry {
        audit_id: 8,
        timestamp_ms: now_ms(),
        event: "ledger_after_repair".to_string(),
        agent_id: parent.id.clone(),
        parent_agent_id: None,
        session_id: Some(parent.conversation.session_id.clone()),
        previous_status: None,
        status: Some(parent.status.clone()),
        reason: Some("valid append after corrupt tail repair".to_string()),
    })?;
    let restored_after_append = restore_supervisor(&second_store, observer)?;
    let audit = restored_after_append.audit_log(None);
    assert!(
        audit.iter().any(|entry| entry.event == "ledger_only"
            && entry.audit_id == 7
            && entry.agent_id == parent.id),
        "append-only audit ledger should be merged on restore: {audit:#?}"
    );
    assert!(
        audit
            .iter()
            .any(|entry| entry.event == "ledger_after_repair" && entry.audit_id == 8),
        "valid appends after corrupt tail repair should recover on restart: {audit:#?}"
    );
    let repaired_ledger = fs::read_to_string(&audit_path)?;
    assert!(
        repaired_ledger.ends_with('\n'),
        "restore should repair corrupt ledger tails before future appends: {repaired_ledger}"
    );
    assert!(
        repaired_ledger.lines().all(|line| serde_json::from_str::<
            kheish_agent::AgentSupervisorAuditEntry,
        >(line)
        .is_ok()),
        "restore should leave only parseable audit ledger lines: {repaired_ledger}"
    );
    let next = restored_after_append.spawn(
        None,
        ConversationKey {
            session_id: "audit-next".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;
    let next_audit = restored_after_append.audit_log(Some(&next.id));
    assert!(
        next_audit.iter().any(|entry| entry.audit_id > 8),
        "restored audit id seed should advance past ledger entries: {next_audit:#?}"
    );
    second_store.save_supervisor(&restored_after_append.snapshot())?;
    let compacted = fs::read_to_string(&audit_path)?;
    assert!(
        compacted.trim().is_empty(),
        "checkpointed supervisor snapshots should compact recovered audit ledger: {compacted}"
    );
    Ok(())
}

#[test]
fn restore_supervisor_repairs_invalid_and_conflicting_audit_ledger_entries() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let observer: Arc<dyn RuntimeObserver> = Arc::new(NoopObserver);
    let supervisor = AgentSupervisor::new(observer.clone());
    let parent = supervisor.spawn(
        None,
        ConversationKey {
            session_id: "audit-parent".to_string(),
            thread_id: None,
        },
        None,
        None,
        ChildRetentionPolicy::Retain,
        None,
        None,
    )?;
    let snapshot = supervisor.snapshot();
    let checkpointed = snapshot
        .audit_log
        .first()
        .cloned()
        .expect("spawn records an audit entry");
    let store = FileDaemonStore::new(&state_root);
    store.save_supervisor(&snapshot)?;

    let valid_ledger_id = snapshot.next_audit_id + 1;
    let audit_path = state_root.join("daemon-supervisor-audit.jsonl");
    let mut ledger = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&audit_path)?;
    for entry in [
        kheish_agent::AgentSupervisorAuditEntry {
            audit_id: checkpointed.audit_id,
            timestamp_ms: now_ms(),
            event: "conflicting_checkpointed".to_string(),
            agent_id: parent.id.clone(),
            parent_agent_id: None,
            session_id: Some(parent.conversation.session_id.clone()),
            previous_status: None,
            status: Some(parent.status.clone()),
            reason: Some("should not replace checkpointed audit".to_string()),
        },
        kheish_agent::AgentSupervisorAuditEntry {
            audit_id: 0,
            timestamp_ms: now_ms(),
            event: "invalid_zero_id".to_string(),
            agent_id: parent.id.clone(),
            parent_agent_id: None,
            session_id: Some(parent.conversation.session_id.clone()),
            previous_status: None,
            status: Some(parent.status.clone()),
            reason: None,
        },
        kheish_agent::AgentSupervisorAuditEntry {
            audit_id: valid_ledger_id + 1,
            timestamp_ms: now_ms(),
            event: "   ".to_string(),
            agent_id: parent.id.clone(),
            parent_agent_id: None,
            session_id: Some(parent.conversation.session_id.clone()),
            previous_status: None,
            status: Some(parent.status.clone()),
            reason: None,
        },
        kheish_agent::AgentSupervisorAuditEntry {
            audit_id: valid_ledger_id,
            timestamp_ms: now_ms(),
            event: "valid_ledger_semantic".to_string(),
            agent_id: parent.id.clone(),
            parent_agent_id: None,
            session_id: Some(parent.conversation.session_id.clone()),
            previous_status: None,
            status: Some(parent.status.clone()),
            reason: Some("survives semantic ledger repair".to_string()),
        },
        kheish_agent::AgentSupervisorAuditEntry {
            audit_id: valid_ledger_id,
            timestamp_ms: now_ms(),
            event: "conflicting_duplicate_ledger".to_string(),
            agent_id: parent.id.clone(),
            parent_agent_id: None,
            session_id: Some(parent.conversation.session_id.clone()),
            previous_status: None,
            status: Some(parent.status.clone()),
            reason: Some("should not replace first ledger entry".to_string()),
        },
    ] {
        serde_json::to_writer(&mut ledger, &entry)?;
        ledger.write_all(b"\n")?;
    }
    drop(ledger);

    let restored = restore_supervisor(&store, observer)?;
    let audit = restored.audit_log(None);
    let restored_checkpoint = audit
        .iter()
        .find(|entry| entry.audit_id == checkpointed.audit_id)
        .expect("checkpointed audit entry remains present");
    assert_eq!(
        restored_checkpoint.event, checkpointed.event,
        "ledger conflicts must not replace checkpointed audit entries"
    );
    assert!(
        audit.iter().any(
            |entry| entry.audit_id == valid_ledger_id && entry.event == "valid_ledger_semantic"
        ),
        "valid ledger entries newer than the checkpoint should be recovered: {audit:#?}"
    );
    assert!(
        audit
            .iter()
            .all(|entry| entry.audit_id > 0 && !entry.event.trim().is_empty()),
        "invalid semantic ledger entries must be dropped before restore: {audit:#?}"
    );
    assert!(
        audit
            .iter()
            .all(|entry| entry.event != "conflicting_duplicate_ledger"
                && entry.event != "conflicting_checkpointed"),
        "conflicting ledger entries should be dropped: {audit:#?}"
    );

    let repaired_ledger = fs::read_to_string(&audit_path)?;
    let repaired_entries = repaired_ledger
        .lines()
        .map(serde_json::from_str::<kheish_agent::AgentSupervisorAuditEntry>)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    assert_eq!(
        repaired_entries
            .iter()
            .map(|entry| entry.event.as_str())
            .collect::<Vec<_>>(),
        vec!["valid_ledger_semantic"],
        "semantic repair should retain only recoverable ledger-only entries: {repaired_entries:#?}"
    );
    Ok(())
}

