fn sample_pdf_bytes(text: &str) -> Result<Vec<u8>> {
    let mut document = PdfDocument::with_version("1.5");
    let pages_id = document.new_object_id();
    let page_id = document.new_object_id();
    let font_id = document.add_object(dictionary! {
        "Type" => "Font",
        "Subtype" => "Type1",
        "BaseFont" => "Helvetica",
    });
    let resources_id = document.add_object(dictionary! {
        "Font" => dictionary! {
            "F1" => font_id,
        }
    });
    let content = format!("BT\n/F1 18 Tf\n72 96 Td\n({text}) Tj\nET");
    let content_id = document.add_object(PdfStream::new(dictionary! {}, content.into_bytes()));
    document.objects.insert(
        pages_id,
        PdfObject::Dictionary(dictionary! {
            "Type" => "Pages",
            "Kids" => vec![page_id.into()],
            "Count" => 1,
        }),
    );
    document.objects.insert(
        page_id,
        PdfObject::Dictionary(dictionary! {
            "Type" => "Page",
            "Parent" => pages_id,
            "MediaBox" => vec![0.into(), 0.into(), 300.into(), 144.into()],
            "Contents" => content_id,
            "Resources" => resources_id,
        }),
    );
    let catalog_id = document.add_object(dictionary! {
        "Type" => "Catalog",
        "Pages" => pages_id,
    });
    document.trailer.set("Root", catalog_id);
    let mut bytes = Vec::new();
    document
        .save_to(&mut bytes)
        .context("failed to build PDF test fixture")?;
    Ok(bytes)
}

fn sample_png_bytes() -> Result<Vec<u8>> {
    sample_png_bytes_with_color([255, 0, 0])
}

fn sample_png_bytes_with_color(rgb: [u8; 3]) -> Result<Vec<u8>> {
    let image = ImageBuffer::<Rgb<u8>, Vec<u8>>::from_pixel(32, 32, Rgb(rgb));
    let mut cursor = std::io::Cursor::new(Vec::new());
    image
        .write_to(&mut cursor, image::ImageFormat::Png)
        .context("failed to build PNG test fixture")?;
    Ok(cursor.into_inner())
}

fn sample_jpeg_bytes() -> Result<Vec<u8>> {
    let image = ImageBuffer::<Rgb<u8>, Vec<u8>>::from_pixel(32, 32, Rgb([0, 0, 255]));
    let mut bytes = Vec::new();
    JpegEncoder::new_with_quality(&mut bytes, 90)
        .write_image(
            image.as_raw(),
            image.width(),
            image.height(),
            ColorType::Rgb8.into(),
        )
        .context("failed to build JPEG test fixture")?;
    Ok(bytes)
}

