fn inline_attachment(
    file_name: &str,
    media_type: Option<&str>,
    bytes: &[u8],
) -> InputAttachmentRequest {
    InputAttachmentRequest::InlineAsset(InlineAssetUpload {
        file_name: file_name.to_string(),
        media_type: media_type.map(ToOwned::to_owned),
        content_base64: BASE64_STANDARD.encode(bytes),
    })
}

fn asset_reference(asset_id: impl Into<String>) -> InputAttachmentRequest {
    InputAttachmentRequest::AssetReference {
        asset_id: asset_id.into(),
    }
}

fn text_input_item(text: impl Into<String>) -> SubmitInputItemRequest {
    SubmitInputItemRequest::Text { text: text.into() }
}

fn asset_input_item(asset_id: impl Into<String>) -> SubmitInputItemRequest {
    SubmitInputItemRequest::AssetReference {
        asset_id: asset_id.into(),
    }
}

fn assert_fragments_in_order(haystack: &str, fragments: &[&str]) {
    let mut cursor = 0usize;
    for fragment in fragments {
        let relative = haystack[cursor..]
            .find(fragment)
            .unwrap_or_else(|| panic!("missing fragment `{fragment}` in `{haystack}`"));
        cursor += relative + fragment.len();
    }
}

async fn import_test_asset(
    client: &Client,
    base: &str,
    file_name: &str,
    media_type: &str,
    bytes: &[u8],
) -> Result<AssetView> {
    client
        .post(format!("{base}/v1/assets"))
        .json(&CreateAssetRequest {
            upload: InlineAssetUpload {
                file_name: file_name.to_string(),
                media_type: Some(media_type.to_string()),
                content_base64: BASE64_STANDARD.encode(bytes),
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await
        .map_err(Into::into)
}

