async fn start_test_daemon_with_policy_and_scheduler<M>(
    state_root: &Path,
    model: Arc<M>,
    permissions: Arc<PermissionEngine>,
    model_control: Option<Arc<dyn DaemonModelControl>>,
    events: DaemonEventBus,
    debug: DebugControl,
    observer: Arc<dyn RuntimeObserver>,
    subagent_policy: crate::SubagentPolicyConfig,
    image_generation_factory: Option<TestImageGenerationFactory>,
    transcription_factory: Option<TestTranscriptionFactory>,
    enable_image_generation: bool,
    enable_image_edit: bool,
    scheduler_enabled: bool,
    configure_tools: impl FnOnce(&mut ToolRuntime),
) -> Result<(SocketAddr, oneshot::Sender<()>)>
where
    M: ModelDriver + Send + Sync + 'static,
{
    let skills = Arc::new(SharedSkillRegistry::load_from_roots(vec![SkillRoot {
        path: state_root.join("skills"),
        scope: SkillScope::Repo,
    }]));
    let tool_control = DaemonToolControlHandle::new();
    let mut tools = ToolRuntime::new(observer.clone());
    let coding_tool_config = CodingToolConfig::new(state_root);
    configure_tools(&mut tools);
    register_daemon_control_tools(
        &mut tools,
        tool_control.clone(),
        coding_tool_config.clone(),
        false,
        enable_image_generation,
        enable_image_edit,
    );
    let hook_tools = Arc::new(tools.clone_without_hook_dispatcher());
    let sessions = Arc::new(FileSessionStore::new(state_root.join("sessions")));
    let (sender, receiver) = mpsc::unbounded_channel();
    let mut outputs = OutputHost::new();
    let asset_store = Arc::new(crate::assets::FileAssetStore::new(state_root)?);
    let image_generation = if let Some(factory) = image_generation_factory {
        Some(factory(asset_store.clone())?)
    } else {
        None
    };
    let transcription_service = if let Some(factory) = transcription_factory {
        Some(factory()?)
    } else {
        None
    };
    let delivery_queue = Arc::new(DeliveryQueue::load(
        state_root.join("daemon-deliveries.json"),
        crate::connectors::build_delivery_dispatcher(
            Arc::new(crate::connectors::ConnectorRegistry::default()),
            Arc::new(crate::connectors::ExternalConnectorRuntimeService::new()),
            asset_store.clone(),
            observer.clone(),
            state_root.to_path_buf(),
        ),
    )?);
    outputs.register(DaemonOutputPlugin::new(sender));
    crate::connectors::register_output_plugins(&mut outputs, delivery_queue.clone());
    let outputs = Arc::new(outputs);
    let system_prompt = Arc::new(SystemPromptBuilder::new(
        SystemPromptEnvironment::new(state_root, "/bin/bash"),
        SystemPromptSettings::default(),
    ));
    let model_driver: Arc<dyn ModelDriver> = model.clone();
    let hooks = Arc::new(DaemonHookDispatcher::new(
        state_root,
        model_driver,
        model_control.clone(),
        None,
        system_prompt.clone(),
        hook_tools,
        observer.clone(),
        state_root,
    )?);
    let hook_dispatcher: Arc<dyn HookDispatcher> = hooks.clone();
    tools.set_hook_dispatcher(hook_dispatcher.clone());
    let tools = Arc::new(tools);
    let runtime_tools = tools.clone();
    let supervisor = restore_supervisor(&FileDaemonStore::new(state_root), observer.clone())?;
    let orchestrator = AgentOrchestrator::new(
        LoopPolicy::default(),
        AgentRuntimeDependencies {
            model,
            tools,
            permissions: permissions.clone(),
            sessions: sessions.clone(),
            outputs: outputs.clone(),
            system_prompt: system_prompt.clone(),
            hooks: hook_dispatcher,
            observer: observer.clone(),
            skills: skills.clone(),
            active_plugins: Vec::new(),
            active_mcp_tools: Vec::new(),
            connected_mcp_servers: Vec::new(),
            credentialed_mcp_servers: Vec::new(),
            mcp_tool_servers: BTreeMap::new(),
            mcp_server_instructions: Vec::new(),
            mcp_surface: Arc::new(RwLock::new(McpRuntimeSurface::default())),
        },
        supervisor.clone(),
    );
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let auth_manager = AuthManager::new(state_root.join("auth/global-slots.json"))?;
    let connector_service = Arc::new(crate::services::ConnectorService::load(
        state_root,
        None,
        auth_manager.clone(),
    )?);
    let external_connector_runtime =
        Arc::new(crate::connectors::ExternalConnectorRuntimeService::new());
    let service = DaemonService::new(
        crate::service::loopback_control_plane_base_url(address),
        address,
        state_root,
        state_root,
        asset_store,
        orchestrator,
        supervisor,
        permissions,
        sessions,
        system_prompt,
        hooks,
        debug,
        observer,
        runtime_tools,
        McpRuntimeSnapshot::default(),
        Arc::new(RwLock::new(McpRuntimeSurface::default())),
        None,
        model_control,
        events,
        outputs,
        receiver,
        delivery_queue,
        None,
        image_generation,
        transcription_service,
        crate::services::RuntimeConfigService::new(state_root)?,
        auth_manager,
        skills,
        tool_control,
        connector_service.registry(),
        external_connector_runtime,
        connector_service,
        subagent_policy,
        SchedulerPolicyConfig::default(),
        scheduler_enabled,
        ControlPlaneAuthConfig::disabled(),
        crate::ControlPlaneAuthTokenFiles::default(),
        crate::ControlPlaneCorsConfig::loopback(),
        false,
    )
    .await?;
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });
    Ok((address, shutdown_tx))
}

fn write_test_skill_fixture(state_root: &Path, skill_name: &str) -> Result<()> {
    let skill_root = state_root.join("skills").join(skill_name);
    fs::create_dir_all(skill_root.join("agents"))?;
    fs::write(
        skill_root.join("SKILL.md"),
        format!(
            r#"---
name: {skill_name}
description: Validate the daemon skills API surface.
when_to_use: Use when the user explicitly wants the api-skill fixture.
version: "1"
---
You are using the {skill_name} test skill.

Reply with exactly `API_SKILL_FIXTURE_OK`.
"#
        ),
    )?;
    fs::write(
        skill_root.join("agents").join("kheish.yaml"),
        r#"allowed_tools:
  - read_file
blocked_tools:
  - bash
context: inline
agent_profile: verifier
provider: openai
model: gpt-5.4-mini
fallback_model: claude-sonnet-4-5
"#,
    )?;
    Ok(())
}

async fn scripted_daemon(
    state_root: &Path,
    script: Vec<Result<Vec<ModelStreamEvent>, ProviderError>>,
) -> Result<(SocketAddr, oneshot::Sender<()>)> {
    scripted_daemon_with_scheduler_enabled(state_root, script, true).await
}

async fn scripted_daemon_with_scheduler_enabled(
    state_root: &Path,
    script: Vec<Result<Vec<ModelStreamEvent>, ProviderError>>,
    scheduler_enabled: bool,
) -> Result<(SocketAddr, oneshot::Sender<()>)> {
    let events = DaemonEventBus::new(256);
    let debug = DebugControl::new(DebugCaptureLevel::Off);
    let observer: Arc<dyn RuntimeObserver> = DaemonObserver::shared(
        events.clone(),
        debug.clone(),
        FileDebugStore::new(state_root),
    );
    let model = Arc::new(ModelRuntime::new(
        ScriptedProvider(Mutex::new(immediate_script_queue(script))),
        ModelRetryPolicy::default(),
        ModelBudget::default(),
        observer.clone(),
    ));
    let permissions = Arc::new(PermissionEngine::new(
        vec![],
        vec![],
        vec![PermissionRule {
            scope: PermissionScope::Session,
            tool_name_pattern: "echo".to_string(),
            behavior: PermissionBehavior::Ask,
            reason: Some("approval required".to_string()),
        }],
        observer.clone(),
    ));
    let model_control =
        Some(Arc::new(ScriptedModelControl::new("scripted-model")) as Arc<dyn DaemonModelControl>);
    start_test_daemon_with_policy_and_scheduler(
        state_root,
        model,
        permissions,
        model_control,
        events,
        debug,
        observer,
        crate::SubagentPolicyConfig::default(),
        None,
        None,
        false,
        false,
        scheduler_enabled,
        |tools| tools.register(EchoTool),
    )
    .await
}

