/// Reads frames until one matches `wanted`, returning its SSE id and payload.
/// Unlike [`next_sse_event`], the buffer persists across skipped frames, so
/// events arriving in the same chunk are never dropped, and callers can open a
/// follow-up stream with `Last-Event-ID` set to the returned id.
async fn next_sse_event_named(
    response: &mut reqwest::Response,
    wanted: &str,
) -> Result<(Option<u64>, DaemonEvent)> {
    let mut buffer = String::new();
    loop {
        if let Some(frame_end) = buffer.find("\n\n") {
            let frame = buffer[..frame_end].to_string();
            let remainder = buffer[(frame_end + 2)..].to_string();
            buffer = remainder;
            let mut event_name = None;
            let mut event_id = None;
            let mut data = String::new();
            for line in frame.lines() {
                let line = line.trim_end_matches('\r');
                if let Some(value) = line.strip_prefix("event: ") {
                    event_name = Some(value.to_string());
                } else if let Some(value) = line.strip_prefix("id: ") {
                    event_id = value.trim().parse::<u64>().ok();
                } else if let Some(value) = line.strip_prefix("data: ") {
                    data.push_str(value);
                }
            }
            if event_name.as_deref() == Some(wanted) {
                let event = serde_json::from_str::<DaemonEvent>(&data)?;
                return Ok((event_id, event));
            }
            continue;
        }

        let chunk = tokio::time::timeout(Duration::from_secs(5), response.chunk())
            .await
            .context("timed out waiting for SSE chunk")??;
        let Some(chunk) = chunk else {
            anyhow::bail!("SSE stream ended before the expected event was received");
        };
        buffer.push_str(std::str::from_utf8(&chunk)?);
    }
}

async fn next_sse_event(response: &mut reqwest::Response) -> Result<(String, DaemonEvent)> {
    let mut buffer = String::new();
    loop {
        if let Some(frame_end) = buffer.find("\n\n") {
            let frame = buffer[..frame_end].to_string();
            let remainder = buffer[(frame_end + 2)..].to_string();
            buffer = remainder;
            let mut event_name = None;
            let mut data = String::new();
            for line in frame.lines() {
                let line = line.trim_end_matches('\r');
                if let Some(value) = line.strip_prefix("event: ") {
                    event_name = Some(value.to_string());
                } else if let Some(value) = line.strip_prefix("data: ") {
                    data.push_str(value);
                }
            }
            if let Some(event_name) = event_name {
                let event = serde_json::from_str::<DaemonEvent>(&data)?;
                return Ok((event_name, event));
            }
        }

        let chunk = tokio::time::timeout(Duration::from_secs(5), response.chunk())
            .await
            .context("timed out waiting for SSE chunk")??;
        let Some(chunk) = chunk else {
            anyhow::bail!("SSE stream ended before an event was received");
        };
        buffer.push_str(std::str::from_utf8(&chunk)?);
    }
}

async fn wait_for_run_status(
    client: &Client,
    base: &str,
    run_id: &str,
    terminal: &[DaemonRunStatus],
) -> Result<RunView> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let run = client
            .get(format!("{base}/v1/runs/{run_id}"))
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        if terminal.iter().any(|status| run.status == *status) {
            return Ok(run);
        }
        anyhow::ensure!(
            !run.status.is_terminal(),
            "run {run_id} reached unexpected terminal state: {}",
            serde_json::to_string_pretty(&run)?
        );
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for run {run_id} to reach a terminal state"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

async fn wait_for_task_status(
    client: &Client,
    base: &str,
    session_id: &str,
    task_id: &str,
    terminal: &[kheish_types::TaskStatus],
) -> Result<kheish_types::TaskRecord> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let task = client
            .get(format!("{base}/v1/sessions/{session_id}/tasks/{task_id}"))
            .send()
            .await?
            .error_for_status()?
            .json::<kheish_types::TaskRecord>()
            .await?;
        if terminal.iter().any(|status| task.status == *status) {
            return Ok(task);
        }
        anyhow::ensure!(
            !matches!(
                task.status,
                kheish_types::TaskStatus::Completed
                    | kheish_types::TaskStatus::Failed
                    | kheish_types::TaskStatus::Cancelled
            ),
            "task {task_id} reached unexpected terminal state: {}",
            serde_json::to_string_pretty(&task)?
        );
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for task {task_id} to reach a terminal state"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

