async fn wait_for_daemon_shutdown(client: &Client, base: &str) -> Result<()> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        match client.get(format!("{base}/v1/runtime")).send().await {
            Ok(_) => {}
            Err(_) => return Ok(()),
        }
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for daemon at {base} to shut down"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

async fn wait_for_daemon_ready(client: &Client, base: &str) -> Result<()> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        match client.get(format!("{base}/v1/runtime")).send().await {
            Ok(response) if response.status().is_success() => return Ok(()),
            Ok(_) | Err(_) => {}
        }
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for daemon at {base} to become ready"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

fn has_quarantined_sibling(path: &Path) -> Result<bool> {
    let parent = path
        .parent()
        .ok_or_else(|| anyhow!("path has no parent: {}", path.display()))?;
    let file_name = path
        .file_name()
        .ok_or_else(|| anyhow!("path has no file name: {}", path.display()))?
        .to_string_lossy()
        .to_string();
    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let candidate = entry.file_name().to_string_lossy().to_string();
        if candidate.starts_with(&format!("{file_name}.corrupt-")) {
            return Ok(true);
        }
    }
    Ok(false)
}

