fn count_json_files(root: &Path) -> Result<usize> {
    if !root.exists() {
        return Ok(0);
    }
    let mut count = 0usize;
    for entry in fs::read_dir(root)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            count = count.saturating_add(count_json_files(&path)?);
        } else if path.extension().and_then(|value| value.to_str()) == Some("json") {
            count = count.saturating_add(1);
        }
    }
    Ok(count)
}

fn openai_text_response(text: &str, input_tokens: u32, output_tokens: u32) -> String {
    let delta = json!({
        "type": "response.output_text.delta",
        "item_id": "msg-openai-generated",
        "output_index": 0,
        "content_index": 0,
        "delta": text,
    });
    let completed = json!({
        "type": "response.completed",
        "response": {
            "usage": {
                "input_tokens": input_tokens,
                "output_tokens": output_tokens,
            }
        }
    });
    format!(
        "event: response.output_item.added\n\
data: {{\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{{\"id\":\"msg-openai-generated\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}}}\n\n\
event: response.output_text.delta\n\
data: {}\n\n\
event: response.completed\n\
data: {}\n\n",
        delta, completed,
    )
}

fn openai_tool_call_response(
    item_id: &str,
    call_id: &str,
    name: &str,
    input: Value,
    input_tokens: u32,
    output_tokens: u32,
) -> String {
    let added = json!({
        "type": "response.output_item.added",
        "output_index": 0,
        "item": {
            "id": item_id,
            "type": "function_call",
            "status": "in_progress",
            "call_id": call_id,
            "name": name,
            "arguments": "",
        }
    });
    let arguments_done = json!({
        "type": "response.function_call_arguments.done",
        "item_id": item_id,
        "output_index": 0,
        "arguments": input.to_string(),
    });
    let completed = json!({
        "type": "response.completed",
        "response": {
            "usage": {
                "input_tokens": input_tokens,
                "output_tokens": output_tokens,
            }
        }
    });
    format!(
        "event: response.output_item.added\n\
data: {}\n\n\
event: response.function_call_arguments.done\n\
data: {}\n\n\
event: response.completed\n\
data: {}\n\n",
        added, arguments_done, completed,
    )
}

#[derive(Clone)]
struct TelegramMediaMockState {
    file_path: String,
    media_type: String,
    bytes: Vec<u8>,
    get_file_calls: Arc<AtomicUsize>,
}

async fn spawn_telegram_media_mock_server(
    file_path: &str,
    media_type: &str,
    bytes: Vec<u8>,
    get_file_calls: Arc<AtomicUsize>,
) -> Result<String> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let state = TelegramMediaMockState {
        file_path: file_path.to_string(),
        media_type: media_type.to_string(),
        bytes,
        get_file_calls,
    };
    let app = Router::new()
        .route(
            "/bottelegram-test-token/getFile",
            post(
                |axum::extract::State(state): axum::extract::State<TelegramMediaMockState>| async move {
                    state.get_file_calls.fetch_add(1, Ordering::SeqCst);
                    Json(json!({
                        "ok": true,
                        "result": {
                            "file_path": state.file_path,
                        }
                    }))
                },
            ),
        )
        .route(
            "/bottelegram-test-token/getUpdates",
            post(|| async { Json(json!({ "ok": true, "result": [] })) }),
        )
        .route(
            "/file/bottelegram-test-token/{*file_path}",
            get(
                |axum::extract::State(state): axum::extract::State<TelegramMediaMockState>,
                 axum::extract::Path(file_path): axum::extract::Path<String>| async move {
                    if file_path.trim_start_matches('/') != state.file_path {
                        return (
                            StatusCode::NOT_FOUND,
                            [(CONTENT_TYPE, "text/plain".to_string())],
                            b"missing".to_vec(),
                        )
                            .into_response();
                    }
                    (
                        StatusCode::OK,
                        [(CONTENT_TYPE, state.media_type.clone())],
                        state.bytes.clone(),
                    )
                        .into_response()
                },
            ),
        )
        .with_state(state);
    tokio::spawn(async move {
        axum::serve(listener, app)
            .await
            .expect("telegram media mock server should serve");
    });
    Ok(format!("http://{address}"))
}

async fn spawn_openai_auth_mock_server() -> Result<String> {
    async fn oauth_token(headers: axum::http::HeaderMap, body: Bytes) -> Json<serde_json::Value> {
        let content_type = headers
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or_default()
            .to_string();
        if content_type.contains("application/json") {
            let payload: serde_json::Value = serde_json::from_slice(&body).unwrap_or_default();
            if payload
                .get("grant_type")
                .and_then(serde_json::Value::as_str)
                == Some("refresh_token")
            {
                return Json(json!({
                    "access_token": "fresh-access-token",
                    "refresh_token": "fresh-refresh-token"
                }));
            }
        }
        panic!(
            "unexpected OpenAI auth request body: {:?}",
            String::from_utf8(body.to_vec())
        );
    }

    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let router = Router::new().route("/oauth/token", post(oauth_token));
    tokio::spawn(async move {
        let _ = axum::serve(listener, router).await;
    });
    Ok(format!("http://{address}"))
}

async fn spawn_anthropic_auth_mock_server() -> Result<String> {
    async fn oauth_token(headers: axum::http::HeaderMap, body: Bytes) -> Json<serde_json::Value> {
        let content_type = headers
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or_default()
            .to_string();
        assert!(content_type.contains("application/json"));
        let payload: serde_json::Value = serde_json::from_slice(&body).unwrap_or_default();
        assert_eq!(payload["grant_type"], "refresh_token");
        Json(json!({
            "access_token": "anthropic-fresh-access-token",
            "refresh_token": "anthropic-fresh-refresh-token",
            "expires_in": 3600,
            "scope": "user:profile user:inference"
        }))
    }

    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let router = Router::new().route("/oauth/token", post(oauth_token));
    tokio::spawn(async move {
        let _ = axum::serve(listener, router).await;
    });
    Ok(format!("http://{address}/oauth/token"))
}

#[tokio::test]
async fn daemon_api_drives_sessions_and_approval_resume() -> Result<()> {
    let temp = tempdir()?;
    let address_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &address_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-1".to_string(),
                },
                ModelStreamEvent::TextDelta {
                    text: "Need approval.".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "hello"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-2",
                "Completed.",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let session = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("api-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?;
    assert_eq!(session.status(), StatusCode::CREATED);

    let capabilities = client
        .get(format!("{base}/v1/capabilities"))
        .send()
        .await?
        .json::<DaemonCapabilities>()
        .await?;
    assert!(capabilities.approvals);
    assert!(capabilities.session_events);

    let view = client
        .post(format!("{base}/v1/sessions/api-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .json::<SessionView>()
        .await?;
    assert_eq!(view.snapshot.pending_approvals.len(), 1);
    assert_eq!(
        view.snapshot.agent.status,
        kheish_agent::AgentStatus::WaitingForApproval
    );

    let conflict = client
        .post(format!("{base}/v1/sessions/api-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "second run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);
    assert!(
        conflict
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = conflict.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("sessions"));
    assert_eq!(problem.code, "session_busy");

    let unknown_approval = client
        .post(format!("{base}/v1/sessions/api-session/approvals"))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: "approval-missing".to_string(),
                behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                updated_input: None,
                justification: Some("invalid".to_string()),
                reason: None,
            }],
        })
        .send()
        .await?;
    assert_eq!(unknown_approval.status(), StatusCode::BAD_REQUEST);
    let unknown_problem = unknown_approval.json::<ProblemDetails>().await?;
    assert_eq!(unknown_problem.domain.as_deref(), Some("approvals"));
    assert_eq!(unknown_problem.code, "approval_request_not_pending");

    let duplicate_approval = client
        .post(format!("{base}/v1/sessions/api-session/approvals"))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![
                ApprovalResolution {
                    request_id: view.snapshot.pending_approvals[0].id.clone(),
                    behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                    updated_input: None,
                    justification: Some("duplicate-a".to_string()),
                    reason: None,
                },
                ApprovalResolution {
                    request_id: view.snapshot.pending_approvals[0].id.clone(),
                    behavior: kheish_types::ApprovalResolutionBehavior::Deny,
                    updated_input: None,
                    justification: Some("duplicate-b".to_string()),
                    reason: Some("duplicate".to_string()),
                },
            ],
        })
        .send()
        .await?;
    assert_eq!(duplicate_approval.status(), StatusCode::BAD_REQUEST);
    let duplicate_problem = duplicate_approval.json::<ProblemDetails>().await?;
    assert_eq!(duplicate_problem.domain.as_deref(), Some("approvals"));
    assert_eq!(duplicate_problem.code, "approval_duplicate_resolution");

    let still_waiting = client
        .get(format!("{base}/v1/sessions/api-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(
        still_waiting.snapshot.pending_approvals,
        view.snapshot.pending_approvals
    );
    assert_eq!(
        still_waiting.snapshot.agent.status,
        kheish_agent::AgentStatus::WaitingForApproval
    );

    let resumed_response = client
        .post(format!("{base}/v1/sessions/api-session/approvals"))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: view.snapshot.pending_approvals[0].id.clone(),
                behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                updated_input: None,
                justification: Some("approved".to_string()),
                reason: None,
            }],
        })
        .send()
        .await?;
    let resumed_status = resumed_response.status();
    let resumed_body = resumed_response.text().await?;
    assert_eq!(
        resumed_status,
        StatusCode::OK,
        "unexpected approval resume response: {resumed_body}"
    );
    let resumed: SessionView =
        serde_json::from_str(&resumed_body).context("failed to decode approval resume response")?;
    assert_eq!(resumed.snapshot.pending_approvals.len(), 0);
    assert_eq!(
        resumed.snapshot.last_assistant_message.as_deref(),
        Some("Completed.")
    );
    assert!(!resumed.outputs.is_empty());

    let runs = client
        .get(format!("{base}/v1/runs?session_id=api-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    let run_id = runs
        .first()
        .map(|run| run.run_id.clone())
        .ok_or_else(|| anyhow!("expected completed approval run"))?;
    let run_events = client
        .get(format!("{base}/v1/runs/{run_id}/events"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert!(
        run_events.iter().any(|entry| {
            matches!(
                &entry.event,
                RunEvent::ApprovalResolved { resolutions }
                    if resolutions
                        .iter()
                        .any(|resolution| resolution.request_id == view.snapshot.pending_approvals[0].id)
            )
        }),
        "approval resolution should be durably audited in run events: {}",
        serde_json::to_string_pretty(&run_events)?
    );

    let events = client
        .get(format!("{base}/v1/sessions/api-session/events"))
        .send()
        .await?
        .json::<SessionEventLogView>()
        .await?;
    assert!(!events.session.journal.is_empty());
    assert_eq!(events.daemon_outputs.len(), 1);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_input_rejects_concurrent_submissions_atomically() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let run_gate = Arc::new(Semaphore::new(0));
    let scripted_steps = (0..8)
        .map(|index| ScriptedStep::ReleaseAfterPermit {
            gate: run_gate.clone(),
            response: Ok(scripted_events(
                &format!("assistant-input-race-{index}"),
                &format!("INPUT_RACE_DONE_{index}"),
                kheish_types::ModelFinishReason::Completed,
            )),
        })
        .collect::<Vec<_>>();
    let (address, shutdown) = scripted_daemon_steps(&state_root, scripted_steps).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "input-race-session").await?;
    let url = format!("{base}/v1/sessions/input-race-session/input");
    let mut handles = Vec::new();
    for index in 0..8 {
        let client = client.clone();
        let url = url.clone();
        let mut request = test_submit_input_request("hold one inline input and reject the rest");
        request.binding_keys = vec![format!("input-race-binding-{index}")];
        handles.push(tokio::spawn(async move {
            let response = client.post(url).json(&request).send().await?;
            let status = response.status();
            let content_type = response
                .headers()
                .get(CONTENT_TYPE)
                .and_then(|value| value.to_str().ok())
                .map(ToOwned::to_owned);
            let body = response.text().await?;
            Ok::<(StatusCode, Option<String>, String), anyhow::Error>((status, content_type, body))
        }));
    }

    let deadline = tokio::time::Instant::now() + Duration::from_secs(15);
    loop {
        let runs = client
            .get(format!("{base}/v1/runs?session_id=input-race-session"))
            .send()
            .await?
            .error_for_status()?
            .json::<Vec<RunView>>()
            .await?;
        if runs
            .iter()
            .any(|run| run.status == DaemonRunStatus::Running)
        {
            break;
        }
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for one inline input to become active"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    run_gate.add_permits(8);

    let mut successes = 0usize;
    let mut conflicts = Vec::new();
    for handle in handles {
        let (status, content_type, body) = handle.await??;
        if status.is_success() {
            successes += 1;
            let view: SessionView = serde_json::from_str(&body)?;
            assert_eq!(view.session_id, "input-race-session");
        } else {
            assert_eq!(status, StatusCode::CONFLICT, "unexpected response: {body}");
            assert!(
                content_type
                    .as_deref()
                    .is_some_and(|value| value.starts_with("application/problem+json")),
                "busy response should use problem+json, got {content_type:?}: {body}"
            );
            let problem: ProblemDetails = serde_json::from_str(&body)?;
            assert_eq!(problem.domain.as_deref(), Some("sessions"));
            assert_eq!(problem.code, "session_busy");
            conflicts.push(problem);
        }
    }

    assert_eq!(successes, 1, "exactly one inline input may be accepted");
    assert_eq!(
        conflicts.len(),
        7,
        "remaining inline inputs must be rejected"
    );
    let runs = client
        .get(format!("{base}/v1/runs?session_id=input-race-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    assert_eq!(runs.len(), 1, "busy inline submits must not queue runs");
    assert_eq!(runs[0].status, DaemonRunStatus::Completed);
    let index = FileDaemonStore::new(&state_root).load_index()?;
    let input_race_bindings = index
        .bindings
        .keys()
        .filter(|binding| binding.starts_with("input-race-binding-"))
        .collect::<Vec<_>>();
    assert_eq!(
        input_race_bindings.len(),
        1,
        "busy inline submissions must not persist binding side effects: {input_race_bindings:?}"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_pauses_goal_after_permanent_goal_continuation_failure() -> Result<()> {
    let temp = tempdir()?;
    let address_root = temp.path().join("daemon-state");
    let permanent_error = || {
        Err(ProviderError {
            message: "OpenAI request failed with status 400: type=invalid_request_error"
                .to_string(),
            retryable: false,
            retry_after_ms: None,
        })
    };
    let (address, shutdown) =
        scripted_daemon(&address_root, vec![permanent_error(), permanent_error()]).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "goal-loop-session").await?;
    client
        .put(format!("{base}/v1/sessions/goal-loop-session/goal"))
        .json(&SetSessionGoalRequest {
            objective: "Keep working until a permanent provider error blocks the goal".to_string(),
            token_budget: None,
            status: Some(kheish_types::SessionGoalStatus::Active),
        })
        .send()
        .await?
        .error_for_status()?;

    let first = submit_test_input(&client, &base, "goal-loop-session", "start").await?;
    wait_for_run_status(&client, &base, &first.run_id, &[DaemonRunStatus::Failed]).await?;
    let runs = wait_for_session_run_count(&client, &base, "goal-loop-session", 2).await?;
    let continuation = runs
        .iter()
        .find(|run| run.kind == DaemonRunKind::GoalContinuation)
        .cloned()
        .ok_or_else(|| anyhow!("missing goal continuation run"))?;
    wait_for_run_status(
        &client,
        &base,
        &continuation.run_id,
        &[DaemonRunStatus::Failed],
    )
    .await?;

    tokio::time::sleep(Duration::from_millis(300)).await;
    let final_runs = client
        .get(format!("{base}/v1/runs?session_id=goal-loop-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    assert_eq!(
        final_runs.len(),
        2,
        "permanent continuation failure must not schedule another continuation"
    );

    let goal = client
        .get(format!("{base}/v1/sessions/goal-loop-session/goal"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionGoalResponse>()
        .await?
        .goal
        .expect("goal should remain");
    assert_eq!(goal.status, kheish_types::SessionGoalStatus::Paused);
    assert_eq!(
        goal.last_continuation_run_id.as_deref(),
        Some(continuation.run_id.as_str())
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_run_approval_idempotency_dedupes_retries() -> Result<()> {
    let temp = tempdir()?;
    let address_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &address_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-approval-1".to_string(),
                },
                ModelStreamEvent::TextDelta {
                    text: "Need approval.".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-approval-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "hello"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-approval-2",
                "APPROVAL_DONE",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "approval-idem-session").await?;
    let submitted = client
        .post(format!("{base}/v1/sessions/approval-idem-session/runs"))
        .json(&SubmitRunRequest {
            idempotency_key: None,
            request: SubmitInputRequest {
                source_plugin: None,
                source_kind: None,
                actor_id: None,
                provider: None,
                content: "run".to_string(),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                reply_address: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let waiting = wait_for_pending_approval_run(&client, &base, &submitted.run_id).await?;
    let approval_id = waiting
        .pending_approval_ids
        .first()
        .cloned()
        .context("expected one pending approval")?;

    let empty_response = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: Vec::new(),
        })
        .send()
        .await?;
    assert_eq!(empty_response.status(), StatusCode::BAD_REQUEST);
    let empty_problem = empty_response.json::<ProblemDetails>().await?;
    assert_eq!(empty_problem.domain.as_deref(), Some("approvals"));
    assert_eq!(empty_problem.code, "approval_batch_empty");
    let still_waiting = client
        .get(format!("{base}/v1/runs/{}", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(still_waiting.status, DaemonRunStatus::WaitingForApproval);
    assert_eq!(
        still_waiting.pending_approval_ids,
        vec![approval_id.clone()]
    );

    let approval_request = ResolveApprovalsRequest {
        idempotency_key: None,
        resolutions: vec![ApprovalResolution {
            request_id: approval_id.clone(),
            behavior: kheish_types::ApprovalResolutionBehavior::Allow,
            updated_input: None,
            justification: Some("approved".to_string()),
            reason: None,
        }],
    };
    let first = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .header("Idempotency-Key", "approval-key-1")
        .json(&approval_request)
        .send()
        .await?;
    assert_eq!(first.status(), StatusCode::ACCEPTED);
    let first_run = first.json::<RunView>().await?;
    assert_eq!(first_run.run_id, submitted.run_id);

    let retry = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .header("Idempotency-Key", "approval-key-1")
        .json(&approval_request)
        .send()
        .await?;
    assert_eq!(retry.status(), StatusCode::ACCEPTED);
    let retry_run = retry.json::<RunView>().await?;
    assert_eq!(retry_run.run_id, submitted.run_id);

    let conflicting = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .header("Idempotency-Key", "approval-key-1")
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: approval_id.clone(),
                behavior: kheish_types::ApprovalResolutionBehavior::Deny,
                updated_input: None,
                justification: Some("changed".to_string()),
                reason: Some("no".to_string()),
            }],
        })
        .send()
        .await?;
    assert_eq!(conflicting.status(), StatusCode::CONFLICT);
    let conflicting_problem = conflicting.json::<ProblemDetails>().await?;
    assert_eq!(conflicting_problem.domain.as_deref(), Some("idempotency"));
    assert_eq!(conflicting_problem.code, "idempotency_conflict");

    let completed = wait_for_run_status(
        &client,
        &base,
        &submitted.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    assert_eq!(
        completed
            .outputs
            .last()
            .map(|output| output.content.as_str()),
        Some("APPROVAL_DONE")
    );

    let events = client
        .get(format!("{base}/v1/runs/{}/events", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    let started_count = events
        .iter()
        .filter(|entry| matches!(entry.event, RunEvent::Started))
        .count();
    let resolved_count = events
        .iter()
        .filter(|entry| matches!(entry.event, RunEvent::ApprovalResolved { .. }))
        .count();
    assert_eq!(started_count, 2);
    assert_eq!(resolved_count, 1);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_approval_batch_atomicity_audit_and_multi_wave() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let client = Client::new();
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(vec![
            ModelStreamEvent::MessageId {
                value: "assistant-approval-batch-1".to_string(),
            },
            ModelStreamEvent::TextDelta {
                text: "Need two approvals.".to_string(),
            },
            ModelStreamEvent::ToolCall {
                call: kheish_types::ToolCallRecord {
                    id: "call-approval-batch-1".to_string(),
                    name: "echo".to_string(),
                    input: json!({"text": "first"}),
                    assistant_message_id: None,
                    assistant_provider_response_id: None,
                },
            },
            ModelStreamEvent::ToolCall {
                call: kheish_types::ToolCallRecord {
                    id: "call-approval-batch-2".to_string(),
                    name: "echo".to_string(),
                    input: json!({"text": "second"}),
                    assistant_message_id: None,
                    assistant_provider_response_id: None,
                },
            },
            ModelStreamEvent::Stop {
                reason: kheish_types::ModelFinishReason::ToolCalls,
            },
        ])],
    )
    .await?;
    let base = format!("http://{address}");

    create_test_session(&client, &base, "approval-batch-session").await?;
    let submitted = client
        .post(format!("{base}/v1/sessions/approval-batch-session/runs"))
        .json(&test_submit_input_request("needs two approvals"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let waiting = wait_for_pending_approval_run(&client, &base, &submitted.run_id).await?;
    assert_eq!(waiting.pending_approval_ids.len(), 2);
    let first_id = waiting.pending_approval_ids[0].clone();
    let second_id = waiting.pending_approval_ids[1].clone();

    let invalid = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![
                ApprovalResolution {
                    request_id: first_id.clone(),
                    behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                    updated_input: Some(json!({"text": "first-updated"})),
                    justification: Some("valid part of invalid batch".to_string()),
                    reason: None,
                },
                ApprovalResolution {
                    request_id: "approval-missing".to_string(),
                    behavior: kheish_types::ApprovalResolutionBehavior::Deny,
                    updated_input: None,
                    justification: Some("invalid part".to_string()),
                    reason: Some("unknown".to_string()),
                },
            ],
        })
        .send()
        .await?;
    assert_eq!(invalid.status(), StatusCode::BAD_REQUEST);
    let problem = invalid.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("approvals"));
    assert_eq!(problem.code, "approval_request_not_pending");

    let still_waiting = client
        .get(format!("{base}/v1/runs/{}", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(still_waiting.status, DaemonRunStatus::WaitingForApproval);
    assert_eq!(
        still_waiting.pending_approval_ids,
        waiting.pending_approval_ids
    );
    let events = client
        .get(format!("{base}/v1/runs/{}/events", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert!(
        !events
            .iter()
            .any(|entry| matches!(entry.event, RunEvent::ApprovalResolved { .. })),
        "invalid batch must not append an approval audit event: {events:#?}"
    );

    let first_wave = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .header("Idempotency-Key", "approval-batch-wave-1")
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: first_id.clone(),
                behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                updated_input: Some(json!({"text": "first-updated"})),
                justification: Some("wave one".to_string()),
                reason: None,
            }],
        })
        .send()
        .await?;
    assert_eq!(first_wave.status(), StatusCode::ACCEPTED);
    let first_wave = first_wave.json::<RunView>().await?;
    assert_eq!(first_wave.run_id, submitted.run_id);

    let waiting_after_first =
        wait_for_pending_approval_run(&client, &base, &submitted.run_id).await?;
    assert_eq!(
        waiting_after_first.pending_approval_ids,
        vec![second_id.clone()]
    );

    let _ = shutdown.send(());
    tokio::time::sleep(Duration::from_millis(100)).await;

    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-approval-batch-2",
            "APPROVAL_BATCH_DONE",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let base = format!("http://{address}");

    let restored = client
        .get(format!("{base}/v1/runs/{}", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(restored.status, DaemonRunStatus::WaitingForApproval);
    assert_eq!(restored.pending_approval_ids, vec![second_id.clone()]);
    let restored_session = client
        .get(format!("{base}/v1/sessions/approval-batch-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(
        restored_session.snapshot.agent.status,
        kheish_agent::AgentStatus::WaitingForApproval
    );
    assert_eq!(restored_session.snapshot.pending_approvals.len(), 1);

    let second_wave = client
        .post(format!("{base}/v1/runs/{}/approvals", submitted.run_id))
        .header("Idempotency-Key", "approval-batch-wave-2")
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: second_id.clone(),
                behavior: kheish_types::ApprovalResolutionBehavior::Deny,
                updated_input: None,
                justification: Some("wave two".to_string()),
                reason: Some("deny second tool".to_string()),
            }],
        })
        .send()
        .await?;
    assert_eq!(second_wave.status(), StatusCode::ACCEPTED);
    let completed = wait_for_run_status(
        &client,
        &base,
        &submitted.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(
        completed
            .outputs
            .last()
            .map(|output| output.content.as_str()),
        Some("APPROVAL_BATCH_DONE")
    );

    let events = client
        .get(format!("{base}/v1/runs/{}/events", submitted.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    let approvals = events
        .iter()
        .filter_map(|entry| match &entry.event {
            RunEvent::ApprovalResolved { resolutions } => Some(resolutions),
            _ => None,
        })
        .collect::<Vec<_>>();
    let waiting_events = events
        .iter()
        .filter_map(|entry| match &entry.event {
            RunEvent::WaitingForApproval { requests, .. } => Some(requests),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert!(
        waiting_events.iter().any(|requests| requests.len() == 2
            && requests.iter().any(
                |request| request.id == "approval-write_file-1" || request.tool_name == "echo"
            )),
        "waiting approval event should retain full request audit payloads: {events:#?}"
    );
    assert_eq!(approvals.len(), 2, "approval audit events: {events:#?}");
    assert_eq!(approvals[0].len(), 1);
    assert_eq!(approvals[0][0].request_id, first_id);
    assert_eq!(
        approvals[0][0].behavior,
        kheish_types::ApprovalResolutionBehavior::Allow
    );
    assert_eq!(
        approvals[0][0].updated_input,
        Some(json!({"text": "first-updated"}))
    );
    assert_eq!(approvals[0][0].justification.as_deref(), Some("wave one"));
    assert_eq!(approvals[1].len(), 1);
    assert_eq!(approvals[1][0].request_id, second_id);
    assert_eq!(
        approvals[1][0].behavior,
        kheish_types::ApprovalResolutionBehavior::Deny
    );
    assert_eq!(approvals[1][0].justification.as_deref(), Some("wave two"));
    assert_eq!(approvals[1][0].reason.as_deref(), Some("deny second tool"));

    let _ = shutdown.send(());
    Ok(())
}

