#[tokio::test]
async fn daemon_flow_tool_policy_fails_closed_on_scoped_violation() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-flow-tool-policy");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-flow-tool-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "flow-tool-call-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "FLOW_TOOL_POLICY_VIOLATION"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-flow-tool-2",
                "FLOW_TOOL_DONE",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "flow-tool-session").await?;
    let mut manifest = test_playbook_manifest("flow-tool-policy", "1.0.0");
    manifest.tools = PlaybookToolPolicy {
        enforce: true,
        allow: Vec::new(),
        deny: vec!["echo".to_string()],
    };
    let validation = client
        .post(format!("{base}/v1/playbooks/validate"))
        .json(&ValidatePlaybookRequest {
            manifest: manifest.clone(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<PlaybookValidationResult>()
        .await?;
    let digest = validation.digest.context("missing playbook digest")?;
    client
        .post(format!("{base}/v1/playbooks"))
        .json(&CreatePlaybookRequest { manifest })
        .send()
        .await?
        .error_for_status()?;
    client
        .post(format!("{base}/v1/playbooks/flow-tool-policy/publish"))
        .json(&PublishPlaybookRequest {
            version: "1.0.0".to_string(),
            digest: digest.clone(),
            status: Some(PlaybookReleaseStatus::Active),
            evidence_refs: test_release_evidence(),
        })
        .send()
        .await?
        .error_for_status()?;

    let started = client
        .post(format!("{base}/v1/flows"))
        .json(&StartFlowRequest {
            flow_id: Some("flow-tool-policy-1".to_string()),
            idempotency_key: Some("idem-flow-tool-policy-1".to_string()),
            playbook_ref: PlaybookVersionRef {
                playbook_id: "flow-tool-policy".to_string(),
                version: "1.0.0".to_string(),
                digest,
            },
            session_id: "flow-tool-session".to_string(),
            request: test_submit_input_request("execute tool policy flow"),
            metadata: Value::Null,
            evidence_refs: Vec::new(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<FlowView>()
        .await?;
    let run_id = started.run_id.context("flow should reference run")?;
    let waiting = wait_for_pending_approval_run(&client, &base, &run_id).await?;
    let approval_id = waiting
        .pending_approval_ids
        .first()
        .context("echo tool should require approval")?
        .clone();
    client
        .post(format!("{base}/v1/sessions/flow-tool-session/approvals"))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: approval_id,
                behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                updated_input: None,
                justification: Some("allow policy violation test".to_string()),
                reason: None,
            }],
        })
        .send()
        .await?
        .error_for_status()?;
    wait_for_run_status(&client, &base, &run_id, &[DaemonRunStatus::Completed]).await?;

    let flow = client
        .get(format!("{base}/v1/flows/flow-tool-policy-1"))
        .send()
        .await?
        .error_for_status()?
        .json::<FlowView>()
        .await?;
    assert_eq!(flow.status, FlowStatus::Failed);
    let tool_policy = flow
        .contract
        .checks
        .iter()
        .find(|check| check.name == "tool_policy")
        .context("missing tool policy check")?;
    assert!(!tool_policy.passed);
    assert!(tool_policy.details.contains("echo"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_flow_cancel_delegates_to_active_run() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-flow-cancel");
    let (address, shutdown) = slow_daemon(&state_root).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "flow-cancel-session").await?;
    let manifest = test_playbook_manifest("cancel-flow", "1.0.0");
    let validation = client
        .post(format!("{base}/v1/playbooks/validate"))
        .json(&ValidatePlaybookRequest {
            manifest: manifest.clone(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<PlaybookValidationResult>()
        .await?;
    let digest = validation
        .digest
        .context("validation should return a digest")?;
    client
        .post(format!("{base}/v1/playbooks"))
        .json(&CreatePlaybookRequest { manifest })
        .send()
        .await?
        .error_for_status()?;
    client
        .post(format!("{base}/v1/playbooks/cancel-flow/publish"))
        .json(&PublishPlaybookRequest {
            version: "1.0.0".to_string(),
            digest: digest.clone(),
            status: Some(PlaybookReleaseStatus::Active),
            evidence_refs: test_release_evidence(),
        })
        .send()
        .await?
        .error_for_status()?;

    let started = client
        .post(format!("{base}/v1/flows"))
        .json(&StartFlowRequest {
            flow_id: Some("flow-cancel-1".to_string()),
            idempotency_key: Some("idem-flow-cancel-1".to_string()),
            playbook_ref: PlaybookVersionRef {
                playbook_id: "cancel-flow".to_string(),
                version: "1.0.0".to_string(),
                digest,
            },
            session_id: "flow-cancel-session".to_string(),
            request: test_submit_input_request("stay active until flow cancel"),
            metadata: Value::Null,
            evidence_refs: Vec::new(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<FlowView>()
        .await?;
    let run_id = started
        .run_id
        .clone()
        .context("flow should reference a run")?;
    wait_for_run_status(&client, &base, &run_id, &[DaemonRunStatus::Running]).await?;

    let cancelled = client
        .post(format!("{base}/v1/flows/flow-cancel-1/cancel"))
        .send()
        .await?
        .error_for_status()?
        .json::<FlowView>()
        .await?;
    assert_eq!(cancelled.status, FlowStatus::Cancelled);
    assert_eq!(cancelled.run_id.as_deref(), Some(run_id.as_str()));
    assert_eq!(
        cancelled
            .run
            .as_ref()
            .context("cancelled flow should include run view")?
            .status,
        DaemonRunStatus::Cancelled
    );

    let run = client
        .get(format!("{base}/v1/runs/{run_id}"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(run.status, DaemonRunStatus::Cancelled);

    let _ = shutdown.send(());
    Ok(())
}

