#[tokio::test]
async fn daemon_run_writes_signed_external_action_audit_records() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-external-action-audit");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "msg-audit-1",
            "one audited reply",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let session = create_test_session(&client, &base, "audit-session").await?;
    let run = client
        .post(format!("{base}/v1/sessions/{}/runs", session.session_id))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "write one audited reply".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let completed =
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;

    let audit_path = resolve_storage_path_for_read(
        &state_root.join("external-actions"),
        &completed.run_id,
        "jsonl",
    );
    let content = fs::read_to_string(&audit_path).with_context(|| {
        format!(
            "missing external action audit file {}",
            audit_path.display()
        )
    })?;
    let records = content
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(serde_json::from_str::<serde_json::Value>)
        .collect::<std::result::Result<Vec<_>, _>>()?;

    assert!(
        records.iter().any(|record| {
            record["kind"].as_str() == Some("output_dispatch")
                && record["phase"].as_str() == Some("response")
                && record["record_hash"].as_str().is_some()
                && record["signature"].as_str().is_some()
                && record["key_id"].as_str().is_some()
        }),
        "expected one signed output_dispatch audit record in {audit_path:?}: {records:#?}"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn project_task_start_creates_discussion_thread_and_updates_run_linkage() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-project-start");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "msg-project-start-1",
            "project task started",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let base = format!("http://{address}");
    let client = Client::new();

    let session = create_test_session(&client, &base, "project-worker").await?;
    create_test_channel(&client, &base, "project-room", "Project Room", Vec::new()).await?;
    create_test_project(
        &client,
        &base,
        "project-alpha",
        &session.session_id,
        "project-room",
    )
    .await?;
    create_test_project_task(&client, &base, "project-alpha", "project-task-1").await?;

    let mirrored_members = client
        .get(format!("{base}/v1/channels/project-room/members"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ChannelMemberView>>()
        .await?;
    let mirrored_member_id = mirrored_project_channel_member_id("project-alpha", "worker");
    assert!(mirrored_members.iter().any(|member| {
        member.member_id == mirrored_member_id
            && member.session_id.as_deref() == Some(session.session_id.as_str())
    }));

    let started = client
        .post(format!(
            "{base}/v1/projects/project-alpha/tasks/project-task-1/start"
        ))
        .json(&crate::StartProjectTaskRequest::default())
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let completed = wait_for_run_status(
        &client,
        &base,
        &started.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(completed.run_id, started.run_id);

    let task = client
        .get(format!(
            "{base}/v1/projects/project-alpha/tasks/project-task-1"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<crate::ProjectTaskView>()
        .await?;
    assert_eq!(task.latest_run_id.as_deref(), Some(started.run_id.as_str()));
    assert_eq!(
        task.primary_session_id.as_deref(),
        Some(session.session_id.as_str())
    );
    assert_eq!(task.status, kheish_types::TaskStatus::Completed);
    assert_eq!(task.output.as_deref(), Some("project task started"));
    let discussion = task
        .discussion
        .clone()
        .ok_or_else(|| anyhow!("project task discussion was not created"))?;
    assert_eq!(discussion.channel_id, "project-room");

    let messages = client
        .get(format!("{base}/v1/channels/project-room/messages"))
        .query(&crate::ChannelMessageListQuery {
            thread_root_message_id: Some(discussion.thread_root_message_id.clone()),
            query: None,
            limit: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ChannelMessageView>>()
        .await?;
    assert_eq!(messages.len(), 1);
    assert_eq!(messages[0].sender.id, "project-control");
    assert_eq!(messages[0].message_id, discussion.thread_root_message_id);
    assert!(messages[0].thread_root_message_id.is_none());
    assert_eq!(messages[0].addressed_member_ids, vec![mirrored_member_id]);

    let room = client
        .get(format!("{base}/v1/channels/project-room/members"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ChannelMemberView>>()
        .await?;
    assert!(
        room.iter()
            .any(|member| member.member_id == "project-control")
    );

    let project = client
        .get(format!("{base}/v1/projects/project-alpha"))
        .send()
        .await?
        .error_for_status()?
        .json::<crate::ProjectView>()
        .await?;
    assert_eq!(project.summary.active_task_count, 0);

    let _ = shutdown.send(());
    Ok(())
}

