#[tokio::test]
async fn project_task_rejects_latest_run_from_another_session() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-project-run-validation");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "msg-project-validation-1",
            "validation run complete",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let base = format!("http://{address}");
    let client = Client::new();

    let owner_session = create_test_session(&client, &base, "project-validation-owner").await?;
    let other_session = create_test_session(&client, &base, "project-validation-other").await?;
    create_test_channel(
        &client,
        &base,
        "project-validation-room",
        "Project Validation Room",
        Vec::new(),
    )
    .await?;
    create_test_project(
        &client,
        &base,
        "project-validation",
        &owner_session.session_id,
        "project-validation-room",
    )
    .await?;

    client
        .post(format!(
            "{base}/v1/sessions/{}/input",
            other_session.session_id
        ))
        .json(&SubmitInputRequest {
            content: "Generate an unrelated run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            source_plugin: Some("tests".to_string()),
            source_kind: Some("validation".to_string()),
            actor_id: Some("tests".to_string()),
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
            generation: None,
            completion_requirements: None,
            provider: None,
        })
        .send()
        .await?
        .error_for_status()?;
    let run = wait_for_session_run_count(&client, &base, &other_session.session_id, 1)
        .await?
        .into_iter()
        .next()
        .ok_or_else(|| anyhow!("expected one run for session {}", other_session.session_id))?;
    let _ = wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;

    let create_task = client
        .post(format!("{base}/v1/projects/project-validation/tasks"))
        .json(&crate::CreateProjectTaskRequest {
            project_task_id: Some("project-task-validation".to_string()),
            title: "Validate run linkage".to_string(),
            description: "Runs must belong to the assigned session".to_string(),
            status: None,
            assignment: crate::ProjectTaskAssignmentRequest {
                assignee_member_id: Some("worker".to_string()),
                assignee_session_id: None,
                assignee_agent_id: None,
            },
            discussion_channel_id: None,
            discussion_thread_root_message_id: None,
            blocked_by: Vec::new(),
            latest_run_id: Some(run.run_id.clone()),
            output: None,
            metadata: json!({"fixture": true}),
        })
        .send()
        .await?;
    assert_eq!(create_task.status(), StatusCode::BAD_REQUEST);
    let body = create_task.text().await?;
    assert!(body.contains("belongs to session"));
    assert!(body.contains(owner_session.session_id.as_str()));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn project_task_create_rejects_active_latest_run() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-project-create-active-latest");
    let run_gate = Arc::new(Semaphore::new(0));
    let (address, shutdown) = scripted_daemon_steps(
        &state_root,
        vec![ScriptedStep::ReleaseAfterPermit {
            gate: run_gate.clone(),
            response: Ok(scripted_events(
                "msg-project-create-active-latest-1",
                "active latest run complete",
                kheish_types::ModelFinishReason::Completed,
            )),
        }],
    )
    .await?;
    let base = format!("http://{address}");
    let client = Client::new();

    let session =
        create_test_session(&client, &base, "project-create-active-latest-worker").await?;
    create_test_channel(
        &client,
        &base,
        "project-create-active-latest-room",
        "Project Create Active Latest Room",
        Vec::new(),
    )
    .await?;
    create_test_project(
        &client,
        &base,
        "project-create-active-latest",
        &session.session_id,
        "project-create-active-latest-room",
    )
    .await?;

    let active = client
        .post(format!("{base}/v1/sessions/{}/runs", session.session_id))
        .json(&test_submit_input_request("hold active latest run"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let _ =
        wait_for_run_status(&client, &base, &active.run_id, &[DaemonRunStatus::Running]).await?;

    let create_task = client
        .post(format!(
            "{base}/v1/projects/project-create-active-latest/tasks"
        ))
        .json(&crate::CreateProjectTaskRequest {
            project_task_id: Some("project-task-create-active-latest".to_string()),
            title: "Reject active latest".to_string(),
            description: "Active runs cannot seed task state".to_string(),
            status: Some(kheish_types::TaskStatus::Completed),
            assignment: crate::ProjectTaskAssignmentRequest {
                assignee_member_id: Some("worker".to_string()),
                assignee_session_id: None,
                assignee_agent_id: None,
            },
            discussion_channel_id: None,
            discussion_thread_root_message_id: None,
            blocked_by: Vec::new(),
            latest_run_id: Some(active.run_id.clone()),
            output: Some("caller output must not be accepted".to_string()),
            metadata: json!({"fixture": true}),
        })
        .send()
        .await?;
    assert_eq!(create_task.status(), StatusCode::BAD_REQUEST);
    assert!(create_task.text().await?.contains("must be terminal"));

    create_test_project_task(
        &client,
        &base,
        "project-create-active-latest",
        "project-task-update-active-latest",
    )
    .await?;
    let update_active = client
        .put(format!(
            "{base}/v1/projects/project-create-active-latest/tasks/project-task-update-active-latest"
        ))
        .json(&crate::UpdateProjectTaskRequest {
            status: Some(kheish_types::TaskStatus::Completed),
            latest_run_id: Some(active.run_id.clone()),
            output: Some("caller output must not be accepted".to_string()),
            ..crate::UpdateProjectTaskRequest::default()
        })
        .send()
        .await?;
    assert_eq!(update_active.status(), StatusCode::BAD_REQUEST);
    assert!(update_active.text().await?.contains("must be terminal"));

    run_gate.add_permits(1);
    let _ = wait_for_run_status(
        &client,
        &base,
        &active.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let created = client
        .post(format!(
            "{base}/v1/projects/project-create-active-latest/tasks"
        ))
        .json(&crate::CreateProjectTaskRequest {
            project_task_id: Some("project-task-create-terminal-latest".to_string()),
            title: "Create from terminal latest".to_string(),
            description: "Terminal runs seed canonical state".to_string(),
            status: Some(kheish_types::TaskStatus::Failed),
            assignment: crate::ProjectTaskAssignmentRequest {
                assignee_member_id: Some("worker".to_string()),
                assignee_session_id: None,
                assignee_agent_id: None,
            },
            discussion_channel_id: None,
            discussion_thread_root_message_id: None,
            blocked_by: Vec::new(),
            latest_run_id: Some(active.run_id.clone()),
            output: Some("caller output must be ignored".to_string()),
            metadata: json!({"fixture": true}),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<crate::ProjectTaskView>()
        .await?;
    assert_eq!(created.status, kheish_types::TaskStatus::Completed);
    assert_eq!(
        created.output.as_deref(),
        Some("active latest run complete")
    );

    let updated = client
        .put(format!(
            "{base}/v1/projects/project-create-active-latest/tasks/project-task-update-active-latest"
        ))
        .json(&crate::UpdateProjectTaskRequest {
            status: Some(kheish_types::TaskStatus::Failed),
            latest_run_id: Some(active.run_id.clone()),
            output: Some("caller output must be ignored".to_string()),
            ..crate::UpdateProjectTaskRequest::default()
        })
        .send()
        .await?
        .error_for_status()?
        .json::<crate::ProjectTaskView>()
        .await?;
    assert_eq!(updated.status, kheish_types::TaskStatus::Completed);
    assert_eq!(
        updated.output.as_deref(),
        Some("active latest run complete")
    );

    let _ = shutdown.send(());
    Ok(())
}

