#[tokio::test]
async fn daemon_channels_timeout_targeted_member_handoffs_to_next_candidate() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let beta_gate = Arc::new(Notify::new());
    let (address, shutdown) = scripted_daemon_steps(
        &state_root,
        vec![
            ScriptedStep::ReleaseAfter {
                gate: beta_gate.clone(),
                response: Ok(vec![
                    ModelStreamEvent::MessageId {
                        value: "assistant-beta-timeout-late-1".to_string(),
                    },
                    ModelStreamEvent::ToolCall {
                        call: kheish_types::ToolCallRecord {
                            id: "emit-beta-timeout-late-1".to_string(),
                            name: "emit_output".to_string(),
                            input: json!({
                                "content": "Late Aurora answer.",
                            }),
                            assistant_message_id: None,
                            assistant_provider_response_id: None,
                        },
                    },
                    ModelStreamEvent::Stop {
                        reason: kheish_types::ModelFinishReason::ToolCalls,
                    },
                ]),
            },
            ScriptedStep::Immediate(Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-alpha-timeout-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "emit-alpha-timeout-1".to_string(),
                        name: "emit_output".to_string(),
                        input: json!({
                            "content": "Atlas steps in because Aurora missed the response window.",
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ])),
            ScriptedStep::Immediate(Ok(scripted_events(
                "assistant-alpha-timeout-2",
                "Done.",
                kheish_types::ModelFinishReason::Completed,
            ))),
            ScriptedStep::Immediate(Ok(scripted_events(
                "assistant-beta-timeout-late-2",
                "Done.",
                kheish_types::ModelFinishReason::Completed,
            ))),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "alpha-room").await?;
    create_test_session(&client, &base, "beta-room").await?;
    client
        .post(format!("{base}/v1/channels"))
        .json(&crate::CreateChannelRequest {
            channel_id: Some("channel-timeout".to_string()),
            title: "timeout".to_string(),
            description: Some("timeout".to_string()),
            purpose: None,
            pinned_asset_ids: Vec::new(),
            created_by: None,
            members: vec![
                crate::ChannelMemberRequest {
                    member_id: "alice".to_string(),
                    member_kind: crate::ChannelMemberKind::HumanActor,
                    display_name_mode: None,
                    display_name: "Alice".to_string(),
                    session_id: None,
                    actor_id: Some("alice".to_string()),
                    role: Some("requester".to_string()),
                    expertise_tags: Vec::new(),
                    participation_mode: Some(crate::ChannelParticipationMode::ManualOnly),
                    muted: Some(false),
                },
                crate::ChannelMemberRequest {
                    member_id: "alpha-room".to_string(),
                    member_kind: crate::ChannelMemberKind::Session,
                    display_name_mode: None,
                    display_name: "Atlas".to_string(),
                    session_id: Some("alpha-room".to_string()),
                    actor_id: None,
                    role: Some("security".to_string()),
                    expertise_tags: vec!["audit".to_string()],
                    participation_mode: None,
                    muted: Some(false),
                },
                crate::ChannelMemberRequest {
                    member_id: "beta-room".to_string(),
                    member_kind: crate::ChannelMemberKind::Session,
                    display_name_mode: None,
                    display_name: "Aurora".to_string(),
                    session_id: Some("beta-room".to_string()),
                    actor_id: None,
                    role: Some("ops".to_string()),
                    expertise_tags: vec!["linear".to_string()],
                    participation_mode: None,
                    muted: Some(false),
                },
            ],
            autonomy_policy: Some(crate::ChannelAutonomyPolicy {
                max_parallel_public_speakers: 1,
                max_agent_replies_per_human_message: 2,
                member_cooldown_ms: 15_000,
                lease_timeout_ms: 150,
                ..Default::default()
            }),
            default_participation_mode: None,
            metadata: Value::Null,
        })
        .send()
        .await?
        .error_for_status()?;

    let posted = client
        .post(format!("{base}/v1/channels/channel-timeout/messages"))
        .json(&crate::PostChannelMessageRequest {
            sender_actor_id: "alice".to_string(),
            sender_display_name: Some("Alice".to_string()),
            sender_session_id: None,
            thread_root_message_id: None,
            reply_to_message_id: None,
            addressed_member_ids: Vec::new(),
            input_items: Vec::new(),
            content: Some("Aurora, peux-tu répondre en premier ?".to_string()),
            metadata: json!({"source": "test"}),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<crate::ChannelMessageView>()
        .await?;
    assert_eq!(posted.addressed_member_ids, vec!["beta-room".to_string()]);

    let beta_run = wait_for_session_run_count(&client, &base, "beta-room", 1)
        .await?
        .last()
        .cloned()
        .ok_or_else(|| anyhow!("missing beta timeout run"))?;
    wait_for_run_status(
        &client,
        &base,
        &beta_run.run_id,
        &[DaemonRunStatus::Running, DaemonRunStatus::Cancelled],
    )
    .await?;

    let alpha_runs = wait_for_session_run_count(&client, &base, "alpha-room", 1).await?;
    let alpha_run = alpha_runs
        .last()
        .cloned()
        .ok_or_else(|| anyhow!("missing alpha timeout run"))?;
    wait_for_run_status(
        &client,
        &base,
        &alpha_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    wait_for_run_status(
        &client,
        &base,
        &beta_run.run_id,
        &[DaemonRunStatus::Cancelled],
    )
    .await?;
    beta_gate.notify_one();

    let messages = wait_for_channel_message_count(&client, &base, "channel-timeout", 2).await?;
    assert_eq!(messages.len(), 2);
    assert_eq!(messages[1].sender_session_id.as_deref(), Some("alpha-room"));
    assert!(
        messages
            .iter()
            .all(|message| message.sender_session_id.as_deref() != Some("beta-room")),
        "timed-out addressed run should not publish a stale public reply"
    );
    let leases = client
        .get(format!("{base}/v1/channels/channel-timeout/leases"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ChannelTurnLeaseView>>()
        .await?;
    assert!(
        leases.is_empty(),
        "handoff should finish without stale leases"
    );

    let _ = shutdown.send(());
    let (restart_address, restart_shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let restart_base = format!("http://{restart_address}");
    let restart_messages =
        wait_for_channel_message_count(&client, &restart_base, "channel-timeout", 2).await?;
    assert!(
        restart_messages
            .iter()
            .all(|message| message.sender_session_id.as_deref() != Some("beta-room")),
        "restart must not recover and publish the cancelled stale addressed run"
    );
    let restart_beta_run = wait_for_run_status(
        &client,
        &restart_base,
        &beta_run.run_id,
        &[DaemonRunStatus::Cancelled],
    )
    .await?;
    assert_eq!(restart_beta_run.status, DaemonRunStatus::Cancelled);
    let restart_leases = client
        .get(format!("{restart_base}/v1/channels/channel-timeout/leases"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ChannelTurnLeaseView>>()
        .await?;
    assert!(
        restart_leases.is_empty(),
        "restart must not recreate a stale lease for the cancelled run"
    );
    let _ = restart_shutdown.send(());
    Ok(())
}

