#[tokio::test]
async fn daemon_coding_write_file_expected_sha256_allows_one_concurrent_writer() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let target = state_root.join("cas.txt");
    fs::write(&target, "initial\n")?;
    let mut hasher = Sha256::new();
    hasher.update(b"initial\n");
    let initial_sha = format!("{:x}", hasher.finalize());

    let (address, shutdown) = scripted_daemon_with_default_coding_tools(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-coding-cas-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-coding-cas-1".to_string(),
                        name: "write_file".to_string(),
                        input: json!({
                            "path": "cas.txt",
                            "content": "writer-one\n",
                            "expected_sha256": initial_sha,
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-coding-cas-2".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-coding-cas-2".to_string(),
                        name: "write_file".to_string(),
                        input: json!({
                            "path": "cas.txt",
                            "content": "writer-two\n",
                            "expected_sha256": initial_sha,
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-coding-cas-3",
                "CAS_DONE",
                kheish_types::ModelFinishReason::Completed,
            )),
            Ok(scripted_events(
                "assistant-coding-cas-4",
                "CAS_DONE",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "coding-cas-one").await?;
    create_test_session(&client, &base, "coding-cas-two").await?;
    let (run_one, run_two) = tokio::try_join!(
        submit_test_input(&client, &base, "coding-cas-one", "writer one"),
        submit_test_input(&client, &base, "coding-cas-two", "writer two")
    )?;
    let (completed_one, completed_two) = tokio::try_join!(
        wait_for_run_status(
            &client,
            &base,
            &run_one.run_id,
            &[DaemonRunStatus::Completed]
        ),
        wait_for_run_status(
            &client,
            &base,
            &run_two.run_id,
            &[DaemonRunStatus::Completed]
        )
    )?;
    assert!(
        completed_one
            .outputs
            .iter()
            .any(|output| output.content.contains("CAS_DONE"))
            && completed_two
                .outputs
                .iter()
                .any(|output| output.content.contains("CAS_DONE")),
        "CAS runs did not complete with expected marker: {} / {}",
        serde_json::to_string_pretty(&completed_one)?,
        serde_json::to_string_pretty(&completed_two)?
    );

    let final_content = fs::read_to_string(&target)?;
    assert!(
        matches!(final_content.as_str(), "writer-one\n" | "writer-two\n"),
        "unexpected final CAS content: {final_content:?}"
    );

    let mut successes = 0;
    let mut mismatches = 0;
    for session_id in ["coding-cas-one", "coding-cas-two"] {
        let events = client
            .get(format!("{base}/v1/sessions/{session_id}/events"))
            .send()
            .await?
            .error_for_status()?
            .json::<SessionEventLogView>()
            .await?;
        for result in events
            .session
            .journal
            .iter()
            .filter_map(|entry| match &entry.event {
                SessionEvent::ToolCallFinished { result }
                    if result.tool_name.as_deref() == Some("write_file") =>
                {
                    Some(result)
                }
                _ => None,
            })
        {
            if result.is_error {
                let error = result.output["error"].as_str().unwrap_or_default();
                assert!(
                    error.contains("expected_sha256 mismatch"),
                    "unexpected CAS write_file error: {}",
                    serde_json::to_string_pretty(&result.output)?
                );
                mismatches += 1;
            } else {
                successes += 1;
            }
        }
    }
    assert_eq!(successes, 1, "exactly one CAS writer should succeed");
    assert_eq!(mismatches, 1, "exactly one CAS writer should fail");

    let _ = shutdown.send(());
    Ok(())
}

