#[tokio::test]
async fn daemon_concurrent_cancel_is_idempotent_for_waiting_runs() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(vec![
            ModelStreamEvent::MessageId {
                value: "assistant-concurrent-cancel-1".to_string(),
            },
            ModelStreamEvent::TextDelta {
                text: "Need approval.".to_string(),
            },
            ModelStreamEvent::ToolCall {
                call: kheish_types::ToolCallRecord {
                    id: "call-concurrent-cancel-1".to_string(),
                    name: "echo".to_string(),
                    input: json!({"text": "hello"}),
                    assistant_message_id: None,
                    assistant_provider_response_id: None,
                },
            },
            ModelStreamEvent::Stop {
                reason: kheish_types::ModelFinishReason::ToolCalls,
            },
        ])],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("concurrent-cancel-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let run = client
        .post(format!("{base}/v1/sessions/concurrent-cancel-session/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "needs approval".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let waiting = wait_for_pending_approval_run(&client, &base, &run.run_id).await?;

    let cancel_url = format!("{base}/v1/runs/{}/cancel", waiting.run_id);
    let left_client = client.clone();
    let right_client = client.clone();
    let left_url = cancel_url.clone();
    let right_url = cancel_url.clone();
    let (left, right) = tokio::join!(
        async move {
            let run = left_client
                .post(left_url)
                .send()
                .await?
                .error_for_status()?
                .json::<RunView>()
                .await?;
            Ok::<RunView, anyhow::Error>(run)
        },
        async move {
            let run = right_client
                .post(right_url)
                .send()
                .await?
                .error_for_status()?
                .json::<RunView>()
                .await?;
            Ok::<RunView, anyhow::Error>(run)
        }
    );
    let left = left?;
    let right = right?;
    assert_eq!(left.status, DaemonRunStatus::Cancelled);
    assert_eq!(right.status, DaemonRunStatus::Cancelled);

    let repeated = client
        .post(cancel_url)
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(repeated.status, DaemonRunStatus::Cancelled);

    let events = client
        .get(format!("{base}/v1/runs/{}/events", waiting.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    let cancelled_events = events
        .iter()
        .filter(|entry| matches!(entry.event, RunEvent::Cancelled))
        .count();
    assert_eq!(
        cancelled_events,
        1,
        "cancel should be durable and idempotent: {}",
        serde_json::to_string_pretty(&events)?
    );

    let session = client
        .get(format!("{base}/v1/sessions/concurrent-cancel-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(session.snapshot.pending_approvals.is_empty());
    assert_eq!(
        session.snapshot.agent.status,
        kheish_agent::AgentStatus::Idle
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_concurrent_cancel_and_approval_resume_settle_once() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let approval_gate = Arc::new(Notify::new());
    let (address, shutdown) = scripted_daemon_steps(
        &state_root,
        vec![
            ScriptedStep::Immediate(Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-cancel-approval-race-1".to_string(),
                },
                ModelStreamEvent::TextDelta {
                    text: "Need approval.".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-cancel-approval-race-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "hello"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ])),
            ScriptedStep::ReleaseAfter {
                gate: approval_gate.clone(),
                response: Ok(scripted_events(
                    "assistant-cancel-approval-race-2",
                    "SHOULD_NOT_DOUBLE_SETTLE",
                    kheish_types::ModelFinishReason::Completed,
                )),
            },
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "cancel-approval-race-session").await?;
    let run = client
        .post(format!(
            "{base}/v1/sessions/cancel-approval-race-session/runs"
        ))
        .json(&test_submit_input_request(
            "needs approval then races cancel",
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let waiting = wait_for_pending_approval_run(&client, &base, &run.run_id).await?;
    let approval_id = waiting
        .pending_approval_ids
        .first()
        .cloned()
        .ok_or_else(|| anyhow!("missing pending approval id"))?;

    let cancel_client = client.clone();
    let cancel_url = format!("{base}/v1/runs/{}/cancel", waiting.run_id);
    let cancel_task = tokio::spawn(async move {
        let response = cancel_client.post(cancel_url).send().await?;
        let status = response.status();
        let body = response.text().await?;
        Ok::<(StatusCode, String), anyhow::Error>((status, body))
    });

    let approval_client = client.clone();
    let approval_url = format!("{base}/v1/sessions/cancel-approval-race-session/approval-runs");
    let approval_task = tokio::spawn(async move {
        let response = approval_client
            .post(approval_url)
            .json(&ResolveApprovalsRequest {
                idempotency_key: None,
                resolutions: vec![ApprovalResolution {
                    request_id: approval_id,
                    behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                    updated_input: None,
                    justification: Some("approved during race".to_string()),
                    reason: None,
                }],
            })
            .send()
            .await?;
        let status = response.status();
        let body = response.text().await?;
        Ok::<(StatusCode, String), anyhow::Error>((status, body))
    });

    let (cancel_response, approval_response) = tokio::join!(cancel_task, approval_task);
    let (cancel_status, cancel_body) = cancel_response??;
    let (approval_status, approval_body) = approval_response??;
    assert_eq!(
        cancel_status,
        StatusCode::OK,
        "cancel must remain idempotent during approval race: {cancel_body}"
    );
    assert!(
        approval_status == StatusCode::OK || approval_status == StatusCode::CONFLICT,
        "approval race should either resume once or see the cancelled state, got {approval_status}: {approval_body}"
    );
    approval_gate.notify_waiters();

    let final_run = wait_for_run_status(
        &client,
        &base,
        &waiting.run_id,
        &[DaemonRunStatus::Cancelled],
    )
    .await?;
    assert!(final_run.pending_approval_ids.is_empty());
    assert!(final_run.pending_question_ids.is_empty());

    let events = client
        .get(format!("{base}/v1/runs/{}/events", waiting.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert_eq!(
        events
            .iter()
            .filter(|entry| matches!(entry.event, RunEvent::Cancelled))
            .count(),
        1,
        "cancel/resume race should record one terminal event: {events:#?}"
    );
    assert!(
        !events
            .iter()
            .any(|entry| matches!(entry.event, RunEvent::Completed)),
        "cancel/resume race must not also complete the run: {events:#?}"
    );

    let session = client
        .get(format!("{base}/v1/sessions/cancel-approval-race-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(session.snapshot.pending_approvals.is_empty());
    assert_eq!(
        session.snapshot.agent.status,
        kheish_agent::AgentStatus::Idle
    );

    let _ = shutdown.send(());
    Ok(())
}

