#[tokio::test]
async fn daemon_session_run_idempotency_recovers_pending_receipt_after_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let session_id = "idempotent-pending-session";
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some(session_id.to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;
    let _ = shutdown.send(());

    let request = test_submit_input_request("reply with PENDING_RECLAIM_OK");
    let idempotency_key = "idem-pending-reclaim-1";
    let key_hash = hex::encode(Sha256::digest(idempotency_key.as_bytes()));
    let request_fingerprint = {
        let payload = json!({
            "version": 1,
            "request": &request,
        });
        hex::encode(Sha256::digest(serde_json::to_vec(&payload)?))
    };
    let store = FileDaemonStore::new(&state_root);
    let mut index = store.load_index()?;
    index.session_run_idempotency_receipts.insert(
        format!("session-run:{session_id}:{key_hash}"),
        crate::state::SessionRunIdempotencyReceiptState::Pending {
            run_id: "run-1".to_string(),
            request_fingerprint,
            recorded_at_ms: crate::runs::now_ms(),
        },
    );
    store.save_index(&index)?;

    let (restart_address, restart_shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(scripted_events(
                "assistant-idempotent-pending-1",
                "PENDING_RECLAIM_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
            Ok(scripted_events(
                "assistant-idempotent-pending-2",
                "NEXT_UNIQUE_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let restart_base = format!("http://{restart_address}");
    let reclaimed = client
        .post(format!("{restart_base}/v1/sessions/{session_id}/runs"))
        .header("Idempotency-Key", idempotency_key)
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(reclaimed.run_id, "run-1");
    wait_for_run_status(
        &client,
        &restart_base,
        &reclaimed.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let unique = client
        .post(format!("{restart_base}/v1/sessions/{session_id}/runs"))
        .json(&test_submit_input_request("reply with NEXT_UNIQUE_OK"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(unique.run_id, "run-2");

    let _ = restart_shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_restart_interrupts_active_input_run_and_reconciles_events() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let client = Client::new();

    let (address, shutdown) = slow_daemon(&state_root).await?;
    let base = format!("http://{address}");
    create_test_session(&client, &base, "restart-active-input-session").await?;
    let run = client
        .post(format!(
            "{base}/v1/sessions/restart-active-input-session/runs"
        ))
        .json(&test_submit_input_request("stay active across restart"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Running]).await?;
    let _ = shutdown.send(());

    let (restart_address, restart_shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-restart-active-input-next",
            "RESTART_ACTIVE_NEXT_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let restart_base = format!("http://{restart_address}");

    let interrupted = client
        .get(format!("{restart_base}/v1/runs/{}", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(interrupted.status, DaemonRunStatus::Interrupted);
    assert_eq!(
        interrupted.error.as_deref(),
        Some("daemon restarted while the run was active")
    );
    assert!(
        interrupted.finished_at_ms.is_some(),
        "interrupted run should carry a terminal timestamp"
    );
    assert!(interrupted.pending_approval_ids.is_empty());
    assert!(interrupted.pending_question_ids.is_empty());

    let events = client
        .get(format!("{restart_base}/v1/runs/{}/events", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert!(
        events
            .iter()
            .any(|entry| matches!(entry.event, RunEvent::Accepted)),
        "restart-recovered run should retain an accepted event: {events:#?}"
    );
    assert!(
        events
            .iter()
            .any(|entry| matches!(entry.event, RunEvent::Started)),
        "restart-recovered run should retain a started event: {events:#?}"
    );
    assert_eq!(
        events
            .iter()
            .filter(|entry| matches!(entry.event, RunEvent::Interrupted))
            .count(),
        1,
        "restart recovery should reconcile exactly one interrupted event: {events:#?}"
    );

    let next = client
        .post(format!(
            "{restart_base}/v1/sessions/restart-active-input-session/runs"
        ))
        .json(&test_submit_input_request(
            "reply with RESTART_ACTIVE_NEXT_OK",
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let completed = wait_for_run_status(
        &client,
        &restart_base,
        &next.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        completed.outputs[0]
            .content
            .contains("RESTART_ACTIVE_NEXT_OK"),
        "restart should release the session queue after interrupting the stale active run: {}",
        serde_json::to_string_pretty(&completed)?
    );

    let _ = restart_shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_restart_reconciles_active_supervisor_tree() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let client = Client::new();

    let (address, shutdown) = slow_daemon(&state_root).await?;
    let base = format!("http://{address}");
    let root = create_test_session(&client, &base, "restart-active-tree-root").await?;
    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&bare_sidechain_request(
            "restart-active-tree-child",
            Some("restart-active-tree-child-thread"),
            None,
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let grandchild = client
        .post(format!("{base}/v1/agents/{}/sidechains", child.agent_id))
        .json(&bare_sidechain_request(
            "restart-active-tree-grandchild",
            Some("restart-active-tree-grandchild-thread"),
            None,
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let child_run = submit_test_input(
        &client,
        &base,
        &child.session_id,
        "child stays active across restart",
    )
    .await?;
    let grandchild_run = submit_test_input(
        &client,
        &base,
        &grandchild.session_id,
        "grandchild stays active across restart",
    )
    .await?;
    wait_for_run_status(
        &client,
        &base,
        &child_run.run_id,
        &[DaemonRunStatus::Running],
    )
    .await?;
    wait_for_run_status(
        &client,
        &base,
        &grandchild_run.run_id,
        &[DaemonRunStatus::Running],
    )
    .await?;
    let _ = shutdown.send(());

    let (restart_address, restart_shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(scripted_events(
                "assistant-active-tree-child-next",
                "ACTIVE_TREE_CHILD_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
            Ok(scripted_events(
                "assistant-active-tree-grandchild-next",
                "ACTIVE_TREE_GRANDCHILD_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let restart_base = format!("http://{restart_address}");

    for run_id in [&child_run.run_id, &grandchild_run.run_id] {
        let interrupted = client
            .get(format!("{restart_base}/v1/runs/{run_id}"))
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        assert_eq!(interrupted.status, DaemonRunStatus::Interrupted);
        assert_eq!(
            interrupted.error.as_deref(),
            Some("daemon restarted while the run was active")
        );
    }

    let summaries = client
        .get(format!(
            "{restart_base}/v1/agents/summaries?root_agent_id={}",
            root.agent_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<AgentSummaryView>>()
        .await?;
    assert_eq!(summaries.len(), 3);
    for agent_id in [&root.agent_id, &child.agent_id, &grandchild.agent_id] {
        let summary = summaries
            .iter()
            .find(|summary| summary.agent_id == *agent_id)
            .ok_or_else(|| anyhow!("missing restored summary for {agent_id}"))?;
        assert_eq!(
            summary.status,
            AgentStatus::Idle,
            "interrupted runs recovered during restart should reconcile supervisor state back to idle: {summaries:#?}"
        );
        assert!(
            summary.has_runtime,
            "active supervisor tree agents should restore runtime handles: {summaries:#?}"
        );
    }

    let child_next = submit_test_input(
        &client,
        &restart_base,
        &child.session_id,
        "reply with ACTIVE_TREE_CHILD_OK",
    )
    .await?;
    let completed_child = wait_for_run_status(
        &client,
        &restart_base,
        &child_next.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        completed_child.outputs[0]
            .content
            .contains("ACTIVE_TREE_CHILD_OK")
    );
    let grandchild_next = submit_test_input(
        &client,
        &restart_base,
        &grandchild.session_id,
        "reply with ACTIVE_TREE_GRANDCHILD_OK",
    )
    .await?;
    let completed_grandchild = wait_for_run_status(
        &client,
        &restart_base,
        &grandchild_next.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        completed_grandchild.outputs[0]
            .content
            .contains("ACTIVE_TREE_GRANDCHILD_OK")
    );

    let _ = restart_shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_run_prune_removes_debug_evidence_without_deleting_run_history() -> Result<()> {
    let _env = DebugCaptureEnvGuard::without_debug_env();
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-prune-debug-1",
            "PRUNE_DEBUG_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let invalid_prune = client
        .post(format!("{base}/v1/runs/prune"))
        .json(&RunRetentionPruneRequest {
            older_than_ms: 0,
            session_id: None,
            limit: None,
            dry_run: false,
        })
        .send()
        .await?;
    assert_eq!(invalid_prune.status(), StatusCode::BAD_REQUEST);
    assert!(
        invalid_prune
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = invalid_prune.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runs"));
    assert_eq!(problem.code, "run_retention_invalid_request");

    let invalid_limit = client
        .post(format!("{base}/v1/runs/prune"))
        .json(&RunRetentionPruneRequest {
            older_than_ms: 1,
            session_id: None,
            limit: Some(0),
            dry_run: false,
        })
        .send()
        .await?;
    assert_eq!(invalid_limit.status(), StatusCode::BAD_REQUEST);
    let problem = invalid_limit.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runs"));
    assert_eq!(problem.code, "run_retention_invalid_request");

    client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Full,
            expected_revision: None,
        })
        .send()
        .await?
        .error_for_status()?;
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("prune-debug-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;
    let run = client
        .post(format!("{base}/v1/sessions/prune-debug-session/runs"))
        .json(&test_submit_input_request("reply with PRUNE_DEBUG_OK"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;
    tokio::time::sleep(Duration::from_millis(5)).await;

    let debug = client
        .get(format!("{base}/v1/runs/{}/debug", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunDebugView>()
        .await?;
    assert!(!debug.artifacts.is_empty());

    let dry_run = client
        .post(format!("{base}/v1/runs/prune"))
        .json(&RunRetentionPruneRequest {
            older_than_ms: 1,
            session_id: Some("prune-debug-session".to_string()),
            limit: Some(10),
            dry_run: true,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunRetentionPruneResponse>()
        .await?;
    assert_eq!(dry_run.limit, Some(10));
    assert_eq!(dry_run.matched_run_count, 1);
    assert_eq!(dry_run.candidate_run_ids, vec![run.run_id.clone()]);
    assert!(dry_run.candidate_debug_bytes > 0);
    assert!(dry_run.pruned_debug_run_ids.is_empty());
    assert_eq!(dry_run.pruned_debug_bytes, 0);

    let pruned = client
        .post(format!("{base}/v1/runs/prune"))
        .json(&RunRetentionPruneRequest {
            older_than_ms: 1,
            session_id: Some("prune-debug-session".to_string()),
            limit: Some(10),
            dry_run: false,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunRetentionPruneResponse>()
        .await?;
    assert_eq!(pruned.limit, Some(10));
    assert_eq!(pruned.matched_run_count, 1);
    assert_eq!(pruned.candidate_debug_bytes, dry_run.candidate_debug_bytes);
    assert_eq!(pruned.pruned_debug_run_ids, vec![run.run_id.clone()]);
    assert_eq!(pruned.pruned_debug_bytes, dry_run.candidate_debug_bytes);

    let debug_status = client
        .get(format!("{base}/v1/runs/{}/debug", run.run_id))
        .send()
        .await?
        .status();
    assert_eq!(debug_status, StatusCode::OK);
    let debug_after = client
        .get(format!("{base}/v1/runs/{}/debug", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<RunDebugView>()
        .await?;
    assert!(debug_after.artifacts.is_empty());
    client
        .get(format!("{base}/v1/runs/{}", run.run_id))
        .send()
        .await?
        .error_for_status()?;
    let events = client
        .get(format!("{base}/v1/runs/{}/events", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert!(!events.is_empty());

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_session_interrupt_releases_waiting_approval_runs() -> Result<()> {
    let temp = tempdir()?;
    let address_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &address_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-interrupt-1".to_string(),
                },
                ModelStreamEvent::TextDelta {
                    text: "Need approval.".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-interrupt-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "hello"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-interrupt-2",
                "INTERRUPT_QUEUED_DONE",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("interrupt-waiting-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let blocked = client
        .post(format!("{base}/v1/sessions/interrupt-waiting-session/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "needs approval".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let blocked = wait_for_pending_approval_run(&client, &base, &blocked.run_id).await?;

    let queued = client
        .post(format!("{base}/v1/sessions/interrupt-waiting-session/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "second task".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(queued.status, DaemonRunStatus::Queued);

    let interrupted = client
        .post(format!(
            "{base}/v1/sessions/interrupt-waiting-session/interrupt"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<InterruptSessionResponse>()
        .await?;
    assert!(interrupted.interrupted);
    assert_eq!(
        interrupted.snapshot.agent.status,
        kheish_agent::AgentStatus::Idle
    );

    let interrupted_run = wait_for_run_status(
        &client,
        &base,
        &blocked.run_id,
        &[DaemonRunStatus::Interrupted],
    )
    .await?;
    assert_eq!(interrupted_run.status, DaemonRunStatus::Interrupted);

    let completed = wait_for_run_status(
        &client,
        &base,
        &queued.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        completed.outputs[0]
            .content
            .contains("INTERRUPT_QUEUED_DONE"),
        "unexpected queued-run output: {}",
        serde_json::to_string_pretty(&completed)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runs_many_sessions_in_parallel_without_cross_talk() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(75)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let session_ids = (0..10)
        .map(|index| format!("parallel-{index}"))
        .collect::<Vec<_>>();
    for session_id in &session_ids {
        client
            .post(format!("{base}/v1/sessions"))
            .json(&CreateSessionRequest {
                session_id: Some(session_id.clone()),
                thread_id: None,
                persona_id: None,
                credential_scope: None,
                capability_scope: None,
            })
            .send()
            .await?
            .error_for_status()?;
    }

    let mut run_ids = Vec::new();
    for session_id in &session_ids {
        let run = client
            .post(format!("{base}/v1/sessions/{session_id}/runs"))
            .json(&SubmitInputRequest {
                source_plugin: None,
                source_kind: None,
                actor_id: None,
                provider: None,
                content: format!("report for {session_id}"),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                reply_address: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
            })
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        run_ids.push((session_id.clone(), run.run_id));
    }

    for (session_id, run_id) in &run_ids {
        let run =
            wait_for_run_status(&client, &base, run_id, &[DaemonRunStatus::Completed]).await?;
        assert_eq!(run.session_id, *session_id);
        assert_eq!(run.outputs.len(), 1);
        assert!(
            run.outputs[0]
                .content
                .contains(&format!("ECHO:report for {session_id}"))
        );
        assert_eq!(run.outputs[0].run_id.as_deref(), Some(run_id.as_str()));
    }

    let _ = shutdown.send(());
    Ok(())
}

