#[tokio::test]
async fn daemon_subagent_start_hook_payload_normalizes_legacy_attachments() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let hook_payload_path = temp.path().join("subagent-start-hook.json");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "hook-sidechain-root").await?;
    let png = import_test_asset(
        &client,
        &base,
        "plan.png",
        "image/png",
        &sample_png_bytes()?,
    )
    .await?;
    let pdf = import_test_asset(
        &client,
        &base,
        "constraints.pdf",
        "application/pdf",
        &sample_pdf_bytes("HOOK_SIDECHAIN_ATTACHMENT_OK")?,
    )
    .await?;

    client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: std::iter::once((
                HookEventName::SubagentStart,
                vec![kheish_types::HookDefinition {
                    name: "capture-subagent-start".to_string(),
                    matcher: None,
                    failure_policy: Default::default(),
                    executor: kheish_types::HookExecutorConfig::Command {
                        command: format!("cat > '{}'", hook_payload_path.display()),
                        shell: None,
                        timeout_ms: Some(1_000),
                    },
                }],
            ))
            .collect(),
        })
        .send()
        .await?
        .error_for_status()?;

    client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&SpawnSidechainRequest {
            session_id: Some("hook-sidechain-child".to_string()),
            thread_id: Some("hook-sidechain-thread".to_string()),
            route_policy: None,
            provider: None,
            permission_mode: None,
            retention: None,
            nickname: None,
            spawned_by_run_id: None,
            spawn_request_id: None,
            fork_context: ForkContext {
                parent_assistant_message: String::new(),
                inherited_tool_call_ids: Vec::new(),
                team_name: Some("review".to_string()),
                isolation: None,
                system_prompt: String::new(),
                prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
                provider: None,
                generation: None,
                tool_surface: kheish_types::ToolSurfaceFilter::default(),
                worktree_path: None,
            },
            generation: None,
            tool_surface: None,
            capability_scope: None,
            credential_scope: None,
            subtask: Some(SidechainSubtaskRequest {
                name: "review-assets".to_string(),
                description: "Inspect the provided legacy attachment bundle.".to_string(),
                content: "Review the plan and constraints.".to_string(),
                input_items: Vec::new(),
                attachments: vec![
                    asset_reference(png.asset_id.clone()),
                    asset_reference(pdf.asset_id.clone()),
                ],
            }),
        })
        .send()
        .await?
        .error_for_status()?;

    let invocation: Value = serde_json::from_str(&fs::read_to_string(&hook_payload_path)?)?;
    let items = invocation["payload"]["subtask"]["input_items"]
        .as_array()
        .ok_or_else(|| anyhow!("subagent start hook input_items should be an array"))?;
    assert_eq!(items.len(), 3);
    assert_eq!(items[0]["type"], "text");
    assert_eq!(items[0]["text"], "Review the plan and constraints.");
    assert_eq!(items[1]["type"], "asset_reference");
    assert_eq!(items[1]["asset_id"], png.asset_id);
    assert_eq!(items[2]["type"], "asset_reference");
    assert_eq!(items[2]["asset_id"], pdf.asset_id);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_subagent_start_hook_payload_sanitizes_inline_assets() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let hook_payload_path = temp.path().join("subagent-start-inline-hook.json");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "hook-inline-sidechain-root").await?;
    let inline_base64 = BASE64_STANDARD.encode(sample_png_bytes()?);

    client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: std::iter::once((
                HookEventName::SubagentStart,
                vec![kheish_types::HookDefinition {
                    name: "capture-inline-subagent-start".to_string(),
                    matcher: None,
                    failure_policy: Default::default(),
                    executor: kheish_types::HookExecutorConfig::Command {
                        command: format!("cat > '{}'", hook_payload_path.display()),
                        shell: None,
                        timeout_ms: Some(1_000),
                    },
                }],
            ))
            .collect(),
        })
        .send()
        .await?
        .error_for_status()?;

    client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&SpawnSidechainRequest {
            session_id: Some("hook-inline-sidechain-child".to_string()),
            thread_id: Some("hook-inline-sidechain-thread".to_string()),
            route_policy: None,
            provider: None,
            permission_mode: None,
            retention: None,
            nickname: None,
            spawned_by_run_id: None,
            spawn_request_id: None,
            fork_context: ForkContext {
                parent_assistant_message: String::new(),
                inherited_tool_call_ids: Vec::new(),
                team_name: Some("review".to_string()),
                isolation: None,
                system_prompt: String::new(),
                prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
                provider: None,
                generation: None,
                tool_surface: kheish_types::ToolSurfaceFilter::default(),
                worktree_path: None,
            },
            generation: None,
            tool_surface: None,
            capability_scope: None,
            credential_scope: None,
            subtask: Some(SidechainSubtaskRequest {
                name: "review-assets".to_string(),
                description: "Inspect one inline upload.".to_string(),
                content: String::new(),
                input_items: vec![
                    text_input_item("Review the inline candidate."),
                    SubmitInputItemRequest::InlineAsset(InlineAssetUpload {
                        file_name: "inline-plan.png".to_string(),
                        media_type: Some("image/png".to_string()),
                        content_base64: inline_base64.clone(),
                    }),
                ],
                attachments: Vec::new(),
            }),
        })
        .send()
        .await?
        .error_for_status()?;

    let raw_payload = fs::read_to_string(&hook_payload_path)?;
    assert!(
        !raw_payload.contains(&inline_base64),
        "subagent start hook payload should not include inline base64 blobs"
    );
    let invocation: Value = serde_json::from_str(&raw_payload)?;
    let items = invocation["payload"]["subtask"]["input_items"]
        .as_array()
        .ok_or_else(|| anyhow!("subagent start hook input_items should be an array"))?;
    assert_eq!(items.len(), 2);
    assert_eq!(items[0]["type"], "text");
    assert_eq!(items[0]["text"], "Review the inline candidate.");
    assert_eq!(items[1]["type"], "inline_asset");
    assert_eq!(items[1]["file_name"], "inline-plan.png");
    assert_eq!(items[1]["media_type"], "image/png");
    assert!(items[1].get("content_base64").is_none());

    let _ = shutdown.send(());
    Ok(())
}

