#[tokio::test]
async fn daemon_mailbox_failed_delivery_requeues_generic_message() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Err(ProviderError {
                message: "simulated generic mailbox failure".to_string(),
                retryable: false,
                retry_after_ms: None,
            }),
            Ok(scripted_events(
                "assistant-generic-mailbox-retry-2",
                "GENERIC_MAILBOX_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "mailbox-retry-root").await?;
    let sidechain = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&bare_sidechain_request(
            "mailbox-retry-child",
            Some("mailbox-retry-thread"),
            None,
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let post = client
        .post(format!("{base}/v1/mailboxes"))
        .json(&PostMailboxRequest {
            message_id: Some("mailbox-generic-retry".to_string()),
            from_agent_id: root.agent_id.clone(),
            to_agent_id: sidechain.agent_id.clone(),
            subject: "handoff".to_string(),
            ttl_ms: None,
            payload: json!({"message": "retry this"}),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<PostMailboxResponse>()
        .await?;
    assert_eq!(post.message_id, "mailbox-generic-retry");
    assert!(!post.duplicate);

    let runs = wait_for_session_run_count(&client, &base, &sidechain.session_id, 2).await?;
    let mut failed_count = 0usize;
    let mut completed = None;
    for run in runs {
        let settled = wait_for_run_status(
            &client,
            &base,
            &run.run_id,
            &[DaemonRunStatus::Failed, DaemonRunStatus::Completed],
        )
        .await?;
        match settled.status {
            DaemonRunStatus::Failed => failed_count += 1,
            DaemonRunStatus::Completed => completed = Some(settled),
            _ => {}
        }
    }
    assert_eq!(failed_count, 1);
    let completed = completed.ok_or_else(|| anyhow!("missing retried mailbox completion"))?;
    assert!(
        completed.outputs[0].content.contains("GENERIC_MAILBOX_OK"),
        "retry should deliver the generic mailbox message: {}",
        serde_json::to_string_pretty(&completed)?
    );

    let mailbox: Vec<MailboxMessage> = client
        .get(format!("{base}/v1/agents/{}/mailbox", sidechain.agent_id))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert!(mailbox.is_empty());
    let dead_letters: Vec<MailboxMessage> = client
        .get(format!(
            "{base}/v1/agents/{}/mailbox/dead-letter",
            sidechain.agent_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert!(dead_letters.is_empty());

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_mailbox_delivery_max_attempts_moves_to_dlq() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Err(ProviderError {
                message: "mailbox failure 1".to_string(),
                retryable: false,
                retry_after_ms: None,
            }),
            Err(ProviderError {
                message: "mailbox failure 2".to_string(),
                retryable: false,
                retry_after_ms: None,
            }),
            Err(ProviderError {
                message: "mailbox failure 3".to_string(),
                retryable: false,
                retry_after_ms: None,
            }),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "mailbox-dlq-root").await?;
    let sidechain = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&bare_sidechain_request(
            "mailbox-dlq-child",
            Some("mailbox-dlq-thread"),
            None,
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    client
        .post(format!("{base}/v1/mailboxes"))
        .json(&PostMailboxRequest {
            message_id: Some("mailbox-max-attempts".to_string()),
            from_agent_id: root.agent_id.clone(),
            to_agent_id: sidechain.agent_id.clone(),
            subject: "handoff".to_string(),
            ttl_ms: None,
            payload: json!({"message": "fail three times"}),
        })
        .send()
        .await?
        .error_for_status()?;

    let runs = wait_for_session_run_count(&client, &base, &sidechain.session_id, 3).await?;
    for run in runs {
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Failed]).await?;
    }
    tokio::time::sleep(Duration::from_millis(100)).await;

    let dead_letters: Vec<MailboxMessage> = client
        .get(format!(
            "{base}/v1/agents/{}/mailbox/dead-letter",
            sidechain.agent_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert_eq!(dead_letters.len(), 1);
    assert_eq!(dead_letters[0].id, "mailbox-max-attempts");
    assert_eq!(dead_letters[0].delivery_attempts, 3);
    assert!(
        dead_letters[0]
            .last_error
            .as_deref()
            .unwrap_or_default()
            .contains("failed after 3 attempts")
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_mailbox_expired_on_restart_moves_to_dlq() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "mailbox-ttl-root").await?;
    let sidechain = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&bare_sidechain_request(
            "mailbox-ttl-child",
            Some("mailbox-ttl-thread"),
            None,
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let _ = shutdown.send(());
    tokio::time::sleep(Duration::from_millis(50)).await;

    let store = FileDaemonStore::new(&state_root);
    let mut supervisor = store
        .load_supervisor()?
        .ok_or_else(|| anyhow!("missing supervisor snapshot"))?;
    let now = now_ms();
    supervisor
        .mailboxes
        .entry(AgentId(sidechain.agent_id.clone()))
        .or_default()
        .push(MailboxMessage::new(
            "mailbox-expired-restart".to_string(),
            AgentId(root.agent_id.clone()),
            AgentId(sidechain.agent_id.clone()),
            "expired".to_string(),
            json!({"message": "too old"}),
            now.saturating_sub(10_000),
            Some(now.saturating_sub(1)),
        ));
    store.save_supervisor(&supervisor)?;

    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let base = format!("http://{address}");
    tokio::time::sleep(Duration::from_millis(100)).await;

    let mailbox: Vec<MailboxMessage> = client
        .get(format!("{base}/v1/agents/{}/mailbox", sidechain.agent_id))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert!(mailbox.is_empty());
    let dead_letters: Vec<MailboxMessage> = client
        .get(format!(
            "{base}/v1/agents/{}/mailbox/dead-letter",
            sidechain.agent_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert_eq!(dead_letters.len(), 1);
    assert_eq!(dead_letters[0].id, "mailbox-expired-restart");
    assert_eq!(dead_letters[0].state, MailboxMessageState::DeadLetter);

    let _ = shutdown.send(());
    Ok(())
}

