#[tokio::test]
async fn daemon_preserves_learned_context_after_user_question_resume() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-learning-question-resume");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let responses_owned = [
        openai_tool_call_response(
            "question-item-1",
            "question-call-learning-1",
            "ask_user_question",
            json!({
                "questions": [{
                    "id": "focus",
                    "header": "Focus",
                    "question": "Which focus should I use?",
                    "options": [
                        {"id": "memory", "label": "memory"},
                        {"id": "other", "label": "other"}
                    ]
                }]
            }),
            12,
            4,
        ),
        openai_text_response("LEARNED_CONTEXT_AFTER_QUESTION_OK", 10, 3),
    ];
    let responses = responses_owned
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url.clone();
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    create_test_session(&client, &base, "learning-question-demo").await?;
    create_and_publish_test_learning(
        &client,
        &base,
        kheish_types::LearningScope {
            kind: kheish_types::LearningScopeKind::Session,
            id: "learning-question-demo".to_string(),
        },
        kheish_types::LearningKind::Fact,
        "Question resume color is cerulean.",
    )
    .await?;

    let run = submit_test_input(
        &client,
        &base,
        "learning-question-demo",
        "Ask me one question, then answer with learned context.",
    )
    .await?;
    let waiting = wait_for_pending_question_run(&client, &base, &run.run_id).await?;
    assert_eq!(
        waiting.pending_question_ids,
        vec!["question-request-question-call-learning-1".to_string()]
    );

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let restart_config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut restart_provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    restart_provider.base_url = base_url;
    let (restart_service, restart_listener) =
        build_openai_daemon(restart_config, restart_provider).await?;
    let restart_address = restart_listener.local_addr()?;
    let (restart_shutdown, restart_shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = restart_service
            .serve_with_shutdown(restart_listener, async move {
                let _ = restart_shutdown_rx.await;
            })
            .await;
    });
    let restart_client = Client::new();
    let restart_base = format!("http://{restart_address}");
    wait_for_daemon_ready(&restart_client, &restart_base).await?;

    let questions = restart_client
        .get(format!(
            "{restart_base}/v1/sessions/learning-question-demo/questions"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<PendingQuestionView>>()
        .await?;
    assert_eq!(questions.len(), 1);

    restart_client
        .post(format!("{restart_base}/v1/runs/{}/questions", run.run_id))
        .json(&ResolveUserQuestionRequest {
            idempotency_key: None,
            resolution: kheish_types::UserQuestionResolution {
                request_id: questions[0].request.id.clone(),
                answers: vec![kheish_types::UserQuestionAnswer {
                    question_id: "focus".to_string(),
                    selected_option_ids: vec!["memory".to_string()],
                    freeform_answer: None,
                }],
                declined: false,
                justification: Some("selected in learned-context resume test".to_string()),
            },
        })
        .send()
        .await?
        .error_for_status()?;
    wait_for_run_status(
        &restart_client,
        &restart_base,
        &run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let captured_requests = captured_requests.lock().clone();
    assert_eq!(captured_requests.len(), 2);
    for (index, request) in captured_requests.iter().enumerate() {
        let payload = serde_json::from_str::<Value>(request)?;
        let instructions = payload["instructions"]
            .as_str()
            .ok_or_else(|| anyhow!("missing provider instructions in request {index}"))?;
        assert!(
            instructions.contains("# Learned Context"),
            "request {index} should include learned context: {instructions}"
        );
        assert!(
            instructions.contains("Question resume color is cerulean."),
            "request {index} lost learned context: {instructions}"
        );
    }

    let _ = restart_shutdown.send(());
    Ok(())
}

