#[tokio::test]
async fn daemon_ranks_learned_context_against_pending_input_before_prompt_injection() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-learned-context-ranking");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let responses_owned = vec![
        openai_text_response("ranked learning answered", 10, 3),
        openai_text_response("unrelated learning omitted", 10, 3),
    ];
    let responses = responses_owned
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    create_test_session(&client, &base, "learning-ranking-demo").await?;

    let session_candidate = client
        .post(format!("{base}/v1/learning-candidates"))
        .json(&CreateLearningCandidateRequest {
            scope: kheish_types::LearningScope {
                kind: kheish_types::LearningScopeKind::Session,
                id: "learning-ranking-demo".to_string(),
            },
            kind: kheish_types::LearningKind::Preference,
            sensitivity: kheish_types::LearningSensitivity::Scoped,
            content: "Default snack preference is banana.".to_string(),
            confidence: 90,
            source: kheish_types::LearningSourceRef {
                session_id: Some("learning-ranking-demo".to_string()),
                ..kheish_types::LearningSourceRef::default()
            },
            evidence_refs: Vec::new(),
            expires_at_ms: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<LearningCandidateView>()
        .await?;
    let session_learning = client
        .post(format!(
            "{base}/v1/learning-candidates/{}/publish",
            session_candidate.candidate_id
        ))
        .json(&PublishLearningCandidateRequest::default())
        .send()
        .await?
        .error_for_status()?
        .json::<LearningView>()
        .await?;

    let workspace_candidate = client
        .post(format!("{base}/v1/learning-candidates"))
        .json(&CreateLearningCandidateRequest {
            scope: kheish_types::LearningScope {
                kind: kheish_types::LearningScopeKind::Workspace,
                id: kheish_types::DEFAULT_WORKSPACE_LEARNING_SCOPE_ID.to_string(),
            },
            kind: kheish_types::LearningKind::Fact,
            sensitivity: kheish_types::LearningSensitivity::Scoped,
            content: "Atlas project color is vermilion.".to_string(),
            confidence: 96,
            source: kheish_types::LearningSourceRef::default(),
            evidence_refs: Vec::new(),
            expires_at_ms: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<LearningCandidateView>()
        .await?;
    let workspace_learning = client
        .post(format!(
            "{base}/v1/learning-candidates/{}/publish",
            workspace_candidate.candidate_id
        ))
        .json(&PublishLearningCandidateRequest::default())
        .send()
        .await?
        .error_for_status()?
        .json::<LearningView>()
        .await?;

    let context = client
        .get(format!(
            "{base}/v1/sessions/learning-ranking-demo/memory-context"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionMemoryContextView>()
        .await?;
    assert_eq!(
        context
            .learned_context
            .as_ref()
            .expect("learned context")
            .entries
            .iter()
            .map(|entry| entry.learning_id.as_str())
            .collect::<Vec<_>>(),
        vec![
            session_learning.learning_id.as_str(),
            workspace_learning.learning_id.as_str()
        ]
    );
    let queried_context = client
        .get(format!(
            "{base}/v1/sessions/learning-ranking-demo/memory-context?query=Atlas"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionMemoryContextView>()
        .await?;
    assert_eq!(
        queried_context
            .learned_context
            .as_ref()
            .expect("queried learned context")
            .entries
            .iter()
            .map(|entry| entry.learning_id.as_str())
            .collect::<Vec<_>>(),
        vec![workspace_learning.learning_id.as_str()]
    );

    let run = submit_test_input(
        &client,
        &base,
        "learning-ranking-demo",
        "What color is Atlas?",
    )
    .await?;
    wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;

    let captured_after_ranked = captured_requests.lock().clone();
    assert_eq!(captured_after_ranked.len(), 1);
    let payload = serde_json::from_str::<Value>(&captured_after_ranked[0])?;
    let instructions = payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions"))?;
    assert!(
        instructions.contains("Atlas project color is vermilion."),
        "missing relevant workspace learning: {instructions}"
    );
    assert!(
        !instructions.contains("Default snack preference is banana."),
        "zero-score session learning should be omitted when a query-relevant learning matched: {instructions}"
    );

    let searched = client
        .get(format!(
            "{base}/v1/sessions/learning-ranking-demo/memory-search?query=Atlas"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionMemorySearchView>()
        .await?;
    let first_learning = searched
        .results
        .iter()
        .find(|result| result.kind == SessionMemorySearchResultKind::Learning)
        .ok_or_else(|| anyhow!("missing learning search result"))?;
    assert_eq!(first_learning.source_id, workspace_learning.learning_id);
    assert!(first_learning.score > 0);
    assert!(
        first_learning
            .matched_fields
            .iter()
            .any(|field| field == "content")
    );

    let unrelated_run = submit_test_input(
        &client,
        &base,
        "learning-ranking-demo",
        "What is the deployment status?",
    )
    .await?;
    wait_for_run_status(
        &client,
        &base,
        &unrelated_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    let captured_after_unrelated = captured_requests.lock().clone();
    assert_eq!(captured_after_unrelated.len(), 2);
    let unrelated_payload = serde_json::from_str::<Value>(&captured_after_unrelated[1])?;
    let unrelated_instructions = unrelated_payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions"))?;
    assert!(
        !unrelated_instructions.contains("Atlas project color is vermilion."),
        "unrelated input must not inject zero-score workspace learning: {unrelated_instructions}"
    );
    assert!(
        !unrelated_instructions.contains("Default snack preference is banana."),
        "unrelated input must not inject zero-score session learning: {unrelated_instructions}"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_learning_automation_rejects_secrets_and_escalates_conflicts() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-semantic-learning-policy-guards");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");
    create_test_session(&client, &base, "semantic-guards-demo").await?;

    let seed_candidate = client
        .post(format!("{base}/v1/learning-candidates"))
        .json(&CreateLearningCandidateRequest {
            scope: kheish_types::LearningScope {
                kind: kheish_types::LearningScopeKind::Session,
                id: "semantic-guards-demo".to_string(),
            },
            kind: kheish_types::LearningKind::Fact,
            sensitivity: kheish_types::LearningSensitivity::Scoped,
            content: "Project codename is Atlas.".to_string(),
            confidence: 99,
            source: kheish_types::LearningSourceRef::default(),
            evidence_refs: Vec::new(),
            expires_at_ms: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<LearningCandidateView>()
        .await?;
    let seed_learning = client
        .post(format!(
            "{base}/v1/learning-candidates/{}/publish",
            seed_candidate.candidate_id
        ))
        .json(&PublishLearningCandidateRequest::default())
        .send()
        .await?
        .error_for_status()?
        .json::<LearningView>()
        .await?;
    assert_eq!(seed_learning.status, kheish_types::LearningStatus::Active);

    client
        .post(format!("{base}/v1/runtime/learning-policy"))
        .json(&LearningAutomationPolicyConfig {
            mode: LearningAutomationMode::Enabled,
            capture: LearningCapturePolicy {
                run_summary_candidates: false,
                semantic_candidates: LearningSemanticCaptureConfig::default(),
            },
            publication: LearningPublicationPolicy {
                default_action: LearningPublicationAction::ManualReview,
                allow_api_origin_active_publication: true,
                quarantined_rule_names: Vec::new(),
                rules: vec![LearningPublicationRule {
                    name: Some("api-session-fact".to_string()),
                    scope_kind: Some(kheish_types::LearningScopeKind::Session),
                    scope_id: Some("semantic-guards-demo".to_string()),
                    kind: Some(kheish_types::LearningKind::Fact),
                    sensitivity: Some(kheish_types::LearningSensitivity::Scoped),
                    min_confidence: Some(90),
                    require_evidence: false,
                    require_source_run: false,
                    require_source_session: false,
                    action: LearningPublicationAction::PublishActive,
                    expires_after_ms: None,
                }],
            },
            judge: LearningJudgeConfig::default(),
        })
        .send()
        .await?
        .error_for_status()?;

    let secret_response = client
        .post(format!("{base}/v1/learning-candidates"))
        .json(&CreateLearningCandidateRequest {
            scope: kheish_types::LearningScope {
                kind: kheish_types::LearningScopeKind::Session,
                id: "semantic-guards-demo".to_string(),
            },
            kind: kheish_types::LearningKind::Fact,
            sensitivity: kheish_types::LearningSensitivity::Scoped,
            content: "The API key is sk-proj-secret.".to_string(),
            confidence: 99,
            source: kheish_types::LearningSourceRef::default(),
            evidence_refs: Vec::new(),
            expires_at_ms: None,
        })
        .send()
        .await?;
    assert_eq!(secret_response.status(), StatusCode::BAD_REQUEST);
    assert!(secret_response.text().await?.contains("secret material"));

    let conflicting_candidate = client
        .post(format!("{base}/v1/learning-candidates"))
        .json(&CreateLearningCandidateRequest {
            scope: kheish_types::LearningScope {
                kind: kheish_types::LearningScopeKind::Session,
                id: "semantic-guards-demo".to_string(),
            },
            kind: kheish_types::LearningKind::Fact,
            sensitivity: kheish_types::LearningSensitivity::Scoped,
            content: "Project codename is Borealis.".to_string(),
            confidence: 99,
            source: kheish_types::LearningSourceRef::default(),
            evidence_refs: Vec::new(),
            expires_at_ms: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<LearningCandidateView>()
        .await?;

    let deadline = Instant::now() + Duration::from_secs(5);
    let conflict = loop {
        let conflict = client
            .get(format!(
                "{base}/v1/learning-candidates/{}",
                conflicting_candidate.candidate_id
            ))
            .send()
            .await?
            .error_for_status()?
            .json::<LearningCandidateView>()
            .await?;
        if conflict.state == LearningCandidateState::Escalated {
            break conflict;
        }
        if Instant::now() >= deadline {
            bail!(
                "timed out waiting for semantic conflict guard: conflict={:?}",
                conflict.state
            );
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    };
    assert!(conflict.automation_review.as_ref().is_some_and(|review| {
        review.action == LearningPublicationAction::ManualReview
            && review.reason.contains(seed_learning.learning_id.as_str())
    }));
    let learnings = client
        .get(format!(
            "{base}/v1/learnings?scope_kind=session&scope_id=semantic-guards-demo"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<LearningView>>()
        .await?;
    assert_eq!(
        learnings
            .iter()
            .map(|learning| learning.learning_id.as_str())
            .collect::<Vec<_>>(),
        vec![seed_learning.learning_id.as_str()]
    );

    let manual_conflict = client
        .post(format!(
            "{base}/v1/learning-candidates/{}/publish",
            conflicting_candidate.candidate_id
        ))
        .json(&PublishLearningCandidateRequest::default())
        .send()
        .await?;
    assert_eq!(manual_conflict.status(), StatusCode::CONFLICT);
    assert!(
        manual_conflict
            .text()
            .await?
            .contains("conflicts with active learning")
    );

    let replacement = client
        .post(format!(
            "{base}/v1/learning-candidates/{}/publish",
            conflicting_candidate.candidate_id
        ))
        .json(&PublishLearningCandidateRequest {
            supersedes: Some(seed_learning.learning_id.clone()),
            ..PublishLearningCandidateRequest::default()
        })
        .send()
        .await?
        .error_for_status()?
        .json::<LearningView>()
        .await?;
    assert_eq!(replacement.status, kheish_types::LearningStatus::Active);
    assert_eq!(
        replacement.supersedes.as_deref(),
        Some(seed_learning.learning_id.as_str())
    );
    let superseded_seed = client
        .get(format!("{base}/v1/learnings/{}", seed_learning.learning_id))
        .send()
        .await?
        .error_for_status()?
        .json::<LearningView>()
        .await?;
    assert_eq!(
        superseded_seed.status,
        kheish_types::LearningStatus::Superseded
    );
    assert_eq!(
        superseded_seed.superseded_by.as_deref(),
        Some(replacement.learning_id.as_str())
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_recovers_recent_run_memory_after_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-recovered-memory-restart");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let responses = vec![
        concat!(
            "event: response.output_item.added\n",
            "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-memory-r1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-memory-r1\",\"output_index\":0,\"content_index\":0,\"delta\":\"restart stored\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":9,\"output_tokens\":3}}}\n\n"
        ),
        concat!(
            "event: response.output_item.added\n",
            "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-memory-r2\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-memory-r2\",\"output_index\":0,\"content_index\":0,\"delta\":\"restart second run\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":11,\"output_tokens\":2}}}\n\n"
        ),
    ];
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url.clone();
    let (service, listener) = build_openai_daemon(config.clone(), provider.clone()).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("memory-restart-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let first_run = client
        .post(format!("{base}/v1/sessions/memory-restart-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Remember the restart marker.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    let _ = shutdown.send(());

    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let base = format!("http://{address}");
    let second_run = client
        .post(format!("{base}/v1/sessions/memory-restart-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Use the recovered memory after restart.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &second_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let captured_requests = captured_requests.lock().clone();
    assert_eq!(captured_requests.len(), 2);
    let second_payload = serde_json::from_str::<Value>(&captured_requests[1])?;
    let instructions = second_payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions in second request"))?;
    assert!(instructions.contains("# Recovered Memory"));
    assert!(instructions.contains("Request: Remember the restart marker."));
    assert!(instructions.contains("Result: restart stored"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_ignores_corrupted_run_memory_records() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-corrupted-memory");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let responses = vec![
        concat!(
            "event: response.output_item.added\n",
            "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-memory-c1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-memory-c1\",\"output_index\":0,\"content_index\":0,\"delta\":\"corrupt me\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":9,\"output_tokens\":3}}}\n\n"
        ),
        concat!(
            "event: response.output_item.added\n",
            "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-memory-c2\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-memory-c2\",\"output_index\":0,\"content_index\":0,\"delta\":\"second run despite corruption\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":11,\"output_tokens\":2}}}\n\n"
        ),
    ];
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("memory-corruption-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let first_run = client
        .post(format!("{base}/v1/sessions/memory-corruption-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Create memory that will be corrupted.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let memory_path = FileRunMemoryStore::new(&state_root).run_memory_path(&first_run.run_id);
    std::fs::write(&memory_path, "{broken")?;

    let second_run = client
        .post(format!("{base}/v1/sessions/memory-corruption-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Proceed even if older memory is unreadable.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &second_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let captured_requests = captured_requests.lock().clone();
    assert_eq!(captured_requests.len(), 2);
    let second_payload = serde_json::from_str::<Value>(&captured_requests[1])?;
    let instructions = second_payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions in second request"))?;
    assert!(
        !instructions.contains("# Recovered Memory"),
        "corrupted memory should be skipped: {}",
        serde_json::to_string_pretty(&second_payload)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_boots_with_corrupted_index_run_and_schedule_files() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-corrupted-boot");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(scripted_events(
                "assistant-corrupt-run-1",
                "RUN_ONE_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
            Ok(scripted_events(
                "assistant-corrupt-run-2",
                "RUN_TWO_OK",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "corruption-demo").await?;

    let first_run = client
        .post(format!("{base}/v1/sessions/corruption-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "first run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: vec!["team:alpha".to_string()],
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let schedule = create_test_schedule(
        &client,
        &base,
        CreateScheduleRequest {
            name: "corrupted-once".to_string(),
            target_session_id: "corruption-demo".to_string(),
            target_agent_id: None,
            owner_session_id: Some("corruption-demo".to_string()),
            owner_agent_id: Some("agent-1".to_string()),
            created_by_run_id: None,
            cadence: ScheduleCadence::Once {
                fire_at_ms: crate::now_ms() + 1_200,
            },
            max_executions: None,
            overlap_policy: ScheduleOverlapPolicy::Skip,
            misfire_policy: ScheduleMisfirePolicy::CoalesceOnce,
            request: Some(SubmitInputRequest {
                source_plugin: Some("scheduler".to_string()),
                source_kind: Some("test".to_string()),
                actor_id: Some("schedule-test".to_string()),
                provider: None,
                content: "trigger corrupted schedule".to_string(),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
                reply_address: None,
            }),
            observation_materialization: None,
            flow_start: None,
        },
    )
    .await?;

    let response = client
        .post(format!(
            "{base}/v1/schedules/{}/trigger",
            schedule.schedule_id
        ))
        .send()
        .await?
        .error_for_status()?;
    let triggered = response.json::<crate::ScheduleMutationResponse>().await?;
    assert_eq!(triggered.schedule.schedule_id, schedule.schedule_id);

    let runs = wait_for_session_run_count(&client, &base, "corruption-demo", 2).await?;
    let scheduled_run = runs
        .iter()
        .find(|run| run.kind == DaemonRunKind::ScheduledInput)
        .ok_or_else(|| anyhow!("missing scheduled run after trigger"))?;
    wait_for_run_status(
        &client,
        &base,
        &scheduled_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let daemon_index_path = state_root.join("daemon-index.json");
    let schedule_path = state_root
        .join("schedules")
        .join(format!("{}.json", schedule.schedule_id));
    let scheduled_run_path = FileRunStore::new(&state_root).run_path(&scheduled_run.run_id);
    fs::write(&daemon_index_path, "{broken-index")?;
    fs::write(&schedule_path, "{broken-schedule")?;
    fs::write(&scheduled_run_path, "{broken-run")?;

    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-corrupt-run-3",
            "RUN_THREE_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let base = format!("http://{address}");

    let session = client
        .get(format!("{base}/v1/sessions/corruption-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(session.session_id, "corruption-demo");

    let restored_runs = client
        .get(format!("{base}/v1/runs?session_id=corruption-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    assert_eq!(restored_runs.len(), 1, "corrupted run should be skipped");
    assert_eq!(restored_runs[0].run_id, first_run.run_id);
    assert!(
        restored_runs[0]
            .outputs
            .iter()
            .any(|output| output.content.contains("RUN_ONE_OK"))
    );

    let restored_schedules = client
        .get(format!("{base}/v1/schedules"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::ScheduleView>>()
        .await?;
    assert!(
        restored_schedules.is_empty(),
        "corrupted schedule should be skipped"
    );

    let replacement_schedule = create_test_schedule(
        &client,
        &base,
        CreateScheduleRequest {
            name: "replacement-once".to_string(),
            target_session_id: "corruption-demo".to_string(),
            target_agent_id: None,
            owner_session_id: Some("corruption-demo".to_string()),
            owner_agent_id: Some("agent-1".to_string()),
            created_by_run_id: None,
            cadence: ScheduleCadence::Once {
                fire_at_ms: crate::now_ms() + 1_200,
            },
            max_executions: None,
            overlap_policy: ScheduleOverlapPolicy::Skip,
            misfire_policy: ScheduleMisfirePolicy::CoalesceOnce,
            request: Some(SubmitInputRequest {
                source_plugin: Some("scheduler".to_string()),
                source_kind: Some("test".to_string()),
                actor_id: Some("schedule-test".to_string()),
                provider: None,
                content: "replacement schedule".to_string(),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
                reply_address: None,
            }),
            observation_materialization: None,
            flow_start: None,
        },
    )
    .await?;
    assert_eq!(
        replacement_schedule.schedule_id, "schedule-2",
        "schedule ids should continue past quarantined history"
    );

    let third_run = client
        .post(format!("{base}/v1/sessions/corruption-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "third run after corruption".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let third_run = wait_for_run_status(
        &client,
        &base,
        &third_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(
        third_run.run_id, "run-3",
        "run ids should continue past quarantined history"
    );
    assert!(
        third_run
            .outputs
            .iter()
            .any(|output| output.content.contains("RUN_THREE_OK"))
    );

    assert!(daemon_index_path.exists());
    assert!(!schedule_path.exists());
    assert!(!scheduled_run_path.exists());
    assert!(has_quarantined_sibling(&daemon_index_path)?);
    assert!(has_quarantined_sibling(&schedule_path)?);
    assert!(has_quarantined_sibling(&scheduled_run_path)?);

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;
    Ok(())
}

#[tokio::test]
async fn daemon_rebuilds_bindings_but_not_run_reply_targets_when_index_is_corrupted() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-corrupted-index-topology");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-corrupt-topology-run-1",
            "TOPOLOGY_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "corruption-topology-demo").await?;
    let reply_target = kheish_types::ReplyHandle {
        plugin: "http".to_string(),
        address: crate::connectors::encode_http_reply_route(&crate::connectors::HttpReplyRoute {
            url: "https://example.invalid/reply".to_string(),
            allow_private_network: false,
            headers: std::collections::BTreeMap::new(),
        }),
    };
    let first_run = client
        .post(format!("{base}/v1/sessions/corruption-topology-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "topology rebuild".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            binding_keys: vec!["team:alpha".to_string()],
            reply_targets: vec![reply_target.clone()],
            reply_plugin: None,
            reply_address: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let daemon_index_path = state_root.join("daemon-index.json");
    fs::write(&daemon_index_path, "{broken-index")?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");

    let session = client
        .get(format!("{base}/v1/sessions/corruption-topology-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(
        session.reply_targets.is_empty(),
        "one-off run reply targets must not become sticky session defaults after index repair"
    );

    let index = FileDaemonStore::new(&state_root).load_index()?;
    assert_eq!(
        index.bindings.get("team:alpha").map(String::as_str),
        Some("corruption-topology-demo")
    );
    assert!(
        index
            .reply_targets
            .get("corruption-topology-demo")
            .is_none(),
        "run-scoped reply targets should not repopulate the session cache"
    );
    assert!(has_quarantined_sibling(&daemon_index_path)?);

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;
    Ok(())
}

