#[tokio::test]
async fn daemon_repairs_stale_session_owner_from_supervisor_on_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-stale-index-session-owner");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let created = create_test_session(&client, &base, "stale-owner-demo").await?;
    let canonical_agent_id = created.agent_id.clone();

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let store = FileDaemonStore::new(&state_root);
    let mut index = store.load_index()?;
    index.sessions.insert(
        "stale-owner-demo".to_string(),
        "agent-stale-owner".to_string(),
    );
    index.sessions.insert(
        "orphan-stale-session".to_string(),
        "agent-orphan-owner".to_string(),
    );
    store.save_index(&index)?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");

    let restored = client
        .get(format!("{base}/v1/sessions/stale-owner-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(restored.agent_id, canonical_agent_id);

    let repaired = FileDaemonStore::new(&state_root).load_index()?;
    assert_eq!(
        repaired
            .sessions
            .get("stale-owner-demo")
            .map(String::as_str),
        Some(canonical_agent_id.as_str())
    );
    assert!(
        !repaired.sessions.contains_key("orphan-stale-session"),
        "startup repair should prune session mappings that are not backed by supervisor topology or runs"
    );

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;
    Ok(())
}

#[tokio::test]
async fn daemon_does_not_repair_session_mapping_from_run_with_unknown_agent() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-unknown-run-agent-index");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let known = create_test_session(&client, &base, "known-run-agent-demo").await?;

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let run_request = test_submit_input_request("orphan run should not create session owner");
    FileRunStore::new(&state_root).save_run(&RunRecord {
        view: RunView {
            run_id: "run-orphan-agent-session".to_string(),
            session_id: "orphan-run-session".to_string(),
            agent_id: "agent-missing-from-supervisor".to_string(),
            kind: DaemonRunKind::Input,
            status: DaemonRunStatus::Completed,
            submitted_at_ms: 10,
            updated_at_ms: 20,
            started_at_ms: Some(10),
            finished_at_ms: Some(20),
            queued_position: None,
            request: summarize_input_request(&run_request),
            input_attachments: Vec::new(),
            input_metadata: None,
            pending_approval_ids: Vec::new(),
            pending_approvals: Vec::new(),
            pending_question_ids: Vec::new(),
            pending_questions: Vec::new(),
            outputs: Vec::new(),
            deliveries: Vec::new(),
            error: None,
        },
        reply_targets: Vec::new(),
        payload: RunRequestPayload::Input {
            request: run_request,
            idempotency: None,
        },
    })?;
    let wrong_session_request =
        test_submit_input_request("wrong session should not create session owner");
    FileRunStore::new(&state_root).save_run(&RunRecord {
        view: RunView {
            run_id: "run-known-agent-wrong-session".to_string(),
            session_id: "stale-known-agent-session".to_string(),
            agent_id: known.agent_id.clone(),
            kind: DaemonRunKind::Input,
            status: DaemonRunStatus::Completed,
            submitted_at_ms: 30,
            updated_at_ms: 40,
            started_at_ms: Some(30),
            finished_at_ms: Some(40),
            queued_position: None,
            request: summarize_input_request(&wrong_session_request),
            input_attachments: Vec::new(),
            input_metadata: None,
            pending_approval_ids: Vec::new(),
            pending_approvals: Vec::new(),
            pending_question_ids: Vec::new(),
            pending_questions: Vec::new(),
            outputs: Vec::new(),
            deliveries: Vec::new(),
            error: None,
        },
        reply_targets: Vec::new(),
        payload: RunRequestPayload::Input {
            request: wrong_session_request,
            idempotency: None,
        },
    })?;

    let store = FileDaemonStore::new(&state_root);
    let mut index = store.load_index()?;
    index.sessions.insert(
        "orphan-run-session".to_string(),
        "agent-missing-from-supervisor".to_string(),
    );
    index.sessions.insert(
        "stale-known-agent-session".to_string(),
        known.agent_id.clone(),
    );
    store.save_index(&index)?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    wait_for_daemon_ready(&client, &base).await?;

    let repaired = FileDaemonStore::new(&state_root).load_index()?;
    assert!(
        !repaired.sessions.contains_key("orphan-run-session"),
        "startup repair must not trust run-derived session ownership for unknown agents"
    );
    assert!(
        !repaired.sessions.contains_key("stale-known-agent-session"),
        "startup repair must not trust run-derived session ownership that disagrees with supervisor topology"
    );
    let response = client
        .get(format!("{base}/v1/sessions/orphan-run-session"))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::NOT_FOUND);
    let response = client
        .get(format!("{base}/v1/sessions/stale-known-agent-session"))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::NOT_FOUND);

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;
    Ok(())
}

#[tokio::test]
async fn daemon_omits_recovered_memory_when_model_context_budget_is_exhausted() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-memory-budget");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let responses_owned = vec![
        openai_text_response("budget stored", 9, 3),
        openai_text_response("budget follow-up", 11, 2),
    ];
    let responses = responses_owned
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("memory-budget-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let first_run = client
        .post(format!("{base}/v1/sessions/memory-budget-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Remember the budget marker.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let second_run = client
        .post(format!("{base}/v1/sessions/memory-budget-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "x".repeat(400_000),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig {
                model: Some("gpt-4o".to_string()),
                max_output_tokens: Some(32_000),
                ..ModelGenerationConfig::default()
            }),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &second_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let captured_requests = captured_requests.lock().clone();
    assert_eq!(captured_requests.len(), 2);
    let second_payload = serde_json::from_str::<Value>(&captured_requests[1])?;
    let instructions = second_payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions in second request"))?;
    assert!(
        !instructions.contains("# Recovered Memory"),
        "recovered memory should be omitted when the hard model budget is exhausted: {}",
        serde_json::to_string_pretty(&second_payload)?
    );
    let status = client
        .get(format!("{base}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json::<DaemonStatusView>()
        .await?;
    assert!(
        status.run_memory.metrics.prompt_limit_omitted_total >= 1,
        "runtime prompt-budget omission should be visible in status: {:?}",
        status.run_memory.metrics
    );
    assert_eq!(
        status.run_memory.metrics.injected_total, 0,
        "omitted recovered memory must not count as injected after final prompt packing"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_prunes_tracked_run_memory_files_and_index_entries() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-memory-pruning");
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let total_seed_runs = crate::memory::MAX_TRACKED_RUN_MEMORIES_PER_SESSION + 2;
    let mut responses_owned = (0..total_seed_runs)
        .map(|index| openai_text_response(&format!("stored-{index}"), 9, 3))
        .collect::<Vec<_>>();
    responses_owned.push(openai_text_response("after restart", 11, 2));
    let responses = responses_owned
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let base_url = spawn_openai_mock_server_sequence(responses, captured_requests.clone()).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url.clone();
    let (service, listener) = build_openai_daemon(config.clone(), provider.clone()).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("memory-pruning-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let mut seed_runs = Vec::new();
    for index in 0..total_seed_runs {
        let run = client
            .post(format!("{base}/v1/sessions/memory-pruning-demo/runs"))
            .json(&SubmitInputRequest {
                source_plugin: None,
                source_kind: None,
                actor_id: None,
                provider: None,
                content: format!("Remember pruning marker {index}."),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: None,
                completion_requirements: None,
                metadata: None,
                reply_address: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
            })
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;
        seed_runs.push(run);
    }

    let memory_store = FileRunMemoryStore::new(&state_root);
    assert!(!memory_store.has_run_memory(&seed_runs[0].run_id));
    assert!(memory_store.has_run_memory(&seed_runs[total_seed_runs - 1].run_id));
    assert_eq!(
        count_json_files(&state_root.join("run-memories"))?,
        crate::memory::MAX_TRACKED_RUN_MEMORIES_PER_SESSION
    );
    let topology =
        serde_json::from_slice::<Value>(&fs::read(state_root.join("daemon-index.json"))?)?;
    assert_eq!(
        topology["run_memories"]["by_session"]["memory-pruning-demo"]
            .as_array()
            .map(Vec::len),
        Some(crate::memory::MAX_TRACKED_RUN_MEMORIES_PER_SESSION)
    );

    let _ = shutdown.send(());
    let orphan_memory_path =
        resolve_storage_path_for_read(&state_root.join("run-memories"), "run-orphan", "json");
    fs::create_dir_all(
        orphan_memory_path
            .parent()
            .ok_or_else(|| anyhow!("orphan memory path should have a parent"))?,
    )?;
    fs::write(
        &orphan_memory_path,
        r#"{"session_id":"memory-pruning-demo","memory":{"run_id":"run-orphan"}}"#,
    )?;
    assert!(orphan_memory_path.exists());

    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let base = format!("http://{address}");
    let follow_up_run = client
        .post(format!("{base}/v1/sessions/memory-pruning-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Use any recovered memory that still exists.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    wait_for_run_status(
        &client,
        &base,
        &follow_up_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;

    let captured_requests = captured_requests.lock().clone();
    assert_eq!(captured_requests.len(), total_seed_runs + 1);
    let follow_up_payload = serde_json::from_str::<Value>(
        captured_requests
            .last()
            .ok_or_else(|| anyhow!("missing follow-up provider request"))?,
    )?;
    let instructions = follow_up_payload["instructions"]
        .as_str()
        .ok_or_else(|| anyhow!("missing provider instructions in follow-up request"))?;
    assert!(
        instructions.contains(&format!(
            "Request: Remember pruning marker {}.",
            total_seed_runs - 1
        )),
        "latest recovered memory should survive pruning: {}",
        serde_json::to_string_pretty(&follow_up_payload)?
    );
    assert!(
        !instructions.contains("Request: Remember pruning marker 0."),
        "oldest pruned recovered memory should not survive restart: {}",
        serde_json::to_string_pretty(&follow_up_payload)?
    );
    assert!(
        !orphan_memory_path.exists(),
        "orphaned run-memory file should be pruned during daemon startup"
    );
    let status = client
        .get(format!("{base}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json::<DaemonStatusView>()
        .await?;
    assert!(
        status.run_memory.metrics.pruned_orphan_total >= 1,
        "orphan pruning metric should be visible in status: {:?}",
        status.run_memory.metrics
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_control_plane_auth_enforces_read_and_admin_tokens() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-auth");
    let config = {
        let mut config = DaemonConfig::new(
            "127.0.0.1:0".parse::<SocketAddr>()?,
            &state_root,
            temp.path(),
        );
        config.control_plane_auth = ControlPlaneAuthConfig {
            admin_token: Some("admin-secret".to_string()),
            read_only_token: Some("readonly-secret".to_string()),
        };
        config
    };
    let provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");

    let missing = client.get(format!("{base}/v1/runtime")).send().await?;
    assert_eq!(missing.status(), StatusCode::UNAUTHORIZED);

    let readonly_get = client
        .get(format!("{base}/v1/runtime"))
        .bearer_auth("readonly-secret")
        .send()
        .await?;
    assert_eq!(readonly_get.status(), StatusCode::OK);

    let readonly_post = client
        .post(format!("{base}/v1/sessions"))
        .bearer_auth("readonly-secret")
        .json(&CreateSessionRequest {
            session_id: Some("readonly-denied".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?;
    assert_eq!(readonly_post.status(), StatusCode::FORBIDDEN);

    let admin_post = client
        .post(format!("{base}/v1/sessions"))
        .bearer_auth("admin-secret")
        .json(&CreateSessionRequest {
            session_id: Some("admin-allowed".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?;
    assert_eq!(admin_post.status(), StatusCode::CREATED);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_connector_routes_keep_their_own_auth_when_control_plane_auth_is_enabled()
-> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-connector-auth");
    let captured = Arc::new(Mutex::new(String::new()));
    let response = concat!(
        "event: response.output_item.added\n",
        "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
        "event: response.output_text.delta\n",
        "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-1\",\"output_index\":0,\"content_index\":0,\"delta\":\"hello from connector\"}\n\n",
        "event: response.completed\n",
        "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":7,\"output_tokens\":4}}}\n\n"
    );
    let base_url = spawn_openai_mock_server(response, captured).await?;
    let connectors_path = temp.path().join("connectors.toml");
    std::fs::write(
        &connectors_path,
        r#"
[[http_connectors]]
name = "ingress"
fixed_session_id = "connector-auth-demo"
bearer_token = "connector-secret"
session_policy = { create_if_missing = true }
"#,
    )?;
    let config = {
        let mut config = DaemonConfig::new(
            "127.0.0.1:0".parse::<SocketAddr>()?,
            &state_root,
            temp.path(),
        );
        config.connectors_config_path = Some(connectors_path);
        config.control_plane_auth = ControlPlaneAuthConfig {
            admin_token: Some("admin-secret".to_string()),
            read_only_token: Some("readonly-secret".to_string()),
        };
        config
    };
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");

    let response = client
        .post(format!("{base}/v1/connectors/http/ingress"))
        .bearer_auth("connector-secret")
        .json(&json!({
            "idempotency_key": "connector-auth-1",
            "content": "Reply exactly CONNECTOR_AUTH_OK and nothing else."
        }))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::OK);
    let run = response.json::<RunView>().await?;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    let run = loop {
        let polled = client
            .get(format!("{base}/v1/runs/{}", run.run_id))
            .bearer_auth("admin-secret")
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        if polled.status == DaemonRunStatus::Completed {
            break polled;
        }
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for connector run to complete"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    };
    assert_eq!(
        run.outputs
            .last()
            .map(|output| output.content.trim().to_string())
            .as_deref(),
        Some("hello from connector")
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_connector_hostile_session_id_stays_within_storage_root() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-hostile-session");
    let captured = Arc::new(Mutex::new(String::new()));
    let response = concat!(
        "event: response.output_item.added\n",
        "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
        "event: response.output_text.delta\n",
        "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-1\",\"output_index\":0,\"content_index\":0,\"delta\":\"hello from hostile session\"}\n\n",
        "event: response.completed\n",
        "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":7,\"output_tokens\":4}}}\n\n"
    );
    let base_url = spawn_openai_mock_server(response, captured).await?;
    let hostile_session_id = "../../../etc/passwd";
    let connectors_path = temp.path().join("connectors.toml");
    std::fs::write(
        &connectors_path,
        format!(
            r#"
[[http_connectors]]
name = "ingress"
fixed_session_id = "{hostile_session_id}"
allow_unauthenticated_ingress = true
session_policy = {{ create_if_missing = true }}
"#
        ),
    )?;
    let config = {
        let mut config = DaemonConfig::new(
            "127.0.0.1:0".parse::<SocketAddr>()?,
            &state_root,
            temp.path(),
        );
        config.connectors_config_path = Some(connectors_path);
        config
    };
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    let response = client
        .post(format!("{base}/v1/connectors/http/ingress"))
        .json(&json!({
            "idempotency_key": "hostile-session-1",
            "content": "Reply exactly HOSTILE_SESSION_OK and nothing else."
        }))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::OK);
    let run = response.json::<RunView>().await?;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let polled = client
            .get(format!("{base}/v1/runs/{}", run.run_id))
            .send()
            .await?
            .error_for_status()?
            .json::<RunView>()
            .await?;
        if polled.status == DaemonRunStatus::Completed {
            break;
        }
        anyhow::ensure!(
            tokio::time::Instant::now() < deadline,
            "timed out waiting for hostile-session run to complete"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }

    let safe_name = format!("{}.jsonl", safe_storage_name(hostile_session_id));
    let session_path = state_root.join("sessions").join("__safe").join(&safe_name);
    let output_path = state_root.join("outputs").join("__safe").join(&safe_name);
    assert!(session_path.exists());
    assert!(output_path.exists());
    assert!(session_path.starts_with(state_root.join("sessions").join("__safe")));
    assert!(output_path.starts_with(state_root.join("outputs").join("__safe")));

    let _ = shutdown.send(());
    Ok(())
}

