#[tokio::test]
async fn daemon_slack_connector_scopes_enterprise_sessions_and_blocks_file_host_abuse() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-slack-enterprise");
    let captured = Arc::new(Mutex::new(String::new()));
    let base_url = spawn_openai_mock_server(
        "event: response.completed\n\
         data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":1,\"output_tokens\":1}}}\n\n",
        captured.clone(),
    )
    .await?;
    let connectors_path = temp.path().join("connectors.toml");
    std::fs::write(
        &connectors_path,
        r#"
[[slack_connectors]]
name = "secure"
bot_token = "xoxb-test-token"
signing_secret = "slack-signing-secret"
include_self_output = false
allowed_enterprise_ids = ["E_ALLOWED"]
allowed_team_ids = ["T_ALLOWED"]
allowed_channel_ids = ["C_ALLOWED"]
session_policy = { create_if_missing = true }
"#,
    )?;
    let config = {
        let mut config = DaemonConfig::new(
            "127.0.0.1:0".parse::<SocketAddr>()?,
            &state_root,
            temp.path(),
        );
        config.connectors_config_path = Some(connectors_path);
        config
    };
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    let accepted = json!({
        "type": "event_callback",
        "event_id": "evt-slack-enterprise",
        "enterprise_id": "E_ALLOWED",
        "team_id": "T_ALLOWED",
        "event": {
            "type": "message",
            "channel": "C_ALLOWED",
            "ts": "1712486400.000300",
            "user": "U123",
            "text": "hello"
        }
    });
    let response = post_signed_slack_payload(
        &client,
        &format!("{base}/v1/connectors/slack/secure"),
        &accepted,
        "slack-signing-secret",
    )
    .await?;
    assert_eq!(response.status(), StatusCode::OK);
    let run: Value = response.json().await?;
    assert_eq!(
        run.get("session_id").and_then(Value::as_str),
        Some("slack:secure:enterprise:E_ALLOWED:team:T_ALLOWED:C_ALLOWED:1712486400.000300")
    );

    let denied_authorization = json!({
        "type": "event_callback",
        "event_id": "evt-slack-denied-auth",
        "enterprise_id": "E_ALLOWED",
        "team_id": "T_ALLOWED",
        "authorizations": [{
            "enterprise_id": "E_ALLOWED",
            "team_id": "T_DENIED"
        }],
        "event": {
            "type": "message",
            "channel": "C_ALLOWED",
            "ts": "1712486400.000302",
            "user": "U123",
            "text": "masked denied team"
        }
    });
    let response = post_signed_slack_payload(
        &client,
        &format!("{base}/v1/connectors/slack/secure"),
        &denied_authorization,
        "slack-signing-secret",
    )
    .await?;
    assert_eq!(response.status(), StatusCode::FORBIDDEN);
    assert!(
        response
            .text()
            .await?
            .contains("authorization team_id is not allowed")
    );

    let stale_signature = post_signed_slack_payload_with_timestamp(
        &client,
        &format!("{base}/v1/connectors/slack/secure"),
        &accepted,
        "slack-signing-secret",
        1,
    )
    .await?;
    assert_eq!(stale_signature.status(), StatusCode::UNAUTHORIZED);
    assert!(
        stale_signature
            .text()
            .await?
            .contains("timestamp is too old")
    );

    let hostile_file = json!({
        "type": "event_callback",
        "event_id": "evt-slack-hostile-file",
        "enterprise_id": "E_ALLOWED",
        "team_id": "T_ALLOWED",
        "event": {
            "type": "message",
            "channel": "C_ALLOWED",
            "ts": "1712486400.000301",
            "user": "U123",
            "files": [{
                "id": "F123",
                "name": "demo.txt",
                "mimetype": "text/plain",
                "url_private_download": "https://attacker.invalid/demo.txt"
            }]
        }
    });
    let response = post_signed_slack_payload(
        &client,
        &format!("{base}/v1/connectors/slack/secure"),
        &hostile_file,
        "slack-signing-secret",
    )
    .await?;
    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    assert!(
        response
            .text()
            .await?
            .contains("file URL host is not allowed")
    );

    let _ = shutdown.send(());
    Ok(())
}

async fn post_signed_slack_payload(
    client: &Client,
    url: &str,
    payload: &Value,
    signing_secret: &str,
) -> Result<reqwest::Response> {
    let timestamp = crate::now_ms() / 1_000;
    post_signed_slack_payload_with_timestamp(client, url, payload, signing_secret, timestamp).await
}

async fn post_signed_slack_payload_with_timestamp(
    client: &Client,
    url: &str,
    payload: &Value,
    signing_secret: &str,
    timestamp: u64,
) -> Result<reqwest::Response> {
    let body = payload.to_string();
    let mut mac = TestHmacSha256::new_from_slice(signing_secret.as_bytes())
        .map_err(|_| anyhow!("invalid slack signing secret in test"))?;
    mac.update(format!("v0:{timestamp}:{body}").as_bytes());
    let signature = format!("v0={}", hex::encode(mac.finalize().into_bytes()));
    client
        .post(url)
        .header("content-type", "application/json")
        .header("x-slack-request-timestamp", timestamp.to_string())
        .header("x-slack-signature", signature)
        .body(body)
        .send()
        .await
        .context("failed to post signed Slack payload")
}

#[tokio::test]
async fn daemon_telegram_connector_deduplicates_before_fetching_file_metadata() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-telegram-idempotency");
    let captured = Arc::new(Mutex::new(String::new()));
    let response = concat!(
        "event: response.output_item.added\n",
        "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
        "event: response.output_text.delta\n",
        "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-1\",\"output_index\":0,\"content_index\":0,\"delta\":\"telegram doc ok\"}\n\n",
        "event: response.completed\n",
        "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":7,\"output_tokens\":4}}}\n\n"
    );
    let provider_base_url = spawn_openai_mock_server(response, captured).await?;
    let get_file_calls = Arc::new(AtomicUsize::new(0));
    let telegram_base_url = spawn_telegram_media_mock_server(
        "docs/sample.txt",
        "text/plain",
        b"hello from telegram".to_vec(),
        get_file_calls.clone(),
    )
    .await?;
    let connectors_path = temp.path().join("connectors.toml");
    std::fs::write(
        &connectors_path,
        format!(
            r#"
[[telegram_connectors]]
name = "ingress"
bot_token = "telegram-test-token"
api_base_url = "{telegram_base_url}"
fixed_session_id = "telegram-dedupe-demo"
allow_unauthenticated_ingress = true
allowed_chat_ids = [123456]
ingress_events_per_second = 1
session_policy = {{ create_if_missing = true }}

[[telegram_connectors]]
name = "polling"
bot_token = "telegram-test-token"
api_base_url = "{telegram_base_url}"
ingress_mode = "polling"
include_self_output = false
session_policy = {{ create_if_missing = true }}
"#
        ),
    )?;
    let config = {
        let mut config = DaemonConfig::new(
            "127.0.0.1:0".parse::<SocketAddr>()?,
            &state_root,
            temp.path(),
        );
        config.connectors_config_path = Some(connectors_path);
        config
    };
    let mut provider = OpenAiProviderConfig::new("gpt-test", "test-key");
    provider.base_url = provider_base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    let payload = json!({
        "update_id": 4242,
        "message": {
            "message_id": 99,
            "chat": { "id": 123456 },
            "document": {
                "file_id": "doc-1",
                "file_name": "sample.txt",
                "mime_type": "text/plain",
                "file_size": 20
            }
        }
    });

    let first_run = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&payload)
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;

    let duplicate_run = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&payload)
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(duplicate_run.run_id, first_run.run_id);
    assert_eq!(
        get_file_calls.load(Ordering::SeqCst),
        1,
        "duplicate update_id should return the existing run without refetching media"
    );

    let rate_limited_update = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&json!({
            "update_id": 4244,
            "message": {
                "message_id": 101,
                "chat": { "id": 123456 },
                "document": {
                    "file_id": "doc-2",
                    "file_name": "sample-2.txt",
                    "mime_type": "text/plain",
                    "file_size": 20
                }
            }
        }))
        .send()
        .await?;
    assert_eq!(rate_limited_update.status(), StatusCode::TOO_MANY_REQUESTS);
    assert_eq!(
        rate_limited_update
            .headers()
            .get(reqwest::header::RETRY_AFTER)
            .and_then(|value| value.to_str().ok()),
        Some("1")
    );
    let rate_body: ProblemDetails = rate_limited_update.json().await?;
    assert_eq!(rate_body.code.as_str(), "telegram_ingress_rate_limited");
    assert_eq!(rate_body.domain.as_deref(), Some("connector_ingress"));
    assert!(
        rate_body.detail.contains("retry_after_ms="),
        "unexpected Telegram rate-limit problem: {rate_body:?}"
    );
    assert_eq!(
        get_file_calls.load(Ordering::SeqCst),
        1,
        "rate-limited new updates should be rejected before Telegram getFile"
    );

    let completed = wait_for_run_status(
        &client,
        &base,
        &first_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(
        completed
            .input_metadata
            .as_ref()
            .and_then(|metadata| metadata.get("connector_ingress_key"))
            .and_then(Value::as_str),
        Some("telegram:ingress:4242")
    );
    assert!(
        completed
            .input_metadata
            .as_ref()
            .and_then(|metadata| metadata.get("telegram_ingress_fingerprint"))
            .and_then(Value::as_str)
            .is_some(),
        "telegram ingress should persist a payload fingerprint"
    );
    assert_eq!(
        completed
            .outputs
            .last()
            .map(|output| output.content.as_str()),
        Some("telegram doc ok")
    );

    let conflicting_duplicate = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&json!({
            "update_id": 4242,
            "message": {
                "message_id": 100,
                "chat": { "id": 123456 },
                "text": "same update id with a different payload"
            }
        }))
        .send()
        .await?;
    assert_eq!(conflicting_duplicate.status(), StatusCode::CONFLICT);
    let conflict_body = conflicting_duplicate.text().await?;
    assert!(
        conflict_body.contains("different payload"),
        "unexpected conflict body: {conflict_body}"
    );
    assert_eq!(get_file_calls.load(Ordering::SeqCst), 1);

    let unsupported_update = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&json!({
            "update_id": 4243
        }))
        .send()
        .await?;
    assert_eq!(unsupported_update.status(), StatusCode::OK);
    let unsupported_body: Value = unsupported_update.json().await?;
    assert_eq!(unsupported_body.get("skipped"), Some(&Value::Bool(true)));

    let missing_update_id = client
        .post(format!("{base}/v1/connectors/telegram/ingress"))
        .json(&json!({
            "message": {
                "message_id": 100,
                "chat": { "id": 123456 },
                "text": "missing update id"
            }
        }))
        .send()
        .await?;
    assert_eq!(missing_update_id.status(), StatusCode::BAD_REQUEST);

    let polling_webhook = client
        .post(format!("{base}/v1/connectors/telegram/polling"))
        .json(&json!({
            "update_id": 5000,
            "message": {
                "message_id": 100,
                "chat": { "id": 123456 },
                "text": "polling connector should reject webhook"
            }
        }))
        .send()
        .await?;
    assert_eq!(polling_webhook.status(), StatusCode::CONFLICT);

    let _ = shutdown.send(());
    Ok(())
}

