#[tokio::test]
async fn daemon_missing_run_endpoint_returns_typed_problem_details() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-missing-run-problem");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let response = client
        .get(format!("{base}/v1/runs/missing-run"))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::NOT_FOUND);
    assert_eq!(
        response
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok()),
        Some("application/problem+json")
    );
    let problem = response.json::<ProblemDetails>().await?;
    assert_eq!(problem.status, 404);
    assert_eq!(problem.domain.as_deref(), Some("runs"));
    assert_eq!(problem.code, "run_not_found");
    assert!(
        problem.detail.contains("unknown run missing-run"),
        "unexpected problem detail: {}",
        problem.detail
    );

    let _ = shutdown.send(());
    Ok(())
}

