#[tokio::test]
async fn daemon_openai_account_auth_runs_end_to_end_with_mock_provider() -> Result<()> {
    ensure_auth_store_master_key();
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-openai-account");
    let captured_request = Arc::new(Mutex::new(String::new()));
    let response = concat!(
        "event: response.output_item.added\n",
        "data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"id\":\"msg-openai-account-1\",\"type\":\"message\",\"status\":\"in_progress\",\"role\":\"assistant\",\"content\":[]}}\n\n",
        "event: response.output_text.delta\n",
        "data: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg-openai-account-1\",\"output_index\":0,\"content_index\":0,\"delta\":\"hello from openai account\"}\n\n",
        "event: response.completed\n",
        "data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":7,\"output_tokens\":4}}}\n\n"
    );
    let openai_base_url =
        spawn_openai_mock_server_with_request_capture(response, captured_request.clone()).await?;
    let auth_issuer = spawn_openai_auth_mock_server().await?;
    let codex_auth_path = temp.path().join("codex-auth.json");
    std::fs::write(
        &codex_auth_path,
        serde_json::to_string_pretty(&json!({
            "auth_mode": "chatgpt",
            "OPENAI_API_KEY": null,
            "tokens": {
                "refresh_token": "stale-refresh-token",
                "account_id": "acc-test"
            }
        }))?,
    )?;
    let auth_manager = AuthManager::new(state_root.join("auth/openai-slots.json"))?;
    let record = OpenAiAuthBackend::import_codex_record_with_overrides(
        AuthSlotId::new("openai-default"),
        &codex_auth_path,
        auth_issuer,
        "client-test",
        openai_base_url.clone(),
        None,
        None,
    )?;
    auth_manager.put_record(record).await?;
    let config = DaemonConfig::new(
        "127.0.0.1:0".parse::<SocketAddr>()?,
        &state_root,
        temp.path(),
    );
    let mut provider = OpenAiProviderConfig::with_request_auth_provider(
        "gpt-test",
        auth_manager.request_provider(AuthSlotId::new("openai-default")),
    );
    provider.base_url = openai_base_url;
    let (service, listener) = build_openai_daemon(config, provider).await?;
    let address = listener.local_addr()?;
    let (shutdown, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = service
            .serve_with_shutdown(listener, async move {
                let _ = shutdown_rx.await;
            })
            .await;
    });

    let client = Client::new();
    let base = format!("http://{address}");
    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("openai-account-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let submitted = client
        .post(format!("{base}/v1/sessions/openai-account-demo/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Say hello".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: None,
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(submitted.session_id, "openai-account-demo");
    let runs = client
        .get(format!("{base}/v1/runs?session_id=openai-account-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    let run_id = runs
        .last()
        .map(|run| run.run_id.clone())
        .ok_or_else(|| anyhow!("missing run for openai-account-demo"))?;
    let run = wait_for_run_status(&client, &base, &run_id, &[DaemonRunStatus::Completed]).await?;
    assert_eq!(run.status, DaemonRunStatus::Completed);
    let captured_request = captured_request.lock().clone();
    assert!(
        captured_request.contains("Authorization: Bearer fresh-access-token")
            || captured_request.contains("authorization: Bearer fresh-access-token"),
        "missing Codex bearer authorization header: {captured_request}"
    );
    assert!(
        captured_request.contains("ChatGPT-Account-ID: acc-test")
            || captured_request.contains("chatgpt-account-id: acc-test"),
        "missing ChatGPT account header: {captured_request}"
    );
    let _ = shutdown.send(());
    Ok(())
}

