#[tokio::test]
async fn daemon_repairs_stale_plan_mode_snapshots_after_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-plan-repair");
    let client = Client::new();

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    wait_for_daemon_ready(&client, &base).await?;
    create_test_session(&client, &base, "plan-repair-session").await?;

    let _ = shutdown.send(());
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;

    FileSessionStore::new(state_root.join("sessions"))
        .append(
            "plan-repair-session",
            kheish_session::PersistedSessionRecord::Metadata {
                key: SESSION_CONTROL_STATE_METADATA_KEY.to_string(),
                value: serde_json::to_value(SessionControlState {
                    plan_mode: true,
                    session_permission_mode: Some("default".to_string()),
                    session_permission_updates: Vec::new(),
                    pre_plan_mode: Some("bypassPermissions".to_string()),
                    plan_artifact: None,
                    todos: Vec::new(),
                    tasks: Vec::new(),
                    archived_tasks: Default::default(),
                })?,
            },
        )
        .await?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    wait_for_daemon_ready(&client, &base).await?;
    client
        .get(format!("{base}/v1/sessions/plan-repair-session"))
        .send()
        .await?
        .error_for_status()?;

    let stored = FileSessionStore::new(state_root.join("sessions"))
        .load("plan-repair-session")
        .await?;
    let state = stored
        .metadata
        .get(SESSION_CONTROL_STATE_METADATA_KEY)
        .cloned()
        .map(serde_json::from_value::<SessionControlState>)
        .transpose()?
        .ok_or_else(|| anyhow!("missing repaired session control state"))?;
    assert!(state.plan_mode);
    assert_eq!(state.pre_plan_mode.as_deref(), Some("bypassPermissions"));
    assert_eq!(state.session_permission_mode.as_deref(), Some("plan"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_deduplicates_retried_sidechain_spawns_by_request_id() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-sidechain-dedupe-1",
            "SIDECHAIN_DEDUPE_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "sidechain-dedupe-root").await?;
    let request = SpawnSidechainRequest {
        session_id: None,
        thread_id: Some("sidechain-dedupe-thread".to_string()),
        route_policy: None,
        provider: None,
        permission_mode: None,
        retention: None,
        nickname: None,
        spawn_request_id: Some("spawn-request-1".to_string()),
        spawned_by_run_id: None,
        fork_context: ForkContext {
            parent_assistant_message: String::new(),
            inherited_tool_call_ids: Vec::new(),
            team_name: None,
            isolation: None,
            system_prompt: String::new(),
            prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
            provider: None,
            generation: None,
            tool_surface: kheish_types::ToolSurfaceFilter::default(),
            worktree_path: None,
        },
        generation: None,
        tool_surface: None,
        capability_scope: None,
        credential_scope: None,
        subtask: Some(SidechainSubtaskRequest {
            name: "child".to_string(),
            description: "dedupe".to_string(),
            content: "Reply with SIDECHAIN_DEDUPE_OK.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
        }),
    };

    let first = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let second = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    assert_eq!(second.session_id, first.session_id);
    assert_eq!(second.agent_id, first.agent_id);

    let child_runs = wait_for_session_run_count(&client, &base, &first.session_id, 1).await?;
    let completed = wait_for_run_status(
        &client,
        &base,
        &child_runs[0].run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(completed.outputs[0].content, "SIDECHAIN_DEDUPE_OK");

    let agents = client
        .get(format!("{base}/v1/agents"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ManagedAgentSnapshot>>()
        .await?;
    let child_count = agents
        .into_iter()
        .filter(|agent| {
            agent.agent.parent.as_ref().map(|parent| parent.0.as_str())
                == Some(root.agent_id.as_str())
        })
        .count();
    assert_eq!(child_count, 1);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn daemon_deduplicates_concurrent_auto_session_sidechain_spawns_by_request_id() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-sidechain-auto-dedupe");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "sidechain-auto-dedupe-root").await?;
    let request = SpawnSidechainRequest {
        session_id: None,
        thread_id: Some("sidechain-auto-dedupe-thread".to_string()),
        route_policy: None,
        provider: None,
        permission_mode: None,
        retention: None,
        nickname: None,
        spawn_request_id: Some("spawn-request-auto-concurrent".to_string()),
        spawned_by_run_id: None,
        fork_context: ForkContext {
            parent_assistant_message: String::new(),
            inherited_tool_call_ids: Vec::new(),
            team_name: None,
            isolation: None,
            system_prompt: String::new(),
            prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
            provider: None,
            generation: None,
            tool_surface: kheish_types::ToolSurfaceFilter::default(),
            worktree_path: None,
        },
        generation: None,
        tool_surface: None,
        capability_scope: None,
        credential_scope: None,
        subtask: None,
    };

    let mut tasks = Vec::new();
    for _ in 0..16 {
        let client = client.clone();
        let base = base.clone();
        let agent_id = root.agent_id.clone();
        let request = request.clone();
        tasks.push(tokio::spawn(async move {
            client
                .post(format!("{base}/v1/agents/{agent_id}/sidechains"))
                .json(&request)
                .send()
                .await
        }));
    }

    let mut successes = Vec::new();
    for task in tasks {
        let response = task.await??;
        match response.status() {
            StatusCode::OK => successes.push(response.json::<SessionView>().await?),
            StatusCode::CONFLICT => {
                let body = response.text().await?;
                assert!(
                    body.contains("already in progress"),
                    "unexpected sidechain conflict body: {body}"
                );
            }
            status => {
                let body = response.text().await.unwrap_or_default();
                bail!("unexpected sidechain spawn status {status}: {body}");
            }
        }
    }

    let retry = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let canonical = successes.first().unwrap_or(&retry);
    assert_eq!(retry.session_id, canonical.session_id);
    assert_eq!(retry.agent_id, canonical.agent_id);
    for success in &successes {
        assert_eq!(success.session_id, canonical.session_id);
        assert_eq!(success.agent_id, canonical.agent_id);
    }

    let agents = client
        .get(format!("{base}/v1/agents"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ManagedAgentSnapshot>>()
        .await?;
    let open_child_count = agents
        .iter()
        .filter(|agent| {
            agent.agent.parent.as_ref().map(|parent| parent.0.as_str())
                == Some(root.agent_id.as_str())
                && agent.agent.closed_at_ms.is_none()
        })
        .count();
    assert_eq!(open_child_count, 1);

    let _ = shutdown.send(());
    Ok(())
}

