#[tokio::test]
async fn daemon_retries_pending_sidechain_receipts_after_rolling_back_incomplete_child()
-> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-sidechain-pending-retry");
    let client = Client::new();

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let root = create_test_session(&client, &base, "sidechain-pending-retry-root").await?;
    let initial_request = SpawnSidechainRequest {
        session_id: Some("sidechain-pending-retry-child".to_string()),
        thread_id: Some("sidechain-pending-retry-thread".to_string()),
        route_policy: None,
        provider: None,
        permission_mode: None,
        retention: None,
        nickname: None,
        spawn_request_id: Some("spawn-request-pending".to_string()),
        spawned_by_run_id: None,
        fork_context: ForkContext {
            parent_assistant_message: String::new(),
            inherited_tool_call_ids: Vec::new(),
            team_name: None,
            isolation: None,
            system_prompt: String::new(),
            prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
            provider: None,
            generation: None,
            tool_surface: kheish_types::ToolSurfaceFilter::default(),
            worktree_path: None,
        },
        generation: None,
        tool_surface: None,
        capability_scope: None,
        credential_scope: None,
        subtask: None,
    };
    let first = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&initial_request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let store = FileDaemonStore::new(&state_root);
    let mut index = store.load_index()?;
    let key = format!("{}:spawn-request-pending", root.agent_id);
    let existing_receipt = index
        .sidechain_spawn_receipts
        .get(&key)
        .cloned()
        .ok_or_else(|| anyhow!("missing committed sidechain receipt"))?;
    index.sidechain_spawn_receipts.insert(
        key,
        match existing_receipt {
            crate::state::SidechainSpawnReceiptState::Committed {
                session_id,
                thread_id,
                request_fingerprint,
                subtask_request_json,
                ..
            } => crate::state::SidechainSpawnReceiptState::Pending {
                session_id,
                thread_id,
                request_fingerprint,
                subtask_request_json,
                recorded_at_ms: crate::now_ms(),
            },
            other => other,
        },
    );
    store.save_index(&index)?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let second = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&initial_request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(second.session_id, first.session_id);
    assert_ne!(second.agent_id, first.agent_id);

    let agents = client
        .get(format!("{base}/v1/agents"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ManagedAgentSnapshot>>()
        .await?;
    let open_children = agents
        .iter()
        .filter(|agent| {
            agent.agent.parent.as_ref().map(|parent| parent.0.as_str())
                == Some(root.agent_id.as_str())
                && agent.agent.closed_at_ms.is_none()
        })
        .count();
    assert_eq!(open_children, 1);
    assert!(
        agents
            .iter()
            .all(|agent| agent.agent.id.0 != first.agent_id),
        "pending receipt retry should remove the incomplete child instead of keeping a closed residue"
    );

    let _ = shutdown.send(());
    Ok(())
}

