#[tokio::test]
async fn daemon_pending_sidechain_receipt_cleanup_preserves_owned_session() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp
        .path()
        .join("daemon-sidechain-pending-protect-owned-session");
    let client = Client::new();

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let root = create_test_session(&client, &base, "sidechain-pending-protect-root").await?;
    let protected =
        create_test_session(&client, &base, "sidechain-pending-protect-existing").await?;

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let receipt_key = format!("{}:spawn-request-pending-protect-existing", root.agent_id);
    let store = FileDaemonStore::new(&state_root);
    let mut index = store.load_index()?;
    index.sidechain_spawn_receipts.insert(
        receipt_key.clone(),
        crate::state::SidechainSpawnReceiptState::Pending {
            session_id: protected.session_id.clone(),
            thread_id: None,
            request_fingerprint: "stale-pending-receipt".to_string(),
            subtask_request_json: None,
            recorded_at_ms: crate::now_ms(),
        },
    );
    store.save_index(&index)?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let restored = client
        .get(format!("{base}/v1/sessions/{}", protected.session_id))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(restored.agent_id, protected.agent_id);

    let repaired = FileDaemonStore::new(&state_root).load_index()?;
    assert_eq!(
        repaired.sessions.get(&protected.session_id),
        Some(&protected.agent_id)
    );
    assert!(
        !repaired.sidechain_spawn_receipts.contains_key(&receipt_key),
        "stale pending receipt should be discarded without deleting its owned session"
    );

    let _ = shutdown.send(());
    Ok(())
}

