#[tokio::test]
async fn daemon_user_questions_suspend_resume_and_block_parallel_inputs() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-question-1".to_string(),
                },
                ModelStreamEvent::TextDelta {
                    text: "Need clarification.".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "question-call-1".to_string(),
                        name: "ask_user_question".to_string(),
                        input: json!({
                            "questions": [{
                                "id": "focus",
                                "header": "Focus",
                                "question": "Which focus should I use?",
                                "options": [
                                    {"id": "memory", "label": "memory"},
                                    {"id": "kernel", "label": "kernel"}
                                ]
                            }]
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-question-2",
                "FOCUS:memory\nUse repeated RSS and allocation measurements.",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("question-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let run = client
        .post(format!("{base}/v1/sessions/question-session/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Ask me one structured question, then continue.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;

    let waiting = wait_for_pending_question_run(&client, &base, &run.run_id).await?;
    assert_eq!(
        waiting.pending_question_ids,
        vec!["question-request-question-call-1".to_string()]
    );

    let session = client
        .get(format!("{base}/v1/sessions/question-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(session.snapshot.pending_questions.len(), 1);
    assert_eq!(
        session.snapshot.agent.status,
        kheish_agent::AgentStatus::WaitingForUserInput
    );

    let questions = client
        .get(format!("{base}/v1/sessions/question-session/questions"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<PendingQuestionView>>()
        .await?;
    assert_eq!(questions.len(), 1);
    assert_eq!(questions[0].request.id, "question-request-question-call-1");

    let waiting_events = client
        .get(format!("{base}/v1/runs/{}/events", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    let waiting_question_event = waiting_events
        .iter()
        .find_map(|entry| match &entry.event {
            RunEvent::WaitingForUserQuestion {
                request_ids,
                requests,
            } => Some((request_ids, requests)),
            _ => None,
        })
        .ok_or_else(|| anyhow!("missing waiting_for_user_question event"))?;
    assert_eq!(waiting_question_event.0, &waiting.pending_question_ids);
    assert_eq!(waiting_question_event.1, &waiting.pending_questions);

    let conflict = client
        .post(format!("{base}/v1/sessions/question-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "second run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);

    let answer_request = ResolveUserQuestionRequest {
        idempotency_key: None,
        resolution: kheish_types::UserQuestionResolution {
            request_id: questions[0].request.id.clone(),
            answers: vec![kheish_types::UserQuestionAnswer {
                question_id: "focus".to_string(),
                selected_option_ids: vec!["memory".to_string()],
                freeform_answer: None,
            }],
            declined: false,
            justification: Some("selected in test".to_string()),
        },
    };
    let first_answer = client
        .post(format!("{base}/v1/runs/{}/questions", run.run_id))
        .header("Idempotency-Key", "question-answer-1")
        .json(&answer_request)
        .send()
        .await?;
    assert_eq!(first_answer.status(), StatusCode::ACCEPTED);
    let first_answer_run = first_answer.json::<RunView>().await?;
    assert_eq!(first_answer_run.run_id, run.run_id);

    let retry_answer = client
        .post(format!("{base}/v1/runs/{}/questions", run.run_id))
        .header("Idempotency-Key", "question-answer-1")
        .json(&answer_request)
        .send()
        .await?;
    assert_eq!(retry_answer.status(), StatusCode::ACCEPTED);
    let retry_answer_run = retry_answer.json::<RunView>().await?;
    assert_eq!(retry_answer_run.run_id, run.run_id);

    let conflicting_answer = client
        .post(format!("{base}/v1/runs/{}/questions", run.run_id))
        .header("Idempotency-Key", "question-answer-1")
        .json(&ResolveUserQuestionRequest {
            idempotency_key: None,
            resolution: kheish_types::UserQuestionResolution {
                request_id: questions[0].request.id.clone(),
                answers: vec![kheish_types::UserQuestionAnswer {
                    question_id: "focus".to_string(),
                    selected_option_ids: vec!["kernel".to_string()],
                    freeform_answer: None,
                }],
                declined: false,
                justification: Some("changed in test".to_string()),
            },
        })
        .send()
        .await?;
    assert_eq!(conflicting_answer.status(), StatusCode::CONFLICT);
    let conflicting_problem = conflicting_answer.json::<ProblemDetails>().await?;
    assert_eq!(conflicting_problem.domain.as_deref(), Some("idempotency"));
    assert_eq!(conflicting_problem.code, "idempotency_conflict");

    let completed =
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;
    assert_eq!(completed.outputs.len(), 1);
    assert!(
        completed.outputs[0].content.contains("FOCUS:memory"),
        "unexpected output: {}",
        serde_json::to_string_pretty(&completed)?
    );
    let run_events = client
        .get(format!("{base}/v1/runs/{}/events", run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    let started_count = run_events
        .iter()
        .filter(|entry| matches!(entry.event, RunEvent::Started))
        .count();
    assert_eq!(started_count, 2);
    let resolved_events = run_events
        .iter()
        .filter(|entry| {
            matches!(
                &entry.event,
                RunEvent::UserQuestionResolved { resolution }
                    if resolution == &answer_request.resolution
            )
        })
        .count();
    assert_eq!(resolved_events, 1);

    let _ = shutdown.send(());
    Ok(())
}

