#[tokio::test]
async fn daemon_parent_clarification_run_cancel_declines_child() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-parent-clarify-cancel-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "parent-clarify-cancel-call-1".to_string(),
                        name: "request_parent_clarification".to_string(),
                        input: json!({
                            "questions": [{
                                "id": "focus",
                                "header": "Focus",
                                "question": "Which focus should I use?",
                                "options": [
                                    {"id": "memory", "label": "memory"},
                                    {"id": "kernel", "label": "kernel"}
                                ]
                            }]
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-parent-clarify-cancel-2",
                "CHILD_REQUEST_SENT",
                kheish_types::ModelFinishReason::Completed,
            )),
            Ok(scripted_events(
                "assistant-parent-clarify-cancel-3",
                "CHILD_DECLINED_BY_CANCEL",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "clarify-cancel-root").await?;
    let child = spawn_parent_clarification_child(
        &client,
        &base,
        &root.agent_id,
        "clarify-cancel-child",
        "clarify-cancel-thread",
    )
    .await?;
    let child_runs = wait_for_session_run_count(&client, &base, &child.session_id, 1).await?;
    wait_for_run_status(
        &client,
        &base,
        &child_runs[0].run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    let root_runs = wait_for_session_run_count(&client, &base, "clarify-cancel-root", 1).await?;
    let parent_run = wait_for_pending_question_run(&client, &base, &root_runs[0].run_id).await?;
    let question_id = parent_run
        .pending_questions
        .first()
        .map(|request| request.id.clone())
        .ok_or_else(|| anyhow!("missing parent clarification question"))?;

    let completed_parent = client
        .post(format!("{base}/v1/runs/{}/cancel", parent_run.run_id))
        .json(&json!({}))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(completed_parent.status, DaemonRunStatus::Completed);
    assert!(
        completed_parent.outputs[0]
            .content
            .contains("Declined parent clarification request"),
        "parent run cancel should decline the child clarification: {}",
        serde_json::to_string_pretty(&completed_parent)?
    );

    let events = client
        .get(format!("{base}/v1/runs/{}/events", parent_run.run_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunEventEntry>>()
        .await?;
    assert!(events.iter().any(|entry| matches!(
        &entry.event,
        RunEvent::ParentClarificationResolved {
            requester_agent_id,
            requester_session_id,
            request_id,
            declined,
            ..
        } if requester_agent_id == &child.agent_id
            && requester_session_id == &child.session_id
            && request_id == &question_id
            && *declined
    )));

    let child_runs = wait_for_session_run_count(&client, &base, &child.session_id, 2).await?;
    let mailbox_run = child_runs
        .iter()
        .find(|run| run.run_id != child_runs[0].run_id)
        .ok_or_else(|| anyhow!("missing cancel-decline mailbox run"))?;
    let mailbox_completed = wait_for_run_status(
        &client,
        &base,
        &mailbox_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        mailbox_completed.outputs[0]
            .content
            .contains("CHILD_DECLINED_BY_CANCEL"),
        "cancel decline should be delivered to the child: {}",
        serde_json::to_string_pretty(&mailbox_completed)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_parent_clarification_child_closed_dead_letters_answer() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-parent-clarify-child-closed-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "parent-clarify-child-closed-call-1".to_string(),
                        name: "request_parent_clarification".to_string(),
                        input: json!({
                            "questions": [{
                                "id": "focus",
                                "header": "Focus",
                                "question": "Which focus should I use?",
                                "options": [
                                    {"id": "memory", "label": "memory"},
                                    {"id": "kernel", "label": "kernel"}
                                ]
                            }]
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-parent-clarify-child-closed-2",
                "CHILD_REQUEST_SENT",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "clarify-child-closed-root").await?;
    let mut child_request = parent_clarification_sidechain_request(
        "clarify-child-closed-child",
        "clarify-child-closed-thread",
        "Ask the parent one clarification.",
    );
    child_request.retention = Some(ChildRetentionPolicy::CloseOnSettle);
    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&child_request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let child_runs = wait_for_session_run_count(&client, &base, &child.session_id, 1).await?;
    wait_for_run_status(
        &client,
        &base,
        &child_runs[0].run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    let child_snapshot = client
        .get(format!("{base}/v1/agents/{}", child.agent_id))
        .send()
        .await?
        .error_for_status()?
        .json::<ManagedAgentSnapshot>()
        .await?;
    assert!(
        child_snapshot.agent.closed_at_ms.is_some(),
        "close_on_settle child should be closed before the parent answer: {}",
        serde_json::to_string_pretty(&child_snapshot)?
    );

    let root_runs =
        wait_for_session_run_count(&client, &base, "clarify-child-closed-root", 1).await?;
    let parent_run = wait_for_pending_question_run(&client, &base, &root_runs[0].run_id).await?;
    let questions = client
        .get(format!(
            "{base}/v1/sessions/clarify-child-closed-root/questions"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<PendingQuestionView>>()
        .await?;
    assert_eq!(questions.len(), 1);

    client
        .post(format!("{base}/v1/runs/{}/questions", parent_run.run_id))
        .json(&ResolveUserQuestionRequest {
            idempotency_key: None,
            resolution: kheish_types::UserQuestionResolution {
                request_id: questions[0].request.id.clone(),
                answers: vec![kheish_types::UserQuestionAnswer {
                    question_id: "focus".to_string(),
                    selected_option_ids: vec!["memory".to_string()],
                    freeform_answer: None,
                }],
                declined: false,
                justification: Some("child is already closed".to_string()),
            },
        })
        .send()
        .await?
        .error_for_status()?;
    let completed_parent = wait_for_run_status(
        &client,
        &base,
        &parent_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(completed_parent.outputs.len(), 1);

    let child_runs_after = client
        .get(format!("{base}/v1/runs?session_id={}", child.session_id))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<RunView>>()
        .await?;
    assert_eq!(
        child_runs_after.len(),
        1,
        "closed child should not receive a mailbox delivery run"
    );
    let dead_letters = client
        .get(format!(
            "{base}/v1/agents/{}/mailbox/dead-letter",
            child.agent_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<MailboxMessage>>()
        .await?;
    assert!(dead_letters.iter().any(|message| {
        message.payload["type"] == crate::control_tools::PARENT_CLARIFICATION_ANSWER_MESSAGE_TYPE
    }));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
