#[tokio::test]
async fn daemon_personas_snapshot_into_sessions_without_retconning_existing_bindings() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-persona-snapshots");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let created = create_test_persona(
        &client,
        &base,
        "persona-analyst",
        "Analyst",
        "Reply as Analyst v1.",
    )
    .await?;
    assert_eq!(created.persona_id, "persona-analyst");
    assert_eq!(created.version, 1);

    let listed = client
        .get(format!("{base}/v1/personas?query=Analyst"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<crate::PersonaSummaryView>>()
        .await?;
    assert_eq!(listed.len(), 1);
    assert_eq!(listed[0].persona_id, "persona-analyst");

    let first_session = create_test_session_with_persona(
        &client,
        &base,
        "persona-session-v1",
        Some("persona-analyst"),
    )
    .await?;
    let first_binding = first_session
        .persona
        .as_ref()
        .context("session should expose persona summary")?;
    assert_eq!(first_binding.persona_id, "persona-analyst");
    assert_eq!(first_binding.persona_version, 1);
    assert_eq!(first_binding.display_name, "Analyst");

    let updated = update_test_persona(
        &client,
        &base,
        "persona-analyst",
        Some("Analyst v2"),
        Some("Reply as Analyst v2."),
    )
    .await?;
    assert_eq!(updated.version, 2);
    assert_eq!(updated.display_name, "Analyst v2");

    let persisted_first = client
        .get(format!("{base}/v1/sessions/persona-session-v1"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let persisted_first_binding = persisted_first
        .persona
        .as_ref()
        .context("bound persona should persist on the original session")?;
    assert_eq!(persisted_first_binding.persona_version, 1);
    assert_eq!(persisted_first_binding.display_name, "Analyst");

    let second_session = create_test_session_with_persona(
        &client,
        &base,
        "persona-session-v2",
        Some("persona-analyst"),
    )
    .await?;
    let second_binding = second_session
        .persona
        .as_ref()
        .context("new session should bind the latest persona version")?;
    assert_eq!(second_binding.persona_version, 2);
    assert_eq!(second_binding.display_name, "Analyst v2");

    let reused = create_test_session_with_persona(
        &client,
        &base,
        "persona-session-v1",
        Some("persona-analyst"),
    )
    .await?;
    assert_eq!(reused.session_id, "persona-session-v1");
    assert_eq!(
        reused
            .persona
            .as_ref()
            .context("reused session should keep its original binding")?
            .persona_version,
        1
    );

    create_test_persona(
        &client,
        &base,
        "persona-reviewer",
        "Reviewer",
        "Reply as Reviewer.",
    )
    .await?;
    let conflict = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("persona-session-v1".to_string()),
            thread_id: None,
            persona_id: Some("persona-reviewer".to_string()),
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);

    let filtered = client
        .get(format!("{base}/v1/sessions?persona_id=persona-analyst"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<SessionViewSummary>>()
        .await?;
    let filtered_ids = filtered
        .into_iter()
        .map(|session| session.session_id)
        .collect::<Vec<_>>();
    assert_eq!(
        filtered_ids,
        vec![
            "persona-session-v1".to_string(),
            "persona-session-v2".to_string()
        ]
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
