#[tokio::test]
async fn daemon_mailbox_runs_use_session_route_policy_without_fork_overrides() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-mailbox-session-route");
    let (address, shutdown) = routed_scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-mailbox-route-1",
            "mailbox route ok",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = create_test_session(&client, &base, "mailbox-route-root").await?;
    set_test_session_route_policy(
        &client,
        &base,
        "mailbox-route-root",
        "xai",
        "grok-4.20-0309-reasoning",
    )
    .await?;

    client
        .post(format!("{base}/v1/mailboxes"))
        .json(&PostMailboxRequest {
            message_id: None,
            from_agent_id: root.agent_id.clone(),
            to_agent_id: root.agent_id.clone(),
            subject: "handoff".to_string(),
            ttl_ms: None,
            payload: json!({"message": "route it"}),
        })
        .send()
        .await?
        .error_for_status()?;

    let run = {
        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        loop {
            let runs = client
                .get(format!("{base}/v1/runs?session_id=mailbox-route-root"))
                .send()
                .await?
                .error_for_status()?
                .json::<Vec<RunView>>()
                .await?;
            if let Some(run) = runs
                .into_iter()
                .find(|run| run.kind == DaemonRunKind::MailboxDelivery)
            {
                break run;
            }
            anyhow::ensure!(
                tokio::time::Instant::now() < deadline,
                "timed out waiting for mailbox route run"
            );
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    };
    let completed =
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;
    assert_eq!(completed.request.provider.as_deref(), Some("xai"));
    assert_eq!(
        completed.request.model.as_deref(),
        Some("grok-4.20-0309-reasoning")
    );

    let _ = shutdown.send(());
    Ok(())
}

