#[tokio::test]
async fn daemon_interrupts_in_flight_runs() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = slow_daemon(&state_root).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("interrupt-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let mut stream = client
        .get(format!("{base}/v1/sessions/interrupt-session/stream"))
        .send()
        .await?
        .error_for_status()?;

    let input_client = client.clone();
    let input_base = base.clone();
    let in_flight = tokio::spawn(async move {
        input_client
            .post(format!("{input_base}/v1/sessions/interrupt-session/input"))
            .json(&SubmitInputRequest {
                source_plugin: None,
                source_kind: None,
                actor_id: None,
                provider: None,
                content: "keep working".to_string(),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                reply_address: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
            })
            .send()
            .await
    });

    loop {
        let (event_name, event) = next_sse_event(&mut stream).await?;
        match event {
            DaemonEvent::SessionStateChanged {
                session_id,
                status,
                pending_approvals,
                ..
            } => {
                assert_eq!(event_name, "session_state_changed");
                assert_eq!(session_id, "interrupt-session");
                assert_eq!(status, kheish_agent::AgentStatus::Running);
                assert_eq!(pending_approvals, 0);
                break;
            }
            DaemonEvent::RunUpdated { .. } | DaemonEvent::Trace { .. } => continue,
            other => panic!("unexpected SSE event: {other:?}"),
        }
    }

    let interrupted = client
        .post(format!("{base}/v1/sessions/interrupt-session/interrupt"))
        .send()
        .await?
        .error_for_status()?
        .json::<InterruptSessionResponse>()
        .await?;
    assert!(interrupted.interrupted);
    assert_eq!(
        interrupted.snapshot.agent.status,
        kheish_agent::AgentStatus::Idle
    );

    let in_flight = in_flight.await??;
    assert_eq!(in_flight.status(), StatusCode::CONFLICT);

    let restored = client
        .get(format!("{base}/v1/sessions/interrupt-session"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(
        restored.snapshot.agent.status,
        kheish_agent::AgentStatus::Idle
    );
    assert!(restored.snapshot.pending_approvals.is_empty());

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_exposes_runtime_reconfiguration_and_global_sse() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    // The daemon caches the KHEISH_DEBUG_CAPTURE_KEY validation result at
    // debug-store construction, so boot under the debug-capture env lock —
    // otherwise a parallel test's invalid-key window poisons this daemon's
    // health snapshot for its whole lifetime.
    let (address, shutdown) = {
        let _env_guard = crate::debug::debug_capture_env_lock();
        scripted_daemon(&state_root, Vec::new()).await?
    };
    let client = Client::new();
    let base = format!("http://{address}");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    let expected_root = state_root.to_string_lossy();
    assert_eq!(
        runtime.workspace_root.as_deref(),
        Some(expected_root.as_ref())
    );
    assert_eq!(runtime.state_root.as_deref(), Some(expected_root.as_ref()));
    assert_eq!(runtime.provider.as_deref(), Some("scripted"));
    assert_eq!(runtime.model.as_deref(), Some("scripted-model"));
    assert_eq!(runtime.permission_mode, PermissionMode::Default);

    // The health snapshot reads the process-global KHEISH_DEBUG_* variables at
    // request time; hold the debug-capture env lock so a parallel test cannot
    // mutate them mid-snapshot and fail the health assertion below.
    let status = {
        let _env_guard = crate::debug::debug_capture_env_lock();
        client
            .get(format!("{base}/v1/status"))
            .send()
            .await?
            .error_for_status()?
            .json::<DaemonStatusView>()
            .await?
    };
    assert_eq!(status.status, DaemonReadinessState::Ready);
    assert!(status.ready);
    assert!(status.snapshot_at_ms > 0);
    assert!(status.process_id > 0);
    let expected_bind = address.to_string();
    assert_eq!(
        status.control_plane.bind_addr.as_deref(),
        Some(expected_bind.as_str())
    );
    assert!(status.control_plane.bind_is_loopback);
    assert!(!status.control_plane.bind_is_unspecified);
    assert_eq!(status.control_plane.auth_enabled, false);
    assert_eq!(
        status.control_plane.cors_policy,
        DaemonControlPlaneCorsPolicy::Loopback
    );
    assert!(!status.control_plane.externally_exposed_without_auth);
    assert!(
        status.health.ok,
        "unexpected status health: {:?}",
        status.health
    );
    assert_eq!(status.health.generated_at_ms, status.snapshot_at_ms);

    // Subscribe from the epoch cursor: events are recorded into the bus
    // history before they broadcast, so the runtime_updated event below is
    // delivered through replay even if it fires before this subscription
    // registers. Without the cursor this test races the subscription under
    // parallel-suite load.
    let mut stream = client
        .get(format!("{base}/v1/events/stream"))
        .header("Last-Event-ID", "0")
        .send()
        .await?
        .error_for_status()?;

    let updated = client
        .post(format!("{base}/v1/runtime/permission-mode"))
        .json(&SetPermissionModeRequest {
            mode: PermissionMode::DontAsk,
            expected_revision: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(updated.permission_mode, PermissionMode::DontAsk);

    let (first_event_id, event) = next_sse_event_named(&mut stream, "runtime_updated").await?;
    match event {
        DaemonEvent::RuntimeUpdated { runtime } => {
            assert_eq!(runtime.permission_mode, PermissionMode::DontAsk);
            assert_eq!(runtime.model.as_deref(), Some("scripted-model"));
        }
        other => panic!("unexpected SSE event: {other:?}"),
    }
    let first_event_id = first_event_id.expect("runtime_updated events should carry an SSE id");

    // Resume after the first mutation's event so the second subscription only
    // sees the model change, replayed or live.
    let mut stream = client
        .get(format!("{base}/v1/events/stream"))
        .header("Last-Event-ID", first_event_id.to_string())
        .send()
        .await?
        .error_for_status()?;

    let updated = client
        .post(format!("{base}/v1/runtime/model"))
        .json(&SetModelRequest {
            provider: None,
            model: "scripted-model-v2".to_string(),
            expected_revision: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(updated.model.as_deref(), Some("scripted-model-v2"));

    let (_, event) = next_sse_event_named(&mut stream, "runtime_updated").await?;
    match event {
        DaemonEvent::RuntimeUpdated { runtime } => {
            assert_eq!(runtime.model.as_deref(), Some("scripted-model-v2"));
            assert_eq!(runtime.permission_mode, PermissionMode::DontAsk);
        }
        other => panic!("unexpected SSE event: {other:?}"),
    }

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.model.as_deref(), Some("scripted-model-v2"));
    assert_eq!(runtime.permission_mode, PermissionMode::DontAsk);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_revisions_persist_and_roll_back_after_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = routed_scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(initial.config.revision, 0);

    let permission = client
        .post(format!("{base}/v1/runtime/permission-mode"))
        .json(&SetPermissionModeRequest {
            mode: PermissionMode::AcceptEdits,
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(permission.config.revision, 1);
    assert_eq!(permission.permission_mode, PermissionMode::AcceptEdits);

    let debug = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Full,
            expected_revision: Some(permission.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(debug.config.revision, 2);
    assert_eq!(debug.debug_level, DebugCaptureLevel::Full);

    let prompt = client
        .post(format!("{base}/v1/runtime/system-prompt"))
        .json(&SetSystemPromptRequest {
            settings: SystemPromptSettings {
                custom_prompt: Some("persisted prompt".to_string()),
                ..SystemPromptSettings::default()
            },
            expected_revision: Some(debug.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(prompt.config.revision, 3);
    assert_eq!(
        prompt.system_prompt.custom_prompt.as_deref(),
        Some("persisted prompt")
    );

    let model = client
        .post(format!("{base}/v1/runtime/model"))
        .json(&SetModelRequest {
            provider: Some("openai".to_string()),
            model: "gpt-5.4".to_string(),
            expected_revision: Some(prompt.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(model.config.revision, 4);
    assert_eq!(model.route_id.as_deref(), Some("openai"));
    assert_eq!(model.model.as_deref(), Some("gpt-5.4"));

    let mut low_tool_limits = model.tool_runtime_limits.clone();
    low_tool_limits.max_calls_per_turn = 3;
    low_tool_limits.max_cumulative_result_envelope_bytes = 12_345;
    let tool_limits = client
        .post(format!("{base}/v1/runtime/tool-limits"))
        .json(&SetToolRuntimeLimitsRequest {
            limits: low_tool_limits.clone(),
            expected_revision: Some(model.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(tool_limits.config.revision, 5);
    assert_eq!(tool_limits.tool_runtime_limits, low_tool_limits);

    let mut short_run_memory_policy = tool_limits.run_memory_policy.clone();
    short_run_memory_policy.retention_ms = 120_000;
    short_run_memory_policy.max_tracked_per_session = 6;
    short_run_memory_policy.max_prompt_entries = 2;
    let run_memory_policy = client
        .post(format!("{base}/v1/runtime/run-memory-policy"))
        .json(&SetRunMemoryPolicyRequest {
            policy: short_run_memory_policy.clone(),
            expected_revision: Some(tool_limits.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(run_memory_policy.config.revision, 6);
    assert_eq!(run_memory_policy.run_memory_policy, short_run_memory_policy);

    let learning_policy_settings = LearningAutomationPolicyConfig {
        mode: LearningAutomationMode::ManualOnly,
        capture: LearningCapturePolicy {
            run_summary_candidates: false,
            semantic_candidates: LearningSemanticCaptureConfig::default(),
        },
        ..LearningAutomationPolicyConfig::default()
    };
    let learning_policy = client
        .post(format!("{base}/v1/runtime/learning-policy"))
        .json(&SetLearningPolicyRequest {
            policy: learning_policy_settings.clone(),
            expected_revision: Some(run_memory_policy.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(learning_policy.config.revision, 7);
    assert_eq!(learning_policy.learning_policy, learning_policy_settings);

    let revisions = client
        .get(format!("{base}/v1/runtime/revisions"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeConfigRevisionListResponse>()
        .await?;
    assert_eq!(revisions.revisions.len(), 7);
    assert_eq!(revisions.revisions[0].revision, 7);
    assert_eq!(
        revisions.revisions[0].learning_policy.as_ref(),
        Some(&learning_policy_settings)
    );

    let rolled_back = client
        .post(format!("{base}/v1/runtime/rollback"))
        .json(&RuntimeRollbackRequest {
            target_revision: Some(permission.config.revision),
            expected_revision: Some(learning_policy.config.revision),
            skip_hooks: false,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(rolled_back.config.revision, 8);
    assert_eq!(rolled_back.permission_mode, PermissionMode::AcceptEdits);
    assert_eq!(rolled_back.debug_level, DebugCaptureLevel::Off);
    assert!(rolled_back.system_prompt.custom_prompt.is_none());
    assert_eq!(rolled_back.learning_policy, permission.learning_policy);
    assert_eq!(
        rolled_back.route_id.as_deref(),
        permission.route_id.as_deref()
    );
    assert_eq!(rolled_back.model.as_deref(), permission.model.as_deref());
    assert_eq!(
        rolled_back.tool_runtime_limits,
        permission.tool_runtime_limits
    );
    assert_eq!(rolled_back.run_memory_policy, permission.run_memory_policy);

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let (restart_address, restart_shutdown) =
        routed_scripted_daemon(&state_root, Vec::new()).await?;
    let restart_base = format!("http://{restart_address}");
    wait_for_daemon_ready(&client, &restart_base).await?;
    let restored = client
        .get(format!("{restart_base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(restored.config.revision, rolled_back.config.revision);
    assert_eq!(restored.permission_mode, rolled_back.permission_mode);
    assert_eq!(restored.debug_level, rolled_back.debug_level);
    assert_eq!(restored.system_prompt, rolled_back.system_prompt);
    assert_eq!(restored.learning_policy, rolled_back.learning_policy);
    assert_eq!(restored.route_id, rolled_back.route_id);
    assert_eq!(restored.model, rolled_back.model);
    assert_eq!(
        restored.tool_runtime_limits,
        rolled_back.tool_runtime_limits
    );
    assert_eq!(restored.run_memory_policy, rolled_back.run_memory_policy);

    let _ = restart_shutdown.send(());
    Ok(())
}

