#[tokio::test]
async fn daemon_runtime_config_corrupt_legacy_sidecars_do_not_block_restart() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let manual_policy = LearningAutomationPolicyConfig {
        mode: LearningAutomationMode::ManualOnly,
        capture: LearningCapturePolicy {
            run_summary_candidates: false,
            semantic_candidates: LearningSemanticCaptureConfig::default(),
        },
        ..LearningAutomationPolicyConfig::default()
    };
    let hooks = HookSettings {
        hooks: std::iter::once((
            HookEventName::SessionStart,
            vec![kheish_types::HookDefinition {
                name: "runtime-config-hook".to_string(),
                matcher: None,
                failure_policy: kheish_types::HookFailurePolicy::default(),
                executor: kheish_types::HookExecutorConfig::Command {
                    command: "true".to_string(),
                    shell: None,
                    timeout_ms: Some(1_000),
                },
            }],
        ))
        .collect(),
    };
    let current_revision = RuntimeConfigRevisionView {
        revision: 1,
        updated_at_ms: 1,
        source: "test".to_string(),
        setting: "bootstrap".to_string(),
        rollback_of_revision: None,
        route_id: Some("anthropic".to_string()),
        provider: Some("anthropic".to_string()),
        model: Some("claude-opus-4-6".to_string()),
        permission_mode: PermissionMode::Default,
        system_prompt: SystemPromptSettings::default(),
        hooks: hooks.clone(),
        debug_level: DebugCaptureLevel::Off,
        learning_policy: Some(manual_policy.clone()),
        run_memory_policy: RunMemoryPolicyConfig::default(),
        tool_runtime_limits: kheish_runtime::ToolRuntimeLimits::default(),
    };
    fs::write(
        state_root.join("runtime-config.json"),
        serde_json::to_vec_pretty(&json!({
            "current": current_revision,
        }))?,
    )?;
    fs::write(state_root.join("hooks.json"), b"{not valid json")?;
    fs::write(state_root.join("learning-policy.json"), b"{not valid json")?;

    let (address, shutdown) = routed_scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");
    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, 1);
    assert_eq!(runtime.learning_policy, manual_policy);
    assert_eq!(runtime.hooks, crate::redacted_hook_settings(&hooks));
    let restored_hooks_value =
        serde_json::from_slice::<Value>(&fs::read(state_root.join("hooks.json"))?)?;
    assert_eq!(restored_hooks_value["schema_version"], json!(1));
    let restored_hooks = HookSettings {
        hooks: serde_json::from_value(
            restored_hooks_value
                .get("hooks")
                .cloned()
                .unwrap_or_else(|| json!({})),
        )?,
    };
    assert_eq!(restored_hooks, hooks);
    assert!(!state_root.join("learning-policy.json").exists());
    assert!(
        fs::read_dir(&state_root)?
            .filter_map(|entry| entry.ok())
            .any(|entry| entry
                .file_name()
                .to_string_lossy()
                .starts_with("hooks.json.corrupt-"))
    );
    assert!(
        fs::read_dir(&state_root)?
            .filter_map(|entry| entry.ok())
            .any(|entry| entry
                .file_name()
                .to_string_lossy()
                .starts_with("learning-policy.json.corrupt-"))
    );

    let _ = shutdown.send(());
    Ok(())
}

