#[tokio::test]
async fn daemon_runtime_config_expected_revision_rejects_stale_concurrent_set() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    let revision = initial.config.revision;
    let left_client = client.clone();
    let left_base = base.clone();
    let right_client = client.clone();
    let right_base = base.clone();
    let (left, right) = tokio::join!(
        async move {
            left_client
                .post(format!("{left_base}/v1/runtime/permission-mode"))
                .json(&SetPermissionModeRequest {
                    mode: PermissionMode::DontAsk,
                    expected_revision: Some(revision),
                })
                .send()
                .await
        },
        async move {
            right_client
                .post(format!("{right_base}/v1/runtime/permission-mode"))
                .json(&SetPermissionModeRequest {
                    mode: PermissionMode::AcceptEdits,
                    expected_revision: Some(revision),
                })
                .send()
                .await
        }
    );
    let left = left?;
    let right = right?;
    let statuses = [left.status(), right.status()];
    assert!(statuses.contains(&StatusCode::OK));
    assert!(statuses.contains(&StatusCode::CONFLICT));
    let conflict = if left.status() == StatusCode::CONFLICT {
        left
    } else {
        right
    };
    let problem = conflict.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_revision_conflict");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, revision + 1);

    let stale_learning_policy = client
        .post(format!("{base}/v1/runtime/learning-policy"))
        .json(&SetLearningPolicyRequest {
            policy: LearningAutomationPolicyConfig::default(),
            expected_revision: Some(revision),
        })
        .send()
        .await?;
    assert_eq!(stale_learning_policy.status(), StatusCode::CONFLICT);
    let problem = stale_learning_policy.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_revision_conflict");

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_rollback_races_with_cas_set_coherently() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let debug_on = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::On,
            expected_revision: Some(0),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(debug_on.config.revision, 1);

    let accept_edits = client
        .post(format!("{base}/v1/runtime/permission-mode"))
        .json(&SetPermissionModeRequest {
            mode: PermissionMode::AcceptEdits,
            expected_revision: Some(debug_on.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(accept_edits.config.revision, 2);

    let revision = accept_edits.config.revision;
    let rollback_client = client.clone();
    let rollback_base = base.clone();
    let set_client = client.clone();
    let set_base = base.clone();
    let (rollback, set_debug) = tokio::join!(
        async move {
            rollback_client
                .post(format!("{rollback_base}/v1/runtime/rollback"))
                .json(&RuntimeRollbackRequest {
                    target_revision: Some(debug_on.config.revision),
                    expected_revision: Some(revision),
                    skip_hooks: false,
                })
                .send()
                .await
        },
        async move {
            set_client
                .post(format!("{set_base}/v1/runtime/debug-level"))
                .json(&SetDebugLevelRequest {
                    level: DebugCaptureLevel::Full,
                    expected_revision: Some(revision),
                })
                .send()
                .await
        }
    );
    let rollback = rollback?;
    let set_debug = set_debug?;
    let statuses = [rollback.status(), set_debug.status()];
    assert!(statuses.contains(&StatusCode::OK));
    assert!(statuses.contains(&StatusCode::CONFLICT));
    let rollback_won = rollback.status() == StatusCode::OK;
    let conflict = if rollback_won { set_debug } else { rollback };
    let problem = conflict.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_revision_conflict");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, revision + 1);
    if rollback_won {
        assert_eq!(runtime.debug_level, DebugCaptureLevel::On);
        assert_eq!(runtime.permission_mode, PermissionMode::Default);
    } else {
        assert_eq!(runtime.debug_level, DebugCaptureLevel::Full);
        assert_eq!(runtime.permission_mode, PermissionMode::AcceptEdits);
    }

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_run_memory_policy_expected_revision_rejects_stale_set() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    let mut policy = initial.run_memory_policy.clone();
    policy.retention_ms = 60_000;
    policy.max_tracked_per_session = 8;
    policy.max_prompt_entries = 2;

    let updated = client
        .post(format!("{base}/v1/runtime/run-memory-policy"))
        .json(&SetRunMemoryPolicyRequest {
            policy: policy.clone(),
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(updated.config.revision, initial.config.revision + 1);
    assert_eq!(updated.run_memory_policy, policy);

    let mut stale_policy = updated.run_memory_policy.clone();
    stale_policy.retention_ms = 120_000;
    let stale = client
        .post(format!("{base}/v1/runtime/run-memory-policy"))
        .json(&SetRunMemoryPolicyRequest {
            policy: stale_policy,
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await?;
    assert_eq!(stale.status(), StatusCode::CONFLICT);
    let problem = stale.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_revision_conflict");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, updated.config.revision);
    assert_eq!(runtime.run_memory_policy, policy);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_tool_runtime_limits_are_live_and_reject_invalid_updates() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-tool-limits-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-tool-limits-1".to_string(),
                        name: "echo".to_string(),
                        input: json!({"text": "this input should exceed the live tool limit"}),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-tool-limits-2",
                "LIMIT_APPLIED",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    let mut invalid_limits = initial.tool_runtime_limits.clone();
    invalid_limits.max_input_bytes = 0;
    let invalid = client
        .post(format!("{base}/v1/runtime/tool-limits"))
        .json(&SetToolRuntimeLimitsRequest {
            limits: invalid_limits,
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await?;
    assert_eq!(invalid.status(), StatusCode::BAD_REQUEST);
    let problem = invalid.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "invalid_tool_runtime_limits");

    let mut limits = initial.tool_runtime_limits.clone();
    limits.max_input_bytes = 24;
    let updated = client
        .post(format!("{base}/v1/runtime/tool-limits"))
        .json(&SetToolRuntimeLimitsRequest {
            limits: limits.clone(),
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(updated.config.revision, initial.config.revision + 1);
    assert_eq!(updated.tool_runtime_limits.max_input_bytes, 24);

    let status = client
        .get(format!("{base}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json::<DaemonStatusView>()
        .await?;
    assert_eq!(status.runtime.tool_runtime_limits, limits);

    let session = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("tool-limits-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?;
    assert_eq!(session.status(), StatusCode::CREATED);

    let view = client
        .post(format!("{base}/v1/sessions/tool-limits-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "run".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(view.snapshot.pending_approvals.len(), 1);

    client
        .post(format!("{base}/v1/sessions/tool-limits-session/approvals"))
        .json(&ResolveApprovalsRequest {
            idempotency_key: None,
            resolutions: vec![ApprovalResolution {
                request_id: view.snapshot.pending_approvals[0].id.clone(),
                behavior: kheish_types::ApprovalResolutionBehavior::Allow,
                updated_input: None,
                justification: Some("approved".to_string()),
                reason: None,
            }],
        })
        .send()
        .await?
        .error_for_status()?;

    let events = client
        .get(format!("{base}/v1/sessions/tool-limits-session/events"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionEventLogView>()
        .await?;
    let result = events
        .session
        .journal
        .iter()
        .find_map(|entry| match &entry.event {
            SessionEvent::ToolCallFinished { result }
                if result.tool_name.as_deref() == Some("echo") =>
            {
                Some(result)
            }
            _ => None,
        })
        .ok_or_else(|| anyhow!("missing echo tool result"))?;
    assert!(
        result.is_error,
        "echo should fail on live limit: {result:#?}"
    );
    assert_eq!(result.output["quota"], "input_bytes");

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_concurrent_field_sets_do_not_revert_each_other() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = routed_scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let left_client = client.clone();
    let left_base = base.clone();
    let right_client = client.clone();
    let right_base = base.clone();
    let (model_set, permission_set) = tokio::join!(
        async move {
            left_client
                .post(format!("{left_base}/v1/runtime/model"))
                .json(&SetModelRequest {
                    provider: Some("openai".to_string()),
                    model: "gpt-5.4".to_string(),
                    expected_revision: None,
                })
                .send()
                .await
        },
        async move {
            right_client
                .post(format!("{right_base}/v1/runtime/permission-mode"))
                .json(&SetPermissionModeRequest {
                    mode: PermissionMode::AcceptEdits,
                    expected_revision: None,
                })
                .send()
                .await
        }
    );
    model_set?.error_for_status()?;
    permission_set?.error_for_status()?;

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.route_id.as_deref(), Some("openai"));
    assert_eq!(runtime.model.as_deref(), Some("gpt-5.4"));
    assert_eq!(runtime.permission_mode, PermissionMode::AcceptEdits);
    assert_eq!(runtime.config.revision, 2);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_precommit_hook_does_not_expose_pending_route() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    fs::create_dir_all(&state_root)?;
    let (address, shutdown) = routed_scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-runtime-inflight-pin-1",
            "INFLIGHT_PIN_OK",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    create_test_session(&client, &base, "runtime-inflight-pin").await?;
    let hook_started = state_root.join("config-hook-started");
    let delayed_hook = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: std::iter::once((
                HookEventName::ConfigChange,
                vec![kheish_types::HookDefinition {
                    name: "delay-config".to_string(),
                    matcher: Some("runtime_api".to_string()),
                    failure_policy: kheish_types::HookFailurePolicy::default(),
                    executor: kheish_types::HookExecutorConfig::Command {
                        command: format!(
                            "printf started > '{}'; sleep 0.25",
                            hook_started.display()
                        ),
                        shell: None,
                        timeout_ms: Some(2_000),
                    },
                }],
            ))
            .collect(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(delayed_hook.config.revision, 1);

    let model_client = client.clone();
    let model_base = base.clone();
    let model_task = tokio::spawn(async move {
        model_client
            .post(format!("{model_base}/v1/runtime/model"))
            .json(&SetModelRequest {
                provider: Some("openai".to_string()),
                model: "gpt-5.4".to_string(),
                expected_revision: Some(delayed_hook.config.revision),
            })
            .send()
            .await
    });
    for _ in 0..200 {
        if hook_started.exists() {
            break;
        }
        if model_task.is_finished() {
            let response = model_task.await??;
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            anyhow::bail!("model change completed before config hook marker: {status}: {body}");
        }
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    assert!(
        hook_started.exists(),
        "config_change hook did not start before route pinning assertion"
    );

    let submitted = client
        .post(format!("{base}/v1/sessions/runtime-inflight-pin/runs"))
        .json(&test_submit_input_request("pin after in-flight mutation"))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let changed = model_task
        .await??
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(changed.route_id.as_deref(), Some("openai"));
    assert_eq!(changed.config.revision, 2);
    assert_eq!(submitted.request.provider.as_deref(), Some("anthropic"));
    assert_eq!(submitted.request.model.as_deref(), Some("claude-opus-4-6"));

    let completed = wait_for_run_status(
        &client,
        &base,
        &submitted.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert!(
        completed.outputs[0].content.contains("INFLIGHT_PIN_OK"),
        "unexpected output: {}",
        serde_json::to_string_pretty(&completed)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_hook_block_is_transactional() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let with_hook = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: std::iter::once((
                HookEventName::ConfigChange,
                vec![kheish_types::HookDefinition {
                    name: "block-config".to_string(),
                    matcher: Some("runtime_api".to_string()),
                    failure_policy: kheish_types::HookFailurePolicy {
                        mode: kheish_types::HookFailureMode::Closed,
                        ..Default::default()
                    },
                    executor: kheish_types::HookExecutorConfig::Command {
                        command: "exit 2".to_string(),
                        shell: None,
                        timeout_ms: Some(1_000),
                    },
                }],
            ))
            .collect(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(with_hook.config.revision, 1);
    assert_eq!(with_hook.debug_level, DebugCaptureLevel::Off);

    let blocked = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Full,
            expected_revision: Some(with_hook.config.revision),
        })
        .send()
        .await?;
    assert_eq!(blocked.status(), StatusCode::CONFLICT);
    let problem = blocked.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_change_blocked");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, with_hook.config.revision);
    assert_eq!(runtime.debug_level, DebugCaptureLevel::Off);

    let stale_hook_set = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&SetHooksRequest {
            settings: HookSettings::default(),
            expected_revision: Some(0),
            skip_hooks: true,
        })
        .send()
        .await?;
    assert_eq!(stale_hook_set.status(), StatusCode::CONFLICT);
    let problem = stale_hook_set.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_revision_conflict");

    let normal_reset = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&SetHooksRequest {
            settings: HookSettings::default(),
            expected_revision: Some(with_hook.config.revision),
            skip_hooks: false,
        })
        .send()
        .await?;
    assert_eq!(normal_reset.status(), StatusCode::CONFLICT);
    let problem = normal_reset.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_change_blocked");

    let forced_reset = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&SetHooksRequest {
            settings: HookSettings::default(),
            expected_revision: Some(with_hook.config.revision),
            skip_hooks: true,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(forced_reset.config.revision, with_hook.config.revision + 1);
    assert!(forced_reset.hooks.hooks.is_empty());

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_config_rollback_can_skip_blocking_hook() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let baseline = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::On,
            expected_revision: Some(0),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(baseline.config.revision, 1);

    let with_hook = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: std::iter::once((
                HookEventName::ConfigChange,
                vec![kheish_types::HookDefinition {
                    name: "block-config".to_string(),
                    matcher: Some("runtime_api".to_string()),
                    failure_policy: kheish_types::HookFailurePolicy {
                        mode: kheish_types::HookFailureMode::Closed,
                        ..Default::default()
                    },
                    executor: kheish_types::HookExecutorConfig::Command {
                        command: "exit 2".to_string(),
                        shell: None,
                        timeout_ms: Some(1_000),
                    },
                }],
            ))
            .collect(),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(with_hook.config.revision, 2);

    let blocked = client
        .post(format!("{base}/v1/runtime/rollback"))
        .json(&RuntimeRollbackRequest {
            target_revision: Some(baseline.config.revision),
            expected_revision: Some(with_hook.config.revision),
            skip_hooks: false,
        })
        .send()
        .await?;
    assert_eq!(blocked.status(), StatusCode::CONFLICT);
    let problem = blocked.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "runtime_change_blocked");

    let rolled_back = client
        .post(format!("{base}/v1/runtime/rollback"))
        .json(&RuntimeRollbackRequest {
            target_revision: Some(baseline.config.revision),
            expected_revision: Some(with_hook.config.revision),
            skip_hooks: true,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(rolled_back.config.revision, 3);
    assert_eq!(rolled_back.debug_level, DebugCaptureLevel::On);
    assert!(rolled_back.hooks.hooks.is_empty());

    let _ = shutdown.send(());
    Ok(())
}

