#[cfg(unix)]
#[tokio::test]
async fn daemon_runtime_config_persist_failure_rolls_back_live_state() -> Result<()> {
    use std::os::unix::fs::PermissionsExt as _;

    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(initial.config.revision, 0);
    assert_eq!(initial.debug_level, DebugCaptureLevel::Off);

    let original_mode = fs::metadata(&state_root)?.permissions().mode();
    fs::set_permissions(&state_root, fs::Permissions::from_mode(0o500))?;
    let response = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Full,
            expected_revision: Some(initial.config.revision),
        })
        .send()
        .await;
    fs::set_permissions(&state_root, fs::Permissions::from_mode(original_mode))?;

    let response = response?;
    assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, initial.config.revision);
    assert_eq!(runtime.debug_level, initial.debug_level);

    let recovered = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::On,
            expected_revision: Some(runtime.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(recovered.config.revision, runtime.config.revision + 1);
    assert_eq!(recovered.debug_level, DebugCaptureLevel::On);

    let _ = shutdown.send(());
    Ok(())
}

