#[tokio::test]
async fn daemon_asset_raw_endpoint_rejects_live_integrity_mismatch() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(10)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let imported = client
        .post(format!("{base}/v1/assets"))
        .json(&CreateAssetRequest {
            upload: InlineAssetUpload {
                file_name: "tamper-check.txt".to_string(),
                media_type: Some("text/plain".to_string()),
                content_base64: BASE64_STANDARD.encode(b"ORIGINAL_ASSET_BYTES"),
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;
    let raw_path = state_root
        .join("assets")
        .join("raw")
        .join(format!("{}.txt", imported.asset_id));
    fs::write(&raw_path, b"TAMPERED_BYTES")
        .with_context(|| format!("failed to tamper asset raw file {}", raw_path.display()))?;

    let response = client
        .get(format!("{base}/v1/assets/{}/raw", imported.asset_id))
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::CONFLICT);
    let problem = response.json::<Value>().await?;
    assert_eq!(problem["domain"], "assets");
    assert_eq!(problem["code"], "asset_integrity_mismatch");
    assert!(
        problem["detail"]
            .as_str()
            .is_some_and(|detail| detail.contains(&imported.asset_id))
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_emit_output_records_rich_outputs_as_the_canonical_final_response() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![
            Ok(vec![
                ModelStreamEvent::MessageId {
                    value: "assistant-rich-1".to_string(),
                },
                ModelStreamEvent::ToolCall {
                    call: kheish_types::ToolCallRecord {
                        id: "call-emit-1".to_string(),
                        name: "emit_output".to_string(),
                        input: json!({
                            "content": "Here is the generated image.",
                            "parts": [
                                { "type": "asset", "asset_id": "asset-1" }
                            ],
                            "artifact_ids": ["asset-1"],
                        }),
                        assistant_message_id: None,
                        assistant_provider_response_id: None,
                    },
                },
                ModelStreamEvent::Stop {
                    reason: kheish_types::ModelFinishReason::ToolCalls,
                },
            ]),
            Ok(scripted_events(
                "assistant-rich-2",
                "MODEL_TEXT_SHOULD_NOT_REPLACE_EMIT_OUTPUT",
                kheish_types::ModelFinishReason::Completed,
            )),
        ],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("emit-output-demo".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let png_bytes = sample_png_bytes()?;
    let asset = client
        .post(format!("{base}/v1/assets"))
        .json(&CreateAssetRequest {
            upload: InlineAssetUpload {
                file_name: "asset-inline.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(&png_bytes),
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;
    assert_eq!(asset.asset_id, "asset-1");

    let run = client
        .post(format!("{base}/v1/sessions/emit-output-demo/runs"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "Return one rich output.".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let completed =
        wait_for_run_status(&client, &base, &run.run_id, &[DaemonRunStatus::Completed]).await?;
    let output = completed
        .outputs
        .last()
        .expect("completed run should expose one output");
    assert_eq!(
        output.content,
        "Here is the generated image.\nAttached asset: asset-inline.png (image/png)"
    );
    assert_eq!(output.parts.len(), 2);
    assert!(matches!(
        &output.parts[0],
        kheish_types::ContentPart::Text { text } if text == "Here is the generated image."
    ));
    assert!(matches!(
        &output.parts[1],
        kheish_types::ContentPart::Attachment { attachment } if attachment.id == "asset-1"
    ));
    assert_eq!(output.artifacts.len(), 1);
    assert_eq!(output.artifacts[0].id, "asset-1");

    let session = client
        .get(format!("{base}/v1/sessions/emit-output-demo"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(
        session.outputs.iter().any(|record| {
            record.content
                == "Here is the generated image.\nAttached asset: asset-inline.png (image/png)"
                && record.parts.len() == 2
                && record.artifacts.len() == 1
        }),
        "session outputs did not preserve the canonical rich output: {}",
        serde_json::to_string_pretty(&session)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_endpoints_materialize_supported_asset_profiles() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let cases = vec![
        (
            "note.txt",
            Some("text/plain"),
            b"DERIVATION_TEXT_OK".to_vec(),
            "DERIVATION_TEXT_OK",
            "DERIVATION_TEXT_OK",
        ),
        (
            "rooms.csv",
            Some("text/csv"),
            sample_csv_bytes(),
            "room,width,height\nDining Room,6.5,3.4\nOther,9.4,2.9",
            "Dining Room,6.5,3.4",
        ),
        (
            "note.md",
            Some("text/markdown"),
            b"# Heading\n\nDERIVATION_MARKDOWN_OK".to_vec(),
            "# Heading\n\nDERIVATION_MARKDOWN_OK",
            "DERIVATION_MARKDOWN_OK",
        ),
        (
            "plan.dxf",
            Some("application/dxf"),
            sample_dxf_bytes(),
            "DXF summary",
            "Explicit dimensions: 3.2 / 3.20",
        ),
        (
            "note.json",
            Some("application/json"),
            br#"{"marker":"DERIVATION_JSON_OK"}"#.to_vec(),
            "{\n  \"marker\": \"DERIVATION_JSON_OK\"\n}",
            "\"marker\": \"DERIVATION_JSON_OK\"",
        ),
        (
            "note.pdf",
            Some("application/pdf"),
            sample_pdf_bytes("DERIVATION_PDF_OK")?,
            "DERIVATION_PDF_OK",
            "DERIVATION_PDF_OK",
        ),
        (
            "pixel.png",
            Some("image/png"),
            sample_png_bytes()?,
            "Attached image: pixel.png (image/png)",
            "Attached image: pixel.png (image/png)",
        ),
        (
            "pixel.jpg",
            Some("image/jpeg"),
            sample_jpeg_bytes()?,
            "Attached image: pixel.jpg (image/jpeg)",
            "Attached image: pixel.jpg (image/jpeg)",
        ),
    ];

    let mut imported_assets = Vec::new();
    for (file_name, media_type, bytes, header, marker) in cases {
        let asset = client
            .post(format!("{base}/v1/assets"))
            .json(&CreateAssetRequest {
                upload: InlineAssetUpload {
                    file_name: file_name.to_string(),
                    media_type: media_type.map(str::to_string),
                    content_base64: BASE64_STANDARD.encode(&bytes),
                },
            })
            .send()
            .await?
            .error_for_status()?
            .json::<AssetView>()
            .await?;
        imported_assets.push((asset, header.to_string(), marker.to_string()));
    }

    let mut created_ids = Vec::new();
    for (asset, header, marker) in &imported_assets {
        let created = client
            .post(format!("{base}/v1/derivations"))
            .json(&CreateDerivationRequest {
                profile: DerivationProfile::CanonicalText,
                subject: DerivationSubject::Asset {
                    asset_id: asset.asset_id.clone(),
                },
                transcription: None,
            })
            .send()
            .await?
            .error_for_status()?
            .json::<DerivationView>()
            .await?;
        let duplicate = client
            .post(format!("{base}/v1/derivations"))
            .json(&CreateDerivationRequest {
                profile: DerivationProfile::CanonicalText,
                subject: DerivationSubject::Asset {
                    asset_id: asset.asset_id.clone(),
                },
                transcription: None,
            })
            .send()
            .await?
            .error_for_status()?
            .json::<DerivationView>()
            .await?;
        if created_ids.is_empty() {
            assert_eq!(created.derivation_id, "derivation-1");
        }
        assert_eq!(duplicate.derivation_id, created.derivation_id);
        created_ids.push(created.derivation_id.clone());

        let derived_raw = client
            .get(format!("{base}/v1/assets/{}/raw", created.result_asset_id))
            .send()
            .await?
            .error_for_status()?;
        let derived_text = derived_raw.text().await?;
        assert!(
            derived_text.contains(header),
            "expected canonical derivation header {header} in: {derived_text}"
        );
        assert!(
            derived_text.contains(marker),
            "expected canonical derivation marker {marker} in: {derived_text}"
        );
        let result_asset = client
            .get(format!("{base}/v1/assets/{}", created.result_asset_id))
            .send()
            .await?
            .error_for_status()?
            .json::<AssetView>()
            .await?;
        assert!(
            result_asset.derivation_ids.contains(&created.derivation_id),
            "result asset should include reverse derivation provenance: {result_asset:#?}"
        );

        let fetched = client
            .get(format!("{base}/v1/derivations/{}", created.derivation_id))
            .send()
            .await?
            .error_for_status()?
            .json::<DerivationView>()
            .await?;
        let mut created_without_cache_status = created.clone();
        created_without_cache_status.cache_status = None;
        assert_eq!(fetched, created_without_cache_status);
    }

    let listed = client
        .get(format!("{base}/v1/derivations"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<DerivationView>>()
        .await?;
    assert_eq!(listed.len(), created_ids.len());
    for derivation_id in &created_ids {
        assert!(
            listed
                .iter()
                .any(|candidate| &candidate.derivation_id == derivation_id),
            "missing derivation {derivation_id} from list response"
        );
    }

    let dxf_asset_id = imported_assets
        .iter()
        .find(|(asset, _, _)| asset.media_type == "application/dxf")
        .map(|(asset, _, _)| asset.asset_id.clone())
        .expect("missing dxf asset");
    let dxf_preview = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::VisualPreview,
            subject: DerivationSubject::Asset {
                asset_id: dxf_asset_id.clone(),
            },
            transcription: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert!(!dxf_preview.reused_subject_asset);
    let preview_raw = client
        .get(format!(
            "{base}/v1/assets/{}/raw",
            dxf_preview.result_asset_id
        ))
        .send()
        .await?
        .error_for_status()?;
    let preview_bytes = preview_raw.bytes().await?;
    image::load_from_memory_with_format(&preview_bytes, image::ImageFormat::Png)
        .context("DXF preview derivation should be a decodable PNG")?;
    let dxf_preview_asset = client
        .get(format!("{base}/v1/assets/{}", dxf_preview.result_asset_id))
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;
    assert!(
        dxf_preview_asset
            .derivation_ids
            .contains(&dxf_preview.derivation_id)
    );

    for media_type in ["image/png", "image/jpeg"] {
        let source_asset = imported_assets
            .iter()
            .find(|(asset, _, _)| asset.media_type == media_type)
            .map(|(asset, _, _)| asset.clone())
            .expect("missing image asset");
        let preview = client
            .post(format!("{base}/v1/derivations"))
            .json(&CreateDerivationRequest {
                profile: DerivationProfile::VisualPreview,
                subject: DerivationSubject::Asset {
                    asset_id: source_asset.asset_id.clone(),
                },
                transcription: None,
            })
            .send()
            .await?
            .error_for_status()?
            .json::<DerivationView>()
            .await?;
        assert!(preview.reused_subject_asset);
        assert_eq!(preview.result_asset_id, source_asset.asset_id);
        let reused_asset = client
            .get(format!("{base}/v1/assets/{}", preview.result_asset_id))
            .send()
            .await?
            .error_for_status()?
            .json::<AssetView>()
            .await?;
        assert!(
            reused_asset.derivation_ids.contains(&preview.derivation_id),
            "reused result asset should include reverse derivation provenance: {reused_asset:#?}"
        );
    }

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_endpoints_support_session_input_subjects() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(10)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let imported = client
        .post(format!("{base}/v1/assets"))
        .json(&CreateAssetRequest {
            upload: InlineAssetUpload {
                file_name: "reference.txt".to_string(),
                media_type: Some("text/plain".to_string()),
                content_base64: BASE64_STANDARD.encode(b"SESSION_INPUT_ASSET_OK"),
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("derivation-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;
    client
        .post(format!("{base}/v1/sessions/derivation-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: String::new(),
            input_items: vec![
                SubmitInputItemRequest::Text {
                    text: "Inspect the uploaded asset.".to_string(),
                },
                SubmitInputItemRequest::AssetReference {
                    asset_id: imported.asset_id.clone(),
                },
            ],
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let session_events = client
        .get(format!("{base}/v1/sessions/derivation-session/events"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionEventLogView>()
        .await?;
    let input_offset = session_events
        .session
        .journal
        .iter()
        .find_map(|entry| match &entry.event {
            SessionEvent::InputReceived { .. } => Some(entry.offset),
            _ => None,
        })
        .expect("missing InputReceived event");

    let derivation = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::SessionInput {
                session_id: "derivation-session".to_string(),
                offset: input_offset,
            },
            transcription: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    let derived_raw = client
        .get(format!(
            "{base}/v1/assets/{}/raw",
            derivation.result_asset_id
        ))
        .send()
        .await?
        .error_for_status()?;
    let derived_text = derived_raw.text().await?;
    assert!(derived_text.contains("Inspect the uploaded asset."));
    assert!(derived_text.contains("SESSION_INPUT_ASSET_OK"));

    let invalid_preview = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::VisualPreview,
            subject: DerivationSubject::SessionInput {
                session_id: "derivation-session".to_string(),
                offset: input_offset,
            },
            transcription: None,
        })
        .send()
        .await?;
    assert_eq!(invalid_preview.status(), StatusCode::BAD_REQUEST);
    let invalid_preview_body = invalid_preview.text().await?;
    assert!(invalid_preview_body.contains("do not expose a visual preview"));

    let invalid_offset = session_events
        .session
        .journal
        .iter()
        .find_map(|entry| match &entry.event {
            SessionEvent::InputReceived { .. } => None,
            _ => Some(entry.offset),
        })
        .expect("missing non-input session event");
    let non_input_response = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::SessionInput {
                session_id: "derivation-session".to_string(),
                offset: invalid_offset,
            },
            transcription: None,
        })
        .send()
        .await?;
    assert_eq!(non_input_response.status(), StatusCode::BAD_REQUEST);
    let non_input_body = non_input_response.text().await?;
    assert!(non_input_body.contains("does not contain an InputReceived event"));

    let unknown_session_response = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::SessionInput {
                session_id: "missing-session".to_string(),
                offset: input_offset,
            },
            transcription: None,
        })
        .send()
        .await?;
    assert_eq!(unknown_session_response.status(), StatusCode::NOT_FOUND);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_create_response_reports_cache_status() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let asset = import_test_asset(
        &client,
        &base,
        "cache-status.txt",
        "text/plain",
        b"DERIVATION_CACHE_STATUS_OK",
    )
    .await?;
    let request = CreateDerivationRequest {
        profile: DerivationProfile::CanonicalText,
        subject: DerivationSubject::Asset {
            asset_id: asset.asset_id.clone(),
        },
        transcription: None,
    };
    let first = client
        .post(format!("{base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(first.cache_status, Some(DerivationCacheStatus::Miss));

    let duplicate = client
        .post(format!("{base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(duplicate.derivation_id, first.derivation_id);
    assert_eq!(duplicate.cache_status, Some(DerivationCacheStatus::Hit));

    let fetched = client
        .get(format!("{base}/v1/derivations/{}", first.derivation_id))
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(fetched.derivation_id, first.derivation_id);
    assert_eq!(fetched.cache_status, None);
    let listed = client
        .get(format!("{base}/v1/derivations"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<DerivationView>>()
        .await?;
    assert_eq!(listed.len(), 1);
    assert_eq!(listed[0].cache_status, None);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_force_refresh_recomputes_and_updates_cache() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let recorded_media_types = Arc::new(Mutex::new(Vec::new()));
    let recorded_file_names = Arc::new(Mutex::new(Vec::new()));
    let transcription_service = scripted_transcription_service(
        "FORCED_TRANSCRIPT_OK",
        recorded_media_types,
        recorded_file_names.clone(),
    )?;
    let (address, shutdown) = echoing_delay_daemon_with_transcription_service(
        &state_root,
        Duration::from_millis(1),
        transcription_service.clone(),
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");
    let audio = import_test_asset(
        &client,
        &base,
        "force-refresh.wav",
        "audio/wav",
        &sample_wav_bytes(),
    )
    .await?;
    let request = CreateDerivationRequest {
        profile: DerivationProfile::CanonicalText,
        subject: DerivationSubject::Asset {
            asset_id: audio.asset_id.clone(),
        },
        transcription: None,
    };

    let first = client
        .post(format!("{base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(first.cache_status, Some(DerivationCacheStatus::Miss));
    let duplicate = client
        .post(format!("{base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(duplicate.cache_status, Some(DerivationCacheStatus::Hit));
    assert_eq!(duplicate.derivation_id, first.derivation_id);
    assert_eq!(recorded_file_names.lock().len(), 1);

    let forced = client
        .post(format!("{base}/v1/derivations?force_refresh=true"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(forced.cache_status, Some(DerivationCacheStatus::Miss));
    assert_ne!(forced.derivation_id, first.derivation_id);
    assert_eq!(
        recorded_file_names.lock().len(),
        2,
        "force refresh should bypass existing canonical text reuse and call the backend again"
    );

    let replayed = client
        .post(format!("{base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(replayed.cache_status, Some(DerivationCacheStatus::Hit));
    assert_eq!(replayed.derivation_id, forced.derivation_id);
    assert_eq!(recorded_file_names.lock().len(), 2);

    let forced_text = client
        .get(format!("{base}/v1/assets/{}/raw", forced.result_asset_id))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert_eq!(forced_text, "FORCED_TRANSCRIPT_OK");

    let _ = shutdown.send(());
    let (restart_address, restart_shutdown) = echoing_delay_daemon_with_transcription_service(
        &state_root,
        Duration::from_millis(1),
        transcription_service,
    )
    .await?;
    let restart_base = format!("http://{restart_address}");
    let restarted_replay = client
        .post(format!("{restart_base}/v1/derivations"))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(
        restarted_replay.cache_status,
        Some(DerivationCacheStatus::Hit)
    );
    assert_eq!(restarted_replay.derivation_id, forced.derivation_id);
    assert_eq!(
        recorded_file_names.lock().len(),
        2,
        "restart cache rebuild should keep the successful forced recompute preferred"
    );

    let _ = restart_shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_transcription_options_are_forwarded_and_cache_scoped() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let recorded_media_types = Arc::new(Mutex::new(Vec::new()));
    let recorded_file_names = Arc::new(Mutex::new(Vec::new()));
    let recorded_prompts = Arc::new(Mutex::new(Vec::new()));
    let recorded_languages = Arc::new(Mutex::new(Vec::new()));
    let transcription_service = scripted_transcription_service_with_hints(
        "OPTIONAL_TRANSCRIPTION_OK",
        recorded_media_types.clone(),
        recorded_file_names.clone(),
        recorded_prompts.clone(),
        recorded_languages.clone(),
    )?;
    let (address, shutdown) = echoing_delay_daemon_with_transcription_service(
        &state_root,
        Duration::from_millis(1),
        transcription_service,
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");
    let audio = import_test_asset(
        &client,
        &base,
        "optioned.wav",
        "audio/wav",
        &sample_wav_bytes(),
    )
    .await?;

    let first = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id.clone(),
            },
            transcription: Some(DerivationTranscriptionOptions {
                prompt: Some("  prefer the project glossary  ".to_string()),
                language: Some(" en ".to_string()),
                timestamp_granularities: Vec::new(),
                diarization: false,
            }),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(first.cache_status, Some(DerivationCacheStatus::Miss));
    assert!(
        first.source_fingerprint.contains(":transcription:v1:"),
        "optioned transcription source should include an option/backend cache digest: {}",
        first.source_fingerprint
    );
    let first_backend = first
        .backend
        .as_ref()
        .expect("optioned transcription should record backend provenance");
    assert_eq!(
        first_backend.pipeline_version,
        crate::transcription::TRANSCRIPTION_PIPELINE_VERSION
    );
    assert_eq!(
        first_backend.stitching_strategy,
        crate::transcription::TRANSCRIPTION_STITCHING_STRATEGY_SINGLE_PART
    );
    assert_eq!(
        first_backend.part_count,
        crate::transcription::TRANSCRIPTION_SINGLE_PART_COUNT
    );
    assert_eq!(
        recorded_prompts.lock().as_slice(),
        [Some("prefer the project glossary".to_string())]
    );
    assert_eq!(
        recorded_languages.lock().as_slice(),
        [Some("en".to_string())]
    );
    let refreshed_audio = client
        .get(format!("{base}/v1/assets/{}", audio.asset_id))
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;
    assert!(
        refreshed_audio.text_uri.is_none(),
        "option-specific transcription should not replace the asset's default canonical text"
    );

    let duplicate = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id.clone(),
            },
            transcription: Some(DerivationTranscriptionOptions {
                prompt: Some("prefer the project glossary".to_string()),
                language: Some("en".to_string()),
                timestamp_granularities: Vec::new(),
                diarization: false,
            }),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(duplicate.derivation_id, first.derivation_id);
    assert_eq!(duplicate.cache_status, Some(DerivationCacheStatus::Hit));
    assert_eq!(
        recorded_prompts.lock().len(),
        1,
        "same normalized transcription options should hit cache"
    );

    let changed_language = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id.clone(),
            },
            transcription: Some(DerivationTranscriptionOptions {
                prompt: Some("prefer the project glossary".to_string()),
                language: Some("fr".to_string()),
                timestamp_granularities: Vec::new(),
                diarization: false,
            }),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(
        changed_language.cache_status,
        Some(DerivationCacheStatus::Miss)
    );
    assert_ne!(changed_language.derivation_id, first.derivation_id);
    assert_eq!(
        recorded_languages.lock().as_slice(),
        [Some("en".to_string()), Some("fr".to_string())]
    );

    let timestamp_response = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id,
            },
            transcription: Some(DerivationTranscriptionOptions {
                prompt: None,
                language: None,
                timestamp_granularities: vec!["word".to_string()],
                diarization: false,
            }),
        })
        .send()
        .await?;
    assert_eq!(timestamp_response.status(), StatusCode::BAD_REQUEST);
    assert!(
        timestamp_response.text().await?.contains("whisper-1"),
        "timestamp options should fail with an explicit model capability message"
    );

    let _ = shutdown.send(());
    Ok(())
}

