#[tokio::test]
async fn daemon_derivation_concurrent_same_cache_key_returns_one_record() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let asset = client
        .post(format!("{base}/v1/assets"))
        .json(&CreateAssetRequest {
            upload: InlineAssetUpload {
                file_name: "concurrent.txt".to_string(),
                media_type: Some("text/plain".to_string()),
                content_base64: BASE64_STANDARD.encode(b"DERIVATION_CONCURRENT_OK"),
            },
        })
        .send()
        .await?
        .error_for_status()?
        .json::<AssetView>()
        .await?;

    let mut handles = Vec::new();
    for _ in 0..16 {
        let client = client.clone();
        let base = base.clone();
        let asset_id = asset.asset_id.clone();
        handles.push(tokio::spawn(async move {
            let view = client
                .post(format!("{base}/v1/derivations"))
                .json(&CreateDerivationRequest {
                    profile: DerivationProfile::CanonicalText,
                    subject: DerivationSubject::Asset { asset_id },
                    transcription: None,
                })
                .send()
                .await?
                .error_for_status()?
                .json::<DerivationView>()
                .await?;
            Ok::<DerivationView, anyhow::Error>(view)
        }));
    }

    let mut views = Vec::new();
    for handle in handles {
        views.push(handle.await??);
    }
    let first = views.first().expect("at least one derivation");
    assert_eq!(first.status, DerivationStatus::Completed);
    assert_eq!(first.profile_version, 1);
    assert!(first.source_fingerprint.contains("text/plain:"));
    assert!(
        views
            .iter()
            .all(|view| view.derivation_id == first.derivation_id)
    );
    assert!(
        views
            .iter()
            .all(|view| view.result_asset_id == first.result_asset_id)
    );

    let listed = client
        .get(format!("{base}/v1/derivations"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<DerivationView>>()
        .await?;
    assert_eq!(listed.len(), 1);

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_derivation_unrelated_cache_keys_run_in_parallel() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let calls = Arc::new(AtomicUsize::new(0));
    let in_flight = Arc::new(AtomicUsize::new(0));
    let max_in_flight = Arc::new(AtomicUsize::new(0));
    let entered = Arc::new(Notify::new());
    let release = Arc::new(Semaphore::new(0));
    let transcription_service = blocking_transcription_service(
        calls.clone(),
        in_flight,
        max_in_flight.clone(),
        entered.clone(),
        release.clone(),
    )?;
    let (address, shutdown) = echoing_delay_daemon_with_transcription_service(
        &state_root,
        Duration::from_millis(1),
        transcription_service,
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let first_audio = sample_wav_bytes();
    let mut second_audio = sample_wav_bytes();
    let last_byte = second_audio.last_mut().expect("sample wav has data bytes");
    *last_byte ^= 0x7f;
    let assets = vec![
        import_test_asset(&client, &base, "parallel-a.wav", "audio/wav", &first_audio).await?,
        import_test_asset(&client, &base, "parallel-b.wav", "audio/wav", &second_audio).await?,
    ];

    let mut handles = Vec::new();
    for asset in assets {
        let client = client.clone();
        let base = base.clone();
        handles.push(tokio::spawn(async move {
            let view = client
                .post(format!("{base}/v1/derivations"))
                .json(&CreateDerivationRequest {
                    profile: DerivationProfile::CanonicalText,
                    subject: DerivationSubject::Asset {
                        asset_id: asset.asset_id,
                    },
                    transcription: None,
                })
                .send()
                .await?
                .error_for_status()?
                .json::<DerivationView>()
                .await?;
            Ok::<DerivationView, anyhow::Error>(view)
        }));
    }

    let parallel_observed = tokio::time::timeout(Duration::from_secs(2), async {
        loop {
            if max_in_flight.load(Ordering::SeqCst) >= 2 {
                break;
            }
            entered.notified().await;
        }
    })
    .await
    .is_ok();
    release.add_permits(2);

    let mut views = Vec::new();
    for handle in handles {
        views.push(handle.await??);
    }
    assert!(
        parallel_observed,
        "unrelated derivation cache keys did not execute in parallel"
    );
    assert_eq!(calls.load(Ordering::SeqCst), 2);
    assert_eq!(views.len(), 2);
    assert_ne!(views[0].derivation_id, views[1].derivation_id);
    assert_ne!(views[0].result_asset_id, views[1].result_asset_id);
    assert!(
        views
            .iter()
            .all(|view| view.status == DerivationStatus::Completed)
    );
    assert!(
        views
            .iter()
            .all(|view| view.source_fingerprint.contains(":canonical:text/plain:")),
        "completed transcription derivations should persist the final canonical fingerprint: {views:#?}"
    );
    for view in &views {
        let backend = view
            .backend
            .as_ref()
            .expect("audio derivation should record transcription backend provenance");
        assert_eq!(backend.kind, "transcription");
        assert_eq!(backend.route_id, "blocking-transcription");
        assert_eq!(backend.provider, "openai");
        assert_eq!(backend.model, "gpt-4o-transcribe");
    }

    let listed = client
        .get(format!("{base}/v1/derivations"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<DerivationView>>()
        .await?;
    assert_eq!(listed.len(), 2);

    let _ = shutdown.send(());
    Ok(())
}

