#[tokio::test]
async fn daemon_derivation_asset_cache_key_changes_when_text_uri_changes() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let audio = import_test_asset(
        &client,
        &base,
        "cache-key-call.wav",
        "audio/wav",
        &sample_wav_bytes(),
    )
    .await?;
    let placeholder = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id.clone(),
            },
            transcription: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;
    assert_eq!(placeholder.status, DerivationStatus::Completed);
    assert!(
        !placeholder.source_fingerprint.contains(":canonical:"),
        "audio without canonical text should not include a canonical fingerprint: {}",
        placeholder.source_fingerprint
    );
    let placeholder_text = client
        .get(format!(
            "{base}/v1/assets/{}/raw",
            placeholder.result_asset_id
        ))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert!(placeholder_text.contains("Attached file: cache-key-call.wav (audio/wav)"));
    let _ = shutdown.send(());
    tokio::time::sleep(Duration::from_millis(100)).await;

    let asset_store = crate::assets::FileAssetStore::new(&state_root)?;
    let transcript_asset = asset_store.import_bytes(
        "cache-key-call.transcript.txt",
        Some("text/plain"),
        b"REAL_TRANSCRIPT_CACHE_KEY_OK",
    )?;
    asset_store.attach_text_asset(&audio.asset_id, &transcript_asset)?;

    let (restart_address, restart_shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let restart_base = format!("http://{restart_address}");
    let refreshed = client
        .post(format!("{restart_base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Asset {
                asset_id: audio.asset_id,
            },
            transcription: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<DerivationView>()
        .await?;

    assert_ne!(refreshed.derivation_id, placeholder.derivation_id);
    assert!(
        refreshed
            .source_fingerprint
            .contains(":canonical:text/plain:"),
        "asset with canonical text should include canonical fingerprint: {}",
        refreshed.source_fingerprint
    );
    assert_eq!(refreshed.result_asset_id, transcript_asset.id);
    let refreshed_text = client
        .get(format!(
            "{restart_base}/v1/assets/{}/raw",
            refreshed.result_asset_id
        ))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert_eq!(refreshed_text, "REAL_TRANSCRIPT_CACHE_KEY_OK");
    let listed = client
        .get(format!("{restart_base}/v1/derivations"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<DerivationView>>()
        .await?;
    assert_eq!(listed.len(), 2);

    let _ = restart_shutdown.send(());
    Ok(())
}

