#[tokio::test]
async fn daemon_observation_ingress_rate_limits_and_audits_without_tokens() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/observation-sources"))
        .json(&CreateObservationSourceRequest {
            source_id: Some("rate-limited-screen".to_string()),
            display_name: "Rate limited screen".to_string(),
            kind: ObservationSourceKind::ScreenSnapshot,
            upload_token: "rate-limit-token".to_string(),
            sensitivity: ObservationSensitivity::Sensitive,
            retention_seconds: 24 * 60 * 60,
            max_active_observations: 64,
            max_active_bytes: 64 * 1024 * 1024,
            ingest_rate_limit_window_ms: 60_000,
            ingest_rate_limit_burst: 1,
            purge_raw_on_retention: false,
            allow_materialization: true,
            allow_output_delivery: false,
        })
        .send()
        .await?
        .error_for_status()?;

    let malformed_json = client
        .post(format!(
            "{base}/v1/observation-sources/rate-limited-screen/observations"
        ))
        .bearer_auth("rate-limit-token")
        .header(CONTENT_TYPE, "application/json")
        .body("{")
        .send()
        .await?;
    assert_eq!(malformed_json.status(), StatusCode::BAD_REQUEST);
    assert!(
        malformed_json
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = malformed_json.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("observation_ingress"));
    assert_eq!(problem.code, "bad_request");

    let oversized_json = client
        .post(format!(
            "{base}/v1/observation-sources/rate-limited-screen/observations"
        ))
        .bearer_auth("rate-limit-token")
        .header(CONTENT_TYPE, "application/json")
        .body(vec![b' '; 25 * 1024 * 1024])
        .send()
        .await?;
    assert_eq!(oversized_json.status(), StatusCode::PAYLOAD_TOO_LARGE);
    assert!(
        oversized_json
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = oversized_json.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("observation_ingress"));
    assert_eq!(problem.code, "payload_too_large");

    upload_test_observation(
        &client,
        &base,
        "rate-limited-screen",
        "rate-limit-token",
        "first.png",
        "image/png",
        &sample_png_bytes()?,
        "first",
        None,
    )
    .await?;
    let limited = client
        .post(format!(
            "{base}/v1/observation-sources/rate-limited-screen/observations"
        ))
        .bearer_auth("rate-limit-token")
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "second.jpg".to_string(),
                media_type: Some("image/jpeg".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_jpeg_bytes()?),
            },
            idempotency_key: "second".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(limited.status(), StatusCode::TOO_MANY_REQUESTS);
    assert!(
        limited
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = limited.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("observation_ingress"));
    assert_eq!(problem.code, "rate_limited");
    assert!(problem.detail.contains("retry_after_ms="));

    let audit = fs::read_to_string(observation_audit_path(&state_root))?;
    assert!(audit.contains("\"event\":\"source_created\""));
    assert!(audit.contains("\"event\":\"upload_succeeded\""));
    assert!(audit.contains("\"event\":\"upload_rate_limited\""));
    assert!(audit.contains("\"retry_after_ms\":"));
    assert!(!audit.contains("rate-limit-token"));
    assert!(!audit.contains("\"first\""));
    assert!(!audit.contains("\"second\""));
    let listed_audit = client
        .get(format!(
            "{base}/v1/observation-audit?source_id=rate-limited-screen&event=upload_rate_limited&limit=1"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationAuditRecord>>()
        .await?;
    assert_eq!(listed_audit.len(), 1);
    assert_eq!(listed_audit[0].event, "upload_rate_limited");
    assert_eq!(listed_audit[0].reason.as_deref(), Some("rate_limited"));
    assert!(
        listed_audit[0].retry_after_ms.unwrap_or_default() > 0,
        "rate-limit audit should expose retry_after_ms: {}",
        serde_json::to_string_pretty(&listed_audit)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_observation_source_token_rotate_revoke_and_audit_api() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let source = create_test_observation_source(
        &client,
        &base,
        "token-source",
        "Token Source",
        ObservationSourceKind::ScreenSnapshot,
        "token-v1",
    )
    .await?;
    assert_eq!(source.upload_token_version, 1);
    upload_test_observation(
        &client,
        &base,
        "token-source",
        "token-v1",
        "before.png",
        "image/png",
        &sample_png_bytes()?,
        "token-before",
        None,
    )
    .await?;

    let rotated = client
        .post(format!(
            "{base}/v1/observation-sources/token-source/rotate-token"
        ))
        .json(&RotateObservationSourceTokenRequest {
            upload_token: "token-v2".to_string(),
            grace_period_ms: 60_000,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<ObservationSourceView>()
        .await?;
    assert_eq!(rotated.upload_token_version, 2);
    assert!(rotated.upload_token_revoked_at_ms.is_none());

    let old_during_grace = upload_test_observation(
        &client,
        &base,
        "token-source",
        "token-v1",
        "old-grace.png",
        "image/png",
        &sample_png_bytes()?,
        "token-old-grace",
        None,
    )
    .await?;
    assert_eq!(old_during_grace.source_id, "token-source");
    let new_after_rotate = upload_test_observation(
        &client,
        &base,
        "token-source",
        "token-v2",
        "new-token.png",
        "image/png",
        &sample_png_bytes()?,
        "token-new",
        None,
    )
    .await?;
    assert_eq!(new_after_rotate.source_id, "token-source");

    let revoked = client
        .post(format!(
            "{base}/v1/observation-sources/token-source/revoke-token"
        ))
        .json(&RevokeObservationSourceTokenRequest {
            reason: Some("token-v2".to_string()),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<ObservationSourceView>()
        .await?;
    assert!(revoked.upload_token_revoked_at_ms.is_some());

    let same_token_reactivation = client
        .post(format!(
            "{base}/v1/observation-sources/token-source/rotate-token"
        ))
        .json(&RotateObservationSourceTokenRequest {
            upload_token: "token-v2".to_string(),
            grace_period_ms: 0,
        })
        .send()
        .await?;
    assert_eq!(same_token_reactivation.status(), StatusCode::BAD_REQUEST);

    for (token, key) in [
        ("token-v2", "token-revoked-current"),
        ("token-v1", "token-revoked-previous"),
    ] {
        let rejected = client
            .post(format!(
                "{base}/v1/observation-sources/token-source/observations"
            ))
            .bearer_auth(token)
            .json(&CreateObservationRequest {
                upload: InlineAssetUpload {
                    file_name: format!("{key}.png"),
                    media_type: Some("image/png".to_string()),
                    content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
                },
                idempotency_key: key.to_string(),
                captured_at_ms: Some(now_ms()),
                stream_id: None,
                seq_no: None,
                canonical_text: None,
                metadata: Value::Null,
            })
            .send()
            .await?;
        assert_eq!(rejected.status(), StatusCode::UNAUTHORIZED);
    }

    let audit = client
        .get(format!(
            "{base}/v1/observation-audit?source_id=token-source&limit=20"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationAuditRecord>>()
        .await?;
    let events = audit
        .iter()
        .map(|record| record.event.as_str())
        .collect::<Vec<_>>();
    assert!(events.contains(&"source_created"));
    assert!(events.contains(&"source_token_rotated"));
    assert!(events.contains(&"source_token_revoked"));
    assert!(events.contains(&"upload_rejected"));
    let revoke_audit = audit
        .iter()
        .find(|record| record.event == "source_token_revoked")
        .expect("source_token_revoked audit");
    assert_eq!(
        revoke_audit.reason.as_deref(),
        Some("operator_reason_redacted")
    );
    let rendered = serde_json::to_string(&audit)?;
    assert!(!rendered.contains("token-v1"));
    assert!(!rendered.contains("token-v2"));
    assert!(!rendered.contains("token-before"));
    assert!(!rendered.contains("token-new"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_observation_time_retention_expires_without_followup_upload_after_restart()
-> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/observation-sources"))
        .json(&CreateObservationSourceRequest {
            source_id: Some("ttl-source".to_string()),
            display_name: "TTL Source".to_string(),
            kind: ObservationSourceKind::ScreenSnapshot,
            upload_token: "ttl-token".to_string(),
            sensitivity: ObservationSensitivity::Sensitive,
            retention_seconds: 1,
            max_active_observations: 64,
            max_active_bytes: 64 * 1024 * 1024,
            ingest_rate_limit_window_ms: 60_000,
            ingest_rate_limit_burst: 120,
            purge_raw_on_retention: false,
            allow_materialization: true,
            allow_output_delivery: false,
        })
        .send()
        .await?
        .error_for_status()?;
    let observation = upload_test_observation(
        &client,
        &base,
        "ttl-source",
        "ttl-token",
        "ttl.png",
        "image/png",
        &sample_png_bytes()?,
        "ttl-observation",
        None,
    )
    .await?;
    let active = client
        .get(format!("{base}/v1/observations?source_id=ttl-source"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert_eq!(active.len(), 1);
    let _ = shutdown.send(());

    tokio::time::sleep(Duration::from_millis(1_100)).await;
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let active_after_restart = client
        .get(format!("{base}/v1/observations?source_id=ttl-source"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert!(
        active_after_restart.is_empty(),
        "expired observation should be swept before list results: {}",
        serde_json::to_string_pretty(&active_after_restart)?
    );
    let purged = client
        .get(format!(
            "{base}/v1/observations?source_id=ttl-source&include_purged=true"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert_eq!(purged.len(), 1);
    assert_eq!(purged[0].retention_state, ObservationRetentionState::Purged);

    create_test_session(&client, &base, "ttl-materialize-session").await?;
    let materialization = client
        .post(format!("{base}/v1/observation-materializations"))
        .json(&ObservationMaterializationRequest {
            target_session_id: "ttl-materialize-session".to_string(),
            selection: ObservationSelection::ObservationIds {
                observation_ids: vec![observation.observation_id.clone()],
            },
            request: SubmitInputRequest {
                source_plugin: None,
                source_kind: None,
                actor_id: None,
                provider: None,
                content: "Analyze expired observation.".to_string(),
                input_items: Vec::new(),
                attachments: Vec::new(),
                generation: Some(ModelGenerationConfig::default()),
                completion_requirements: None,
                metadata: None,
                reply_address: None,
                binding_keys: Vec::new(),
                reply_targets: Vec::new(),
                reply_plugin: None,
            },
            include_raw_assets: true,
            raw_asset_policy: None,
            fail_when_empty: true,
        })
        .send()
        .await?;
    assert_eq!(materialization.status(), StatusCode::BAD_REQUEST);
    assert!(
        materialization
            .text()
            .await?
            .contains("no longer materializable")
    );

    let derivation = client
        .post(format!("{base}/v1/derivations"))
        .json(&CreateDerivationRequest {
            profile: DerivationProfile::CanonicalText,
            subject: DerivationSubject::Observation {
                observation_id: observation.observation_id,
            },
            transcription: None,
        })
        .send()
        .await?;
    assert_eq!(derivation.status(), StatusCode::BAD_REQUEST);
    assert!(
        derivation
            .text()
            .await?
            .contains("no longer materializable")
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_observation_time_retention_uses_receive_time_not_future_capture_time() -> Result<()>
{
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/observation-sources"))
        .json(&CreateObservationSourceRequest {
            source_id: Some("future-ttl-source".to_string()),
            display_name: "Future TTL Source".to_string(),
            kind: ObservationSourceKind::ScreenSnapshot,
            upload_token: "future-ttl-token".to_string(),
            sensitivity: ObservationSensitivity::Sensitive,
            retention_seconds: 1,
            max_active_observations: 64,
            max_active_bytes: 64 * 1024 * 1024,
            ingest_rate_limit_window_ms: 60_000,
            ingest_rate_limit_burst: 120,
            purge_raw_on_retention: false,
            allow_materialization: true,
            allow_output_delivery: false,
        })
        .send()
        .await?
        .error_for_status()?;
    let future_observation = client
        .post(format!(
            "{base}/v1/observation-sources/future-ttl-source/observations"
        ))
        .bearer_auth("future-ttl-token")
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "future.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "future-ttl-observation".to_string(),
            captured_at_ms: Some(now_ms().saturating_add(10 * 60 * 1000)),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<ObservationView>()
        .await?;
    assert!(future_observation.captured_at_ms > future_observation.received_at_ms);
    let _ = shutdown.send(());

    tokio::time::sleep(Duration::from_millis(1_100)).await;
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");
    let active_after_restart = client
        .get(format!(
            "{base}/v1/observations?source_id=future-ttl-source"
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert!(
        active_after_restart.is_empty(),
        "future captured_at_ms must not extend daemon retention: {}",
        serde_json::to_string_pretty(&active_after_restart)?
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_capture_provisioning_rotates_heartbeats_and_revokes_agents() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let initial_provision_request = CaptureAgentProvisionRequest {
        batch_id: "capture-batch-1".to_string(),
        daemon_base_url: base.clone(),
        os_profile: CaptureOsProfile::Macos,
        agents: vec![
            CaptureAgentProvisionTarget {
                machine_id: "cap-001".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            },
            CaptureAgentProvisionTarget {
                machine_id: "cap-002".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            },
        ],
        sources: CaptureAgentProvisionSources {
            screen: true,
            camera: false,
            system_audio: false,
            microphone: false,
        },
        interval_ms: 5_000,
        max_runs: None,
        duration_ms: None,
        retention_seconds: 3_600,
        max_active_observations: 16,
        max_active_bytes: 16 * 1024 * 1024,
        token_ttl_ms: 60_000,
        heartbeat_interval_ms: 20,
        heartbeat_grace_ms: 20,
    };
    let provision = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&initial_provision_request)
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentProvisionResponse>()
        .await?;
    assert_eq!(provision.agents.len(), 2);
    let cap_001 = provision
        .agents
        .iter()
        .find(|agent| agent.machine_id == "cap-001")
        .expect("cap-001 provisioned");
    let cap_002 = provision
        .agents
        .iter()
        .find(|agent| agent.machine_id == "cap-002")
        .expect("cap-002 provisioned");
    let cap_001_source = &cap_001.sources[0];
    let cap_002_source = &cap_002.sources[0];
    assert_ne!(cap_001_source.upload_token, cap_002_source.upload_token);

    let duplicate_batch_retry = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&initial_provision_request)
        .send()
        .await?;
    assert_eq!(duplicate_batch_retry.status(), StatusCode::CONFLICT);

    let agents = client
        .get(format!("{base}/v1/capture-agents"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<CaptureAgentView>>()
        .await?;
    assert_eq!(agents.len(), 2);
    assert!(
        agents
            .iter()
            .all(|agent| agent.status == CaptureAgentStatus::Active)
    );

    let uploaded = upload_test_observation(
        &client,
        &base,
        &cap_001_source.source_id,
        &cap_001_source.upload_token,
        "cap-001-before-rotate.png",
        "image/png",
        &sample_png_bytes()?,
        "cap-001-before-rotate",
        None,
    )
    .await?;
    assert_eq!(uploaded.source_id, cap_001_source.source_id);

    let heartbeat = client
        .post(format!("{base}/v1/capture-agents/cap-001/heartbeat"))
        .bearer_auth(&cap_001.heartbeat_token)
        .json(&CaptureAgentHeartbeatRequest {
            observed_source_ids: vec![cap_001_source.source_id.clone()],
            agent_version: Some("kheish-capture-agent/test".to_string()),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentHeartbeatResponse>()
        .await?;
    assert_eq!(heartbeat.heartbeat_state, CaptureHeartbeatState::Healthy);
    assert_eq!(
        heartbeat.agent_version.as_deref(),
        Some("kheish-capture-agent/test")
    );
    assert_eq!(
        heartbeat.observed_source_ids,
        vec![cap_001_source.source_id.clone()]
    );
    assert!(heartbeat.unobserved_source_ids.is_empty());

    let cap_001_after_heartbeat = client
        .get(format!("{base}/v1/capture-agents/cap-001"))
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentView>()
        .await?;
    assert_eq!(
        cap_001_after_heartbeat
            .last_heartbeat_agent_version
            .as_deref(),
        Some("kheish-capture-agent/test")
    );
    assert_eq!(
        cap_001_after_heartbeat.last_heartbeat_observed_source_ids,
        vec![cap_001_source.source_id.clone()]
    );
    assert!(
        cap_001_after_heartbeat
            .last_heartbeat_unobserved_source_ids
            .is_empty()
    );

    let upload_token_heartbeat = client
        .post(format!("{base}/v1/capture-agents/cap-001/heartbeat"))
        .bearer_auth(&cap_001_source.upload_token)
        .json(&CaptureAgentHeartbeatRequest::default())
        .send()
        .await?;
    assert_eq!(upload_token_heartbeat.status(), StatusCode::UNAUTHORIZED);
    assert!(
        upload_token_heartbeat
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = upload_token_heartbeat.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("observation_ingress"));
    assert_eq!(problem.code, "unauthorized");

    let invalid_observed_source = client
        .post(format!("{base}/v1/capture-agents/cap-001/heartbeat"))
        .bearer_auth(&cap_001.heartbeat_token)
        .json(&CaptureAgentHeartbeatRequest {
            observed_source_ids: vec![cap_002_source.source_id.clone()],
            agent_version: None,
        })
        .send()
        .await?;
    assert_eq!(invalid_observed_source.status(), StatusCode::BAD_REQUEST);
    assert!(
        invalid_observed_source
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("application/problem+json"))
    );
    let problem = invalid_observed_source.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("observation_ingress"));
    assert_eq!(problem.code, "bad_request");

    let generic_rotate_capture_source = client
        .post(format!(
            "{base}/v1/observation-sources/{}/rotate-token",
            cap_001_source.source_id
        ))
        .json(&RotateObservationSourceTokenRequest {
            upload_token: "generic-rotation-token".to_string(),
            grace_period_ms: 0,
        })
        .send()
        .await?;
    assert_eq!(generic_rotate_capture_source.status(), StatusCode::CONFLICT);

    let generic_revoke_capture_source = client
        .post(format!(
            "{base}/v1/observation-sources/{}/revoke-token",
            cap_001_source.source_id
        ))
        .json(&RevokeObservationSourceTokenRequest {
            reason: Some("generic revoke should be blocked".to_string()),
        })
        .send()
        .await?;
    assert_eq!(generic_revoke_capture_source.status(), StatusCode::CONFLICT);

    let rotated = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&CaptureAgentProvisionRequest {
            batch_id: "capture-batch-rotate".to_string(),
            daemon_base_url: base.clone(),
            os_profile: CaptureOsProfile::Macos,
            agents: vec![CaptureAgentProvisionTarget {
                machine_id: "cap-001".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            }],
            sources: CaptureAgentProvisionSources {
                screen: true,
                camera: false,
                system_audio: false,
                microphone: false,
            },
            interval_ms: 5_000,
            max_runs: None,
            duration_ms: None,
            retention_seconds: 3_600,
            max_active_observations: 16,
            max_active_bytes: 16 * 1024 * 1024,
            token_ttl_ms: 60_000,
            heartbeat_interval_ms: 20,
            heartbeat_grace_ms: 20,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentProvisionResponse>()
        .await?;
    let rotated_source = &rotated.agents[0].sources[0];
    assert_eq!(rotated_source.source_id, cap_001_source.source_id);
    assert_ne!(rotated_source.upload_token, cap_001_source.upload_token);

    let old_token = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            cap_001_source.source_id
        ))
        .bearer_auth(&cap_001_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-001-old-token.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-001-old-token".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(old_token.status(), StatusCode::UNAUTHORIZED);

    let cap_002_reprofiled = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&CaptureAgentProvisionRequest {
            batch_id: "capture-batch-cap-002-mic".to_string(),
            daemon_base_url: base.clone(),
            os_profile: CaptureOsProfile::Macos,
            agents: vec![CaptureAgentProvisionTarget {
                machine_id: "cap-002".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            }],
            sources: CaptureAgentProvisionSources {
                screen: false,
                camera: false,
                system_audio: false,
                microphone: true,
            },
            interval_ms: 5_000,
            max_runs: None,
            duration_ms: None,
            retention_seconds: 3_600,
            max_active_observations: 16,
            max_active_bytes: 16 * 1024 * 1024,
            token_ttl_ms: 60_000,
            heartbeat_interval_ms: 20,
            heartbeat_grace_ms: 20,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentProvisionResponse>()
        .await?;
    assert!(
        cap_002_reprofiled.agents[0]
            .sources
            .iter()
            .any(|source| source.kind == ObservationSourceKind::MicrophoneSegment)
    );

    let retired_heartbeat = client
        .post(format!("{base}/v1/capture-agents/cap-002/heartbeat"))
        .bearer_auth(&cap_002.heartbeat_token)
        .json(&CaptureAgentHeartbeatRequest::default())
        .send()
        .await?;
    assert_eq!(retired_heartbeat.status(), StatusCode::UNAUTHORIZED);

    let retired_upload = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            cap_002_source.source_id
        ))
        .bearer_auth(&cap_002_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-002-retired-source.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-002-retired-source".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(retired_upload.status(), StatusCode::UNAUTHORIZED);

    let after_rotation = upload_test_observation(
        &client,
        &base,
        &rotated_source.source_id,
        &rotated_source.upload_token,
        "cap-001-after-rotate.png",
        "image/png",
        &sample_png_bytes()?,
        "cap-001-after-rotate",
        None,
    )
    .await?;
    assert_eq!(after_rotation.source_id, rotated_source.source_id);

    tokio::time::sleep(Duration::from_millis(60)).await;
    let refreshed_heartbeat = client
        .post(format!("{base}/v1/capture-agents/cap-001/heartbeat"))
        .bearer_auth(&rotated.agents[0].heartbeat_token)
        .json(&CaptureAgentHeartbeatRequest::default())
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentHeartbeatResponse>()
        .await?;
    assert_eq!(
        refreshed_heartbeat.heartbeat_state,
        CaptureHeartbeatState::Healthy
    );

    let alerts = client
        .get(format!("{base}/v1/capture-alerts"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<CaptureAgentAlertView>>()
        .await?;
    assert!(alerts.iter().any(|alert| alert.machine_id == "cap-002"));
    assert!(!alerts.iter().any(|alert| alert.machine_id == "cap-001"));
    let cap_002_missing_detected_at = alerts
        .iter()
        .find(|alert| alert.machine_id == "cap-002")
        .expect("cap-002 missing heartbeat")
        .detected_at_ms;
    tokio::time::sleep(Duration::from_millis(5)).await;
    let alerts_again = client
        .get(format!("{base}/v1/capture-alerts"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<CaptureAgentAlertView>>()
        .await?;
    assert_eq!(
        alerts_again
            .iter()
            .find(|alert| alert.machine_id == "cap-002")
            .expect("cap-002 missing heartbeat remains")
            .detected_at_ms,
        cap_002_missing_detected_at
    );

    let revoked = client
        .post(format!("{base}/v1/capture-agents/cap-001/revoke"))
        .json(&RevokeCaptureAgentRequest {
            reason: Some(format!("Bearer {}", rotated_source.upload_token)),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentView>()
        .await?;
    assert_eq!(revoked.status, CaptureAgentStatus::Revoked);
    assert_eq!(revoked.heartbeat_state, CaptureHeartbeatState::Revoked);
    assert_eq!(
        revoked.revoked_reason.as_deref(),
        Some("operator_reason_redacted")
    );

    let revoked_upload = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            rotated_source.source_id
        ))
        .bearer_auth(&rotated_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-001-revoked.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-001-revoked".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(revoked_upload.status(), StatusCode::UNAUTHORIZED);

    let expiring = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&CaptureAgentProvisionRequest {
            batch_id: "capture-batch-expiring".to_string(),
            daemon_base_url: base.clone(),
            os_profile: CaptureOsProfile::Macos,
            agents: vec![CaptureAgentProvisionTarget {
                machine_id: "cap-expiring".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            }],
            sources: CaptureAgentProvisionSources {
                screen: true,
                camera: false,
                system_audio: false,
                microphone: false,
            },
            interval_ms: 5_000,
            max_runs: None,
            duration_ms: None,
            retention_seconds: 3_600,
            max_active_observations: 16,
            max_active_bytes: 16 * 1024 * 1024,
            token_ttl_ms: 1,
            heartbeat_interval_ms: 10_000,
            heartbeat_grace_ms: 10_000,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentProvisionResponse>()
        .await?;
    let expiring_source = &expiring.agents[0].sources[0];
    tokio::time::sleep(Duration::from_millis(5)).await;
    let expired_upload = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            expiring_source.source_id
        ))
        .bearer_auth(&expiring_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-expired.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-expired".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(expired_upload.status(), StatusCode::UNAUTHORIZED);

    let fail_closed = client
        .post(format!("{base}/v1/capture-agent-provisions"))
        .json(&CaptureAgentProvisionRequest {
            batch_id: "capture-batch-fail-closed".to_string(),
            daemon_base_url: base.clone(),
            os_profile: CaptureOsProfile::Macos,
            agents: vec![CaptureAgentProvisionTarget {
                machine_id: "cap-fail-closed".to_string(),
                os_profile: None,
                camera_unique_id: None,
                camera_name: None,
                microphone_name: None,
            }],
            sources: CaptureAgentProvisionSources {
                screen: true,
                camera: false,
                system_audio: false,
                microphone: false,
            },
            interval_ms: 5_000,
            max_runs: None,
            duration_ms: None,
            retention_seconds: 3_600,
            max_active_observations: 16,
            max_active_bytes: 16 * 1024 * 1024,
            token_ttl_ms: 60_000,
            heartbeat_interval_ms: 10_000,
            heartbeat_grace_ms: 10_000,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentProvisionResponse>()
        .await?;
    let fail_closed_source = fail_closed.agents[0].sources[0].clone();

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    let fail_closed_agent_path = resolve_storage_path_for_read(
        &state_root.join("capture-agents"),
        "cap-fail-closed",
        "json",
    );
    fs::remove_file(&fail_closed_agent_path)?;

    let cap_002_agent_path =
        resolve_storage_path_for_read(&state_root.join("capture-agents"), "cap-002", "json");
    let mut cap_002_agent: Value = serde_json::from_str(&fs::read_to_string(&cap_002_agent_path)?)?;
    let partial_revoke_at_ms = now_ms();
    cap_002_agent["view"]["status"] = json!("revoked");
    cap_002_agent["view"]["heartbeat_state"] = json!("revoked");
    cap_002_agent["view"]["revoked_at_ms"] = json!(partial_revoke_at_ms);
    cap_002_agent["view"]["revoked_reason"] = json!("operator_reason_redacted");
    if let Some(leases) = cap_002_agent["leases"].as_array_mut() {
        for lease in leases {
            lease["view"]["revoked_at_ms"] = json!(partial_revoke_at_ms);
        }
    }
    if let Some(leases) = cap_002_agent["view"]["leases"].as_array_mut() {
        for lease in leases {
            lease["revoked_at_ms"] = json!(partial_revoke_at_ms);
        }
    }
    fs::write(
        &cap_002_agent_path,
        serde_json::to_vec_pretty(&cap_002_agent)?,
    )?;

    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let base = format!("http://{address}");

    let fail_closed_upload = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            fail_closed_source.source_id
        ))
        .bearer_auth(&fail_closed_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-fail-closed.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-fail-closed".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(fail_closed_upload.status(), StatusCode::UNAUTHORIZED);

    let repaired_cap_002 = client
        .post(format!("{base}/v1/capture-agents/cap-002/revoke"))
        .json(&RevokeCaptureAgentRequest {
            reason: Some("api-key: capture-secret-value".to_string()),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<CaptureAgentView>()
        .await?;
    assert_eq!(
        repaired_cap_002.revoked_reason.as_deref(),
        Some("operator_reason_redacted")
    );
    let repaired_source = client
        .get(format!(
            "{base}/v1/observation-sources/{}",
            cap_002_source.source_id
        ))
        .send()
        .await?
        .error_for_status()?
        .json::<ObservationSourceView>()
        .await?;
    assert_eq!(repaired_source.status, ObservationSourceStatus::Disabled);
    let repaired_upload = client
        .post(format!(
            "{base}/v1/observation-sources/{}/observations",
            cap_002_source.source_id
        ))
        .bearer_auth(&cap_002_source.upload_token)
        .json(&CreateObservationRequest {
            upload: InlineAssetUpload {
                file_name: "cap-002-repaired-revoke.png".to_string(),
                media_type: Some("image/png".to_string()),
                content_base64: BASE64_STANDARD.encode(sample_png_bytes()?),
            },
            idempotency_key: "cap-002-repaired-revoke".to_string(),
            captured_at_ms: Some(now_ms()),
            stream_id: None,
            seq_no: None,
            canonical_text: None,
            metadata: Value::Null,
        })
        .send()
        .await?;
    assert_eq!(repaired_upload.status(), StatusCode::UNAUTHORIZED);

    let audit = fs::read_to_string(observation_audit_path(&state_root))?;
    assert!(audit.contains("\"event\":\"capture_agent_provisioned\""));
    assert!(audit.contains("\"event\":\"capture_agent_heartbeat_missing\""));
    assert!(audit.contains("\"event\":\"capture_agent_revoked\""));
    assert!(audit.contains("\"event\":\"capture_agent_revoke_repaired\""));
    assert!(audit.contains("\"reason\":\"operator_reason_redacted\""));
    assert!(!audit.contains("capture-secret-value"));
    assert!(!audit.contains(&cap_001_source.upload_token));
    assert!(!audit.contains(&cap_001.heartbeat_token));
    assert!(!audit.contains(&rotated_source.upload_token));
    assert!(!audit.contains(&rotated.agents[0].heartbeat_token));
    assert!(!audit.contains(&cap_002_source.upload_token));
    assert!(!audit.contains(&cap_002.heartbeat_token));
    assert!(!audit.contains(&cap_002_reprofiled.agents[0].sources[0].upload_token));
    assert!(!audit.contains(&cap_002_reprofiled.agents[0].heartbeat_token));
    assert!(!audit.contains(&expiring_source.upload_token));
    assert!(!audit.contains(&fail_closed_source.upload_token));
    assert!(!audit.contains(&fail_closed.agents[0].heartbeat_token));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_observation_retention_can_purge_raw_assets() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/observation-sources"))
        .json(&CreateObservationSourceRequest {
            source_id: Some("purge-raw-screen".to_string()),
            display_name: "Purge raw screen".to_string(),
            kind: ObservationSourceKind::ScreenSnapshot,
            upload_token: "purge-raw-token".to_string(),
            sensitivity: ObservationSensitivity::Sensitive,
            retention_seconds: 24 * 60 * 60,
            max_active_observations: 1,
            max_active_bytes: 64 * 1024 * 1024,
            ingest_rate_limit_window_ms: 60_000,
            ingest_rate_limit_burst: 120,
            purge_raw_on_retention: true,
            allow_materialization: true,
            allow_output_delivery: false,
        })
        .send()
        .await?
        .error_for_status()?;

    let old = upload_test_observation(
        &client,
        &base,
        "purge-raw-screen",
        "purge-raw-token",
        "old.png",
        "image/png",
        &sample_png_bytes()?,
        "old",
        None,
    )
    .await?;
    let _new = upload_test_observation(
        &client,
        &base,
        "purge-raw-screen",
        "purge-raw-token",
        "new.jpg",
        "image/jpeg",
        &sample_jpeg_bytes()?,
        "new",
        None,
    )
    .await?;

    let purged_raw = client
        .get(format!("{base}/v1/assets/{}/raw", old.asset_id))
        .send()
        .await?;
    assert_eq!(purged_raw.status(), StatusCode::NOT_FOUND);
    let listed = client
        .get(format!("{base}/v1/observations?include_purged=true"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert!(
        listed
            .iter()
            .any(|view| view.observation_id == old.observation_id
                && view.retention_state == ObservationRetentionState::Purged)
    );
    let audit = fs::read_to_string(observation_audit_path(&state_root))?;
    assert!(audit.contains("\"event\":\"retention_purged_assets\""));
    assert!(audit.contains(&old.asset_id));
    assert!(!audit.contains("purge-raw-token"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_observation_retention_preserves_board_referenced_assets() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/observation-sources"))
        .json(&CreateObservationSourceRequest {
            source_id: Some("board-retention-screen".to_string()),
            display_name: "Board retention screen".to_string(),
            kind: ObservationSourceKind::ScreenSnapshot,
            upload_token: "board-retention-token".to_string(),
            sensitivity: ObservationSensitivity::Sensitive,
            retention_seconds: 24 * 60 * 60,
            max_active_observations: 1,
            max_active_bytes: 64 * 1024 * 1024,
            ingest_rate_limit_window_ms: 60_000,
            ingest_rate_limit_burst: 120,
            purge_raw_on_retention: true,
            allow_materialization: true,
            allow_output_delivery: false,
        })
        .send()
        .await?
        .error_for_status()?;

    let old = upload_test_observation(
        &client,
        &base,
        "board-retention-screen",
        "board-retention-token",
        "old-board-render.png",
        "image/png",
        &sample_png_bytes()?,
        "old-board-render",
        None,
    )
    .await?;
    let board = client
        .post(format!("{base}/v1/boards"))
        .json(&CreateBoardRequest {
            board_id: Some("board-retention".to_string()),
            display_name: "Board retention".to_string(),
            owner_session_id: None,
            metadata: Value::Null,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<BoardView>()
        .await?;
    assert_eq!(board.summary.board_id, "board-retention");
    let revision = client
        .post(format!("{base}/v1/boards/board-retention/revisions"))
        .json(&CreateBoardRevisionRequest {
            previous_revision_id: None,
            client_revision_id: Some("board-retention-rev-1".to_string()),
            render_asset_id: old.asset_id.clone(),
            state_asset_id: None,
            note: Some("protected old observation render".to_string()),
            source_session_id: None,
            source_run_id: None,
            metadata: Value::Null,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<BoardRevisionView>()
        .await?;
    assert_eq!(revision.render_asset_id, old.asset_id);

    let _new = upload_test_observation(
        &client,
        &base,
        "board-retention-screen",
        "board-retention-token",
        "new-board-render.jpg",
        "image/jpeg",
        &sample_jpeg_bytes()?,
        "new-board-render",
        None,
    )
    .await?;

    let protected_raw = client
        .get(format!("{base}/v1/assets/{}/raw", old.asset_id))
        .send()
        .await?;
    assert_eq!(protected_raw.status(), StatusCode::OK);
    let listed = client
        .get(format!("{base}/v1/observations?include_purged=true"))
        .send()
        .await?
        .error_for_status()?
        .json::<Vec<ObservationView>>()
        .await?;
    assert!(
        listed
            .iter()
            .any(|view| view.observation_id == old.observation_id
                && view.retention_state == ObservationRetentionState::Purged)
    );
    let board_after: BoardView = client
        .get(format!("{base}/v1/boards/board-retention"))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert_eq!(board_after.summary.revision_count, 1);

    let _ = shutdown.send(());
    Ok(())
}

fn assert_asset_reference(view: &AssetReferencesView, domain: &str, role: &str, hard: bool) {
    assert!(
        view.references
            .iter()
            .any(|reference| reference.domain == domain
                && reference.role == role
                && reference.hard == hard),
        "missing asset reference domain={domain} role={role} hard={hard} in {view:#?}"
    );
}

#[tokio::test]
async fn daemon_asset_references_include_provenance_source_assets_as_soft_refs() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (source_id, result_id) = {
        let assets = crate::assets::FileAssetStore::new(&state_root)?;
        let source = assets.import_bytes(
            "source.png",
            Some("image/png"),
            &sample_png_bytes_with_color([12, 34, 56])?,
        )?;
        let result = assets.import_bytes_with_provenance(
            "edited.png",
            Some("image/png"),
            &sample_png_bytes_with_color([56, 34, 12])?,
            Some(crate::assets::AssetProvenanceRecord {
                kind: "image_edit".to_string(),
                tool_name: "edit_image".to_string(),
                session_id: Some("asset-provenance-session".to_string()),
                run_id: Some("run-provenance".to_string()),
                tool_call_id: Some("call-provenance".to_string()),
                route_id: Some("test-route".to_string()),
                provider: "test-provider".to_string(),
                model: "test-model".to_string(),
                prompt_sha256: kheish_codec::digest_text("edit source"),
                source_assets: vec![crate::assets::AssetProvenanceSourceRecord {
                    asset_id: source.id.clone(),
                    media_type: source.media_type.clone(),
                    sha256: source.sha256.clone(),
                }],
                output_index: 1,
                output_count: 1,
            }),
        )?;
        (source.id, result.id)
    };
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let references = client
        .get(format!("{base}/v1/assets/{source_id}/references"))
        .send()
        .await?
        .error_for_status()?
        .json::<AssetReferencesView>()
        .await?;
    let provenance_reference = references
        .references
        .iter()
        .find(|reference| {
            reference.domain == "assets"
                && reference.owner_id == result_id
                && reference.role == "provenance_source_asset"
                && !reference.hard
        })
        .ok_or_else(|| anyhow!("missing provenance source asset reference: {references:#?}"))?;
    assert_eq!(
        provenance_reference.detail_id.as_deref(),
        Some("image_edit")
    );

    let _ = shutdown.send(());
    Ok(())
}

