#[tokio::test]
async fn daemon_runtime_hooks_roundtrip_and_can_block_user_input() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(
        &state_root,
        vec![Ok(scripted_events(
            "assistant-unused",
            "UNUSED",
            kheish_types::ModelFinishReason::Completed,
        ))],
    )
    .await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let hooks = HookSettings {
        hooks: std::iter::once((
            HookEventName::UserPromptSubmit,
            vec![kheish_types::HookDefinition {
                name: "block-input".to_string(),
                matcher: None,
                failure_policy: Default::default(),
                executor: kheish_types::HookExecutorConfig::Command {
                    command: "exit 2".to_string(),
                    shell: None,
                    timeout_ms: Some(1_000),
                },
            }],
        ))
        .collect(),
    };
    let runtime = client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&hooks)
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_ne!(runtime.hooks, hooks);
    let rendered_runtime = serde_json::to_string(&runtime.hooks)?;
    assert!(!rendered_runtime.contains("exit 2"));

    let loaded = client
        .get(format!("{base}/v1/runtime/hooks"))
        .send()
        .await?
        .error_for_status()?
        .json::<HookSettings>()
        .await?;
    assert_eq!(loaded, hooks);

    client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("hook-block-session".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?;

    let blocked = client
        .post(format!("{base}/v1/sessions/hook-block-session/input"))
        .json(&SubmitInputRequest {
            source_plugin: None,
            source_kind: None,
            actor_id: None,
            provider: None,
            content: "blocked".to_string(),
            input_items: Vec::new(),
            attachments: Vec::new(),
            generation: Some(ModelGenerationConfig::default()),
            completion_requirements: None,
            metadata: None,
            reply_address: None,
            binding_keys: Vec::new(),
            reply_targets: Vec::new(),
            reply_plugin: None,
        })
        .send()
        .await?;
    assert_eq!(blocked.status(), StatusCode::FORBIDDEN);
    let problem = blocked.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("hooks"));
    assert_eq!(problem.code, "hook_blocked");
    assert!(problem.detail.contains("blocked"));

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_runtime_hooks_reject_invalid_http_target_without_persisting() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    for url in [
        "http://localhost:9/hook?token=secret",
        "http://127.0.0.1:9/hook",
        "http://169.254.169.254/latest/meta-data",
        "http://192.0.0.1/hook",
        "http://[::ffff:127.0.0.1]/hook",
    ] {
        let invalid_hooks = HookSettings {
            hooks: std::iter::once((
                HookEventName::Notification,
                vec![kheish_types::HookDefinition {
                    name: "local-http".to_string(),
                    matcher: None,
                    failure_policy: Default::default(),
                    executor: kheish_types::HookExecutorConfig::Http {
                        url: url.to_string(),
                        timeout_ms: Some(1_000),
                    },
                }],
            ))
            .collect(),
        };
        let response = client
            .post(format!("{base}/v1/runtime/hooks"))
            .json(&invalid_hooks)
            .send()
            .await?;
        assert_eq!(response.status(), StatusCode::BAD_REQUEST, "{url}");
        let problem = response.json::<ProblemDetails>().await?;
        assert_eq!(problem.domain.as_deref(), Some("runtime"));
        assert_eq!(problem.code, "invalid_hook_settings");

        let loaded = client
            .get(format!("{base}/v1/runtime/hooks"))
            .send()
            .await?
            .error_for_status()?
            .json::<HookSettings>()
            .await?;
        assert_eq!(loaded, HookSettings::default());
    }

    let _ = shutdown.send(());
    Ok(())
}

