#[tokio::test]
async fn daemon_session_end_and_worktree_hooks_execute() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    std::fs::create_dir_all(state_root.join("hooks-worktree"))?;
    let worktree_create_path = temp.path().join("worktree-create.log");
    let worktree_remove_path = temp.path().join("worktree-remove.log");
    let session_end_path = temp.path().join("session-end.log");
    let create_command = format!(
        "cat >/dev/null; printf 'worktree-create' >> {}",
        worktree_create_path.display()
    );
    let remove_command = format!(
        "cat >/dev/null; printf 'worktree-remove' >> {}",
        worktree_remove_path.display()
    );
    let session_end_command = format!(
        "cat >/dev/null; printf 'session-end' >> {}",
        session_end_path.display()
    );
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    client
        .post(format!("{base}/v1/runtime/hooks"))
        .json(&HookSettings {
            hooks: BTreeMap::from([
                (
                    HookEventName::WorktreeCreate,
                    vec![kheish_types::HookDefinition {
                        name: "worktree-create".to_string(),
                        matcher: None,
                        failure_policy: Default::default(),
                        executor: kheish_types::HookExecutorConfig::Command {
                            command: create_command,
                            shell: None,
                            timeout_ms: Some(1_000),
                        },
                    }],
                ),
                (
                    HookEventName::WorktreeRemove,
                    vec![kheish_types::HookDefinition {
                        name: "worktree-remove".to_string(),
                        matcher: None,
                        failure_policy: Default::default(),
                        executor: kheish_types::HookExecutorConfig::Command {
                            command: remove_command,
                            shell: None,
                            timeout_ms: Some(1_000),
                        },
                    }],
                ),
                (
                    HookEventName::SessionEnd,
                    vec![kheish_types::HookDefinition {
                        name: "session-end".to_string(),
                        matcher: None,
                        failure_policy: Default::default(),
                        executor: kheish_types::HookExecutorConfig::Command {
                            command: session_end_command,
                            shell: None,
                            timeout_ms: Some(1_000),
                        },
                    }],
                ),
            ]),
        })
        .send()
        .await?
        .error_for_status()?;

    let root = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("hooks-root".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&SpawnSidechainRequest {
            session_id: Some("hooks-child".to_string()),
            thread_id: Some("thread-worktree".to_string()),
            route_policy: None,
            provider: None,
            permission_mode: None,
            retention: None,
            nickname: None,
            spawned_by_run_id: None,
            spawn_request_id: None,
            fork_context: ForkContext {
                parent_assistant_message: String::new(),
                inherited_tool_call_ids: Vec::new(),
                team_name: Some("reviewer".to_string()),
                isolation: Some("worktree".to_string()),
                system_prompt: String::new(),
                prompt_merge_mode: kheish_runtime::PromptMergeMode::Replace,
                provider: None,
                generation: None,
                tool_surface: kheish_types::ToolSurfaceFilter::default(),
                worktree_path: Some(state_root.join("hooks-worktree").display().to_string()),
            },
            generation: None,
            tool_surface: None,
            capability_scope: None,
            credential_scope: None,
            subtask: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(child.session_id, "hooks-child");
    assert_eq!(
        std::fs::read_to_string(&worktree_create_path)?,
        "worktree-create"
    );

    client
        .post(format!("{base}/v1/sessions/hooks-child/end"))
        .json(&EndSessionRequest {
            reason: Some("done".to_string()),
        })
        .send()
        .await?
        .error_for_status()?;

    assert_eq!(std::fs::read_to_string(&session_end_path)?, "session-end");
    assert_eq!(
        std::fs::read_to_string(&worktree_remove_path)?,
        "worktree-remove"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_managed_sidechain_worktree_is_created_and_removed() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    init_test_git_repo(&state_root)?;
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("managed-worktree-root".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let mut request =
        bare_sidechain_request("managed-worktree-child", Some("thread-worktree"), None);
    request.fork_context.team_name = Some("reviewer".to_string());
    request.fork_context.isolation = Some("worktree".to_string());

    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert_eq!(child.session_id, "managed-worktree-child");
    let ownership = child
        .snapshot
        .agent
        .daemon_owned_worktree
        .as_ref()
        .expect("daemon-owned worktree metadata");
    let worktree_path = PathBuf::from(&ownership.path);
    assert!(
        worktree_path.starts_with(state_root.join(".kheish-agent-worktrees")),
        "daemon-owned worktree should be under the reserved root: {}",
        worktree_path.display()
    );
    assert_eq!(
        child
            .snapshot
            .agent
            .fork_context
            .as_ref()
            .and_then(|context| context.worktree_path.as_deref()),
        Some(ownership.path.as_str())
    );
    assert!(worktree_path.join(".git").exists());
    assert_eq!(
        fs::read_to_string(worktree_path.join("README.md"))?,
        "kheish test repo\n"
    );

    let ended = client
        .post(format!("{base}/v1/sessions/managed-worktree-child/end"))
        .json(&EndSessionRequest {
            reason: Some("done".to_string()),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(ended.snapshot.agent.closed_at_ms.is_some());
    assert!(
        !worktree_path.exists(),
        "daemon-managed sidechain worktree should be removed on session end"
    );

    let _ = shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_startup_reclaims_orphaned_daemon_owned_worktrees() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    init_test_git_repo(&state_root)?;
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("worktree-gc-root".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;

    let mut request = bare_sidechain_request("worktree-gc-child", Some("thread-worktree-gc"), None);
    request.fork_context.isolation = Some("worktree".to_string());

    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let ownership = child
        .snapshot
        .agent
        .daemon_owned_worktree
        .clone()
        .expect("daemon-owned worktree metadata");
    let worktree_path = PathBuf::from(&ownership.path);
    assert!(worktree_path.join(".git").exists());

    let ended = client
        .post(format!("{base}/v1/sessions/worktree-gc-child/end"))
        .json(&EndSessionRequest {
            reason: Some("done".to_string()),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(ended.snapshot.agent.closed_at_ms.is_some());
    assert!(!worktree_path.exists());
    let _ = shutdown.send(());

    // Simulate a crash between settle and cleanup: the closed agent record
    // still carries the ownership metadata, so recreate the worktree it
    // points at as git would have left it.
    let recreate = std::process::Command::new("git")
        .arg("-C")
        .arg(&state_root)
        .args(["worktree", "add", "--detach"])
        .arg(&worktree_path)
        .arg("HEAD")
        .output()?;
    assert!(
        recreate.status.success(),
        "failed to recreate orphan worktree: {}",
        String::from_utf8_lossy(&recreate.stderr)
    );
    assert!(worktree_path.join(".git").exists());

    // A fresh daemon on the same state reclaims the orphan at startup.
    let (_restart_address, restart_shutdown) =
        echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    assert!(
        !worktree_path.exists(),
        "startup GC should reclaim the orphaned daemon-owned worktree"
    );

    let _ = restart_shutdown.send(());
    Ok(())
}

#[tokio::test]
async fn daemon_boots_when_an_open_agents_worktree_vanished() -> Result<()> {
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-state");
    init_test_git_repo(&state_root)?;
    let (address, shutdown) = echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let root = client
        .post(format!("{base}/v1/sessions"))
        .json(&CreateSessionRequest {
            session_id: Some("worktree-vanish-root".to_string()),
            thread_id: None,
            persona_id: None,
            credential_scope: None,
            capability_scope: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let mut request = bare_sidechain_request(
        "worktree-vanish-child",
        Some("thread-worktree-vanish"),
        None,
    );
    request.fork_context.isolation = Some("worktree".to_string());
    let child = client
        .post(format!("{base}/v1/agents/{}/sidechains", root.agent_id))
        .json(&request)
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    let ownership = child
        .snapshot
        .agent
        .daemon_owned_worktree
        .clone()
        .expect("daemon-owned worktree metadata");
    let worktree_path = PathBuf::from(&ownership.path);
    assert!(worktree_path.join(".git").exists());

    let _ = shutdown.send(());
    wait_for_daemon_shutdown(&client, &base).await?;

    // The agent record is still open, but its worktree disappeared behind the
    // daemon's back (external cleanup, tmp reaper, manual rm). Boot must
    // degrade to a warning instead of refusing to start.
    fs::remove_dir_all(&worktree_path)?;
    let prune = std::process::Command::new("git")
        .arg("-C")
        .arg(&state_root)
        .args(["worktree", "prune"])
        .output()?;
    assert!(prune.status.success());

    let (restart_address, restart_shutdown) =
        echoing_delay_daemon(&state_root, Duration::from_millis(25)).await?;
    let restart_base = format!("http://{restart_address}");
    let status: DaemonStatusView = client
        .get(format!("{restart_base}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert!(
        status.ready,
        "daemon must boot despite the vanished worktree"
    );
    let child_after = client
        .get(format!("{restart_base}/v1/sessions/worktree-vanish-child"))
        .send()
        .await?
        .error_for_status()?
        .json::<SessionView>()
        .await?;
    assert!(child_after.snapshot.agent.closed_at_ms.is_none());
    let _ = restart_shutdown.send(());
    Ok(())
}

