#[tokio::test]
async fn daemon_runtime_rollback_rejects_invalid_debug_redaction_config() -> Result<()> {
    let clean_env = DebugCaptureEnvGuard::without_debug_env();
    let temp = tempdir()?;
    let state_root = temp.path().join("daemon-invalid-redaction-rollback");
    let (address, shutdown) = scripted_daemon(&state_root, Vec::new()).await?;
    let client = Client::new();
    let base = format!("http://{address}");

    let debug_full = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Full,
            expected_revision: None,
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(debug_full.config.revision, 1);
    assert_eq!(debug_full.debug_level, DebugCaptureLevel::Full);

    let debug_off = client
        .post(format!("{base}/v1/runtime/debug-level"))
        .json(&SetDebugLevelRequest {
            level: DebugCaptureLevel::Off,
            expected_revision: Some(debug_full.config.revision),
        })
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(debug_off.config.revision, 2);
    assert_eq!(debug_off.debug_level, DebugCaptureLevel::Off);

    let missing_token_file = temp.path().join("missing-rollback-redaction-tokens.txt");
    drop(clean_env);
    let _env = DebugCaptureEnvGuard::invalid_redaction_file(&missing_token_file);
    let response = client
        .post(format!("{base}/v1/runtime/rollback"))
        .json(&RuntimeRollbackRequest {
            target_revision: Some(debug_full.config.revision),
            expected_revision: Some(debug_off.config.revision),
            skip_hooks: true,
        })
        .send()
        .await?;
    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    let problem = response.json::<ProblemDetails>().await?;
    assert_eq!(problem.domain.as_deref(), Some("runtime"));
    assert_eq!(problem.code, "debug_redaction_config_invalid");

    let runtime = client
        .get(format!("{base}/v1/runtime"))
        .send()
        .await?
        .error_for_status()?
        .json::<RuntimeSettingsView>()
        .await?;
    assert_eq!(runtime.config.revision, debug_off.config.revision);
    assert_eq!(runtime.debug_level, DebugCaptureLevel::Off);

    let _ = shutdown.send(());
    Ok(())
}

